\section{Affine Varieties}

Fix an algebraically closed field $k$, put $A=k[x_1,\ldots,x_n]$, and write
\(\mathbb A^n=k^n\).  For $T\subset A$, set
\[
Z(T)=\{P\in\mathbb A^n:f(P)=0\text{ for every }f\in T\}.
\]

\begin{definition}[Polynomial evaluation and zero sets]
\label{def:ha-ch1-polynomial-evaluation}
\source{hartshorne-algebraic-geometry:I.1}
\lean{Hartshorne.AffinePoint, Hartshorne.AffinePolynomial, Hartshorne.evaluate,
Hartshorne.zeroSet, Hartshorne.commonZeroSet, Hartshorne.commonZeroSet_span,
Hartshorne.commonZeroSet_span_finite}
\leanok
For $P=(a_1,\ldots,a_n)\in\mathbb A^n$ and $f\in A$, regard $f$ as the function
$f(P)=f(a_1,\ldots,a_n)$.  For one polynomial write
$Z(f)=\{P\in\mathbb A^n:f(P)=0\}$, and for a subset $T\subseteq A$ write $Z(T)$
for the common zero set displayed above.  If $\mathfrak a=(T)$, then
$Z(T)=Z(\mathfrak a)$; since $A$ is noetherian, $\mathfrak a$ has finitely many generators.
\end{definition}

\begin{definition}[Algebraic set]
\label{def:ha-ch1-algebraic-set}
\source{hartshorne-algebraic-geometry:I.1}
\lean{Hartshorne.IsAlgebraicSet, Hartshorne.isAlgebraicSet_iff}
\leanok
A subset $Y\subseteq\mathbb A^n$ is algebraic if and only if $Y=Z(T)$ for some subset
$T\subseteq A$.
\uses{def:ha-ch1-polynomial-evaluation}
\end{definition}

\begin{proposition}[Affine algebraic sets]
\label{prop:ha-ch1-1-1}
\source{hartshorne-algebraic-geometry:I.1.1}
\dcref{I.1.1}
The union of two algebraic sets and every intersection of algebraic sets are algebraic; so are
$\varnothing$ and $\mathbb A^n$.
\uses{def:ha-ch1-algebraic-set,def:ha-ch1-polynomial-evaluation}
\end{proposition}
\begin{proof}
If $Y_i=Z(T_i)$, then $Y_1\cup Y_2=Z(T_1T_2)$, where $T_1T_2$ consists of all products
of one element from each set.  Also $\bigcap_\alpha Z(T_\alpha)=Z(\bigcup_\alpha T_\alpha)$,
while $Z(1)=\varnothing$ and $Z(0)=\mathbb A^n$.
\end{proof}

\begin{definition}[Zariski topology]
\label{def:ha-ch1-zariski-topology}
\source{hartshorne-algebraic-geometry:I.1}
The Zariski topology on $\mathbb A^n$ is the topology whose closed subsets are the algebraic
sets; equivalently, the complements of the sets $Z(T)$ are the open subsets.
\uses{def:ha-ch1-algebraic-set}
\end{definition}

\begin{definition}[Irreducible subset]
\label{def:ha-ch1-irreducible-subset}
\source{hartshorne-algebraic-geometry:I.1}
A nonempty subset $Y$ of a topological space is irreducible if it is not the union of two proper
closed subsets (with the induced topology). The empty set is not irreducible.
\end{definition}

\begin{definition}[Affine algebraic variety]
\label{def:ha-ch1-affine-variety}
\source{hartshorne-algebraic-geometry:I.1}
An affine algebraic variety is an irreducible algebraic set.
\uses{def:ha-ch1-algebraic-set,def:ha-ch1-irreducible-subset}
\end{definition}

\begin{definition}[Quasi-affine variety]
\label{def:ha-ch1-quasi-affine-variety}
\source{hartshorne-algebraic-geometry:I.1}
A quasi-affine variety is an open subset of an affine algebraic variety.
\uses{def:ha-ch1-affine-variety}
\end{definition}

\begin{definition}[Vanishing ideal]
\label{def:ha-ch1-vanishing-ideal}
\source{hartshorne-algebraic-geometry:I.1}
\lean{Hartshorne.vanishingIdeal, Hartshorne.mem_vanishingIdeal}
\leanok
For $Y\subseteq\mathbb A^n$, its ideal is
\[
 I(Y)=\{f\in A:f(P)=0\text{ for every }P\in Y\}.
\]
\uses{def:ha-ch1-polynomial-evaluation}
\end{definition}

\begin{proposition}[Ideal-zero-set identities]
\label{prop:ha-ch1-1-2}
\source{hartshorne-algebraic-geometry:I.1.2}
\dcref{I.1.2}
For $T_1\subseteq T_2\subset A$, $Z(T_1)\supseteq Z(T_2)$; for $Y_1\subseteq Y_2$,
$I(Y_1)\supseteq I(Y_2)$; $I(Y_1\cup Y_2)=I(Y_1)\cap I(Y_2)$; for an ideal $\mathfrak a$,
$I(Z(\mathfrak a))=\sqrt{\mathfrak a}$; and $Z(I(Y))=\overline Y$.
\uses{def:ha-ch1-polynomial-evaluation,def:ha-ch1-algebraic-set,def:ha-ch1-vanishing-ideal,thm:ha-ch1-1-3A}
\end{proposition}
\begin{proof}
The first three assertions follow immediately from the definitions.  The fourth is the
Nullstellensatz (Theorem~\ref{thm:ha-ch1-1-3A}).  For the last, $Y\subseteq Z(I(Y))$; if
$W=Z(\mathfrak a)$ is any closed set containing $Y$, then $\mathfrak a\subseteq I(W)\subseteq I(Y)$,
so $W\supseteq Z(I(Y))$.  Thus $Z(I(Y))$ is the smallest closed set containing $Y$.
\end{proof}

\begin{theorem}[Hilbert Nullstellensatz]
\label{thm:ha-ch1-1-3A}
\source{hartshorne-algebraic-geometry:I.1.3A}
\dcref{I.1.3A}
\lean{Hartshorne.hilbertNullstellensatz}
\leanok
If $\mathfrak a\subset A$ and $f$ vanishes on $Z(\mathfrak a)$, then $f^r\in\mathfrak a$
for some integer $r>0$.
\end{theorem}
\begin{proof}
Hartshorne gives external references for this theorem and does not prove it in Chapter I.
\end{proof}

\begin{corollary}[Affine Nullstellensatz correspondence]
\label{cor:ha-ch1-1-4}
\source{hartshorne-algebraic-geometry:I.1.4}
\dcref{I.1.4}
\lean{Hartshorne.AffineAlgebraicSet, Hartshorne.AffineRadicalIdeal,
Hartshorne.affineAlgebraicSetToRadicalIdeal,
Hartshorne.affineRadicalIdealToAlgebraicSet,
Hartshorne.affineRadicalIdealToAlgebraicSet_leftInverse,
Hartshorne.affineAlgebraicSetToRadicalIdeal_rightInverse,
Hartshorne.affineNullstellensatzEquiv,
Hartshorne.affineAlgebraicSetToRadicalIdeal_antitone,
Hartshorne.affineRadicalIdealToAlgebraicSet_antitone,
Hartshorne.isAffineVariety_iff_vanishingIdeal_isPrime}
\leanok
Algebraic sets correspond inclusion-reversingly to radical ideals by $Y\mapsto I(Y)$ and
$\mathfrak a\mapsto Z(\mathfrak a)$.  An algebraic set is irreducible exactly when its ideal is prime.
\uses{thm:ha-ch1-1-3A,prop:ha-ch1-1-2}
\end{corollary}
\begin{proof}
The first assertion is Theorem~\ref{thm:ha-ch1-1-3A} together with Proposition~\ref{prop:ha-ch1-1-2}.
If $Y$ is irreducible and $fg\in I(Y)$, then $Y\subseteq Z(f)\cup Z(g)$, so one of $f,g$
vanishes on $Y$; hence $I(Y)$ is prime.  Conversely, if $\mathfrak p$ is prime and
$Z(\mathfrak p)=Y_1\cup Y_2$, then $\mathfrak p=I(Y_1)\cap I(Y_2)$, so primality forces
$\mathfrak p=I(Y_i)$ for some $i$, and $Z(\mathfrak p)=Y_i$.
\end{proof}

\begin{definition}[Affine coordinate ring]
\label{def:ha-ch1-affine-coordinate}
\source{hartshorne-algebraic-geometry:I.1.4}
For an affine algebraic set $Y$, put $A(Y)=A/I(Y)$.
\uses{def:ha-ch1-algebraic-set,def:ha-ch1-vanishing-ideal}
\end{definition}

\begin{proposition}[Irreducible components]
\label{prop:ha-ch1-1-5}
\source{hartshorne-algebraic-geometry:I.1.5}
\dcref{I.1.5}
In a noetherian topological space, every nonempty closed set is a finite union of irreducible
closed subsets, uniquely after omitting components contained in another.
\uses{def:ha-ch1-zariski-topology,def:ha-ch1-irreducible-subset}
\end{proposition}
\begin{proof}
If a minimal counterexample $Y$ were reducible, write $Y=Y'\cup Y''$ with both proper closed;
minimality decomposes each into finitely many irreducible closed sets, contradiction.  For
uniqueness, an irreducible component in one decomposition is contained in a component of the
other; applying this in both directions and removing the first common component gives induction.
\end{proof}

\begin{corollary}[Affine components]
\label{cor:ha-ch1-1-6}
\source{hartshorne-algebraic-geometry:I.1.6}
\dcref{I.1.6}
Every affine algebraic set is a unique irredundant union of affine varieties.
\uses{prop:ha-ch1-1-5,cor:ha-ch1-1-4}
\end{corollary}
\begin{proof}
Apply Proposition~\ref{prop:ha-ch1-1-5} to the noetherian Zariski space $Y$.  Its irreducible
components are closed in $Y$, hence affine algebraic sets, and their ideals are prime by
Corollary~\ref{cor:ha-ch1-1-4}.  The uniqueness and irredundancy are exactly the uniqueness clause
in Proposition~\ref{prop:ha-ch1-1-5}.
\end{proof}

For a topological space, dimension is the supremum of lengths of chains of distinct irreducible
closed subsets.  For a ring, the height of a prime is the supremum of lengths of chains ending in
that prime, and the Krull dimension is the supremum of prime heights.

\begin{proposition}[Dimension of an affine coordinate ring]
\label{prop:ha-ch1-1-7}
\source{hartshorne-algebraic-geometry:I.1.7}
\dcref{I.1.7}
For an affine algebraic set $Y$, $\dim Y=\dim A(Y)$.
\uses{def:ha-ch1-affine-coordinate}
\end{proposition}
\begin{proof}
Closed irreducible subsets of $Y$ correspond to prime ideals of $A$ containing $I(Y)$, hence
to prime ideals of $A(Y)$; chains correspond and have the same lengths.
\end{proof}

\begin{theorem}[Dimension theorem for finite type domains]
\label{thm:ha-ch1-1-8A}
\source{hartshorne-algebraic-geometry:I.1.8A}
\dcref{I.1.8A}
If $B$ is a finitely generated domain over a field $k$, then
$\dim B=\operatorname{trdeg}_kK(B)$ and
$\operatorname{ht}\mathfrak p+\dim(B/\mathfrak p)=\dim B$ for every prime $\mathfrak p$.
\end{theorem}
\begin{proof}
Hartshorne cites Matsumura and Atiyah--Macdonald for this commutative-algebra theorem.
\end{proof}

\begin{proposition}[Dimension of affine space]
\label{prop:ha-ch1-1-9}
\source{hartshorne-algebraic-geometry:I.1.9}
\dcref{I.1.9}
\(\dim\mathbb A^n=n\).
\uses{prop:ha-ch1-1-7,thm:ha-ch1-1-8A}
\end{proposition}
\begin{proof}
Apply Proposition~\ref{prop:ha-ch1-1-7} and Theorem~\ref{thm:ha-ch1-1-8A} to the polynomial ring.
\end{proof}

\begin{proposition}[Dimension of a quasi-affine variety]
\label{prop:ha-ch1-1-10}
\source{hartshorne-algebraic-geometry:I.1.10}
\dcref{I.1.10}
If $Y$ is quasi-affine, then $\dim Y=\dim\overline Y$.
\uses{thm:ha-ch1-1-8A}
\end{proposition}
\begin{proof}
Closing a chain gives $\dim Y\le\dim\overline Y$.  Choose a maximal chain in $Y$ beginning at a
point $P$.  Its closures form a maximal chain in $\overline Y$, and the corresponding prime
ideals lie under the maximal ideal $\mathfrak m_P$ with residue field $k$.  Theorem~\ref{thm:ha-ch1-1-8A}(b)
then gives the same chain length as $\dim A(\overline Y)$, which is $\dim\overline Y$.
\end{proof}

\begin{theorem}[Krull Hauptidealsatz]
\label{thm:ha-ch1-1-11A}
\source{hartshorne-algebraic-geometry:I.1.11A}
\dcref{I.1.11A}
If $A$ is noetherian and $f$ is neither a zero divisor nor a unit, every minimal prime containing
$f$ has height one.
\end{theorem}
\begin{proof}
Hartshorne cites Atiyah--Macdonald for the proof.
\end{proof}

\begin{proposition}[Height-one criterion for a UFD]
\label{prop:ha-ch1-1-12A}
\source{hartshorne-algebraic-geometry:I.1.12A}
\dcref{I.1.12A}
A noetherian domain is a unique factorization domain iff every height-one prime is principal.
\end{proposition}
\begin{proof}
Hartshorne cites Matsumura and Bourbaki for the proof.
\end{proof}

\begin{proposition}[Affine hypersurfaces]
\label{prop:ha-ch1-1-13}
\source{hartshorne-algebraic-geometry:I.1.13}
\dcref{I.1.13}
A variety $Y\subset\mathbb A^n$ has dimension $n-1$ iff $Y=Z(f)$ for one nonconstant irreducible
$f\in k[x_1,\ldots,x_n]$.
\uses{thm:ha-ch1-1-11A,prop:ha-ch1-1-12A}
\end{proposition}
\begin{proof}
For irreducible $f$, $(f)$ is prime and has height one by Hauptidealsatz, so the dimension theorem
gives $n-1$.  Conversely, $Y$ corresponds to a height-one prime in the polynomial UFD; by the
height-one criterion it is generated by an irreducible $f$, hence $Y=Z(f)$.
\end{proof}

\section{Projective Varieties}

Let $S=k[x_0,\ldots,x_n]$ with its total-degree grading.

\begin{definition}[Projective space and homogeneous coordinates]
\label{def:ha-ch1-projective-space}
\source{hartshorne-algebraic-geometry:I.2}
The projective space $\mathbb P^n$ is the set of nonzero $(n+1)$-tuples in $k^{n+1}$ modulo
scalar multiplication. A homogeneous polynomial has all terms of one total degree, and $S$ is
graded by total degree.
\uses{def:ha-ch1-polynomial-evaluation}
\end{definition}

\begin{definition}[Projective algebraic set]
\label{def:ha-ch1-projective-algebraic-set}
\source{hartshorne-algebraic-geometry:I.2}
For homogeneous $T\subset S$, define $Z(T)\subset\mathbb P^n$ by common vanishing. A projective
algebraic set is a set $Z(T)$; its homogeneous vanishing ideal is $I(Y)$ and its homogeneous
coordinate ring is $S(Y)=S/I(Y)$.
\uses{def:ha-ch1-projective-space}
\end{definition}

\begin{definition}[Projective and quasi-projective varieties]
\label{def:ha-ch1-projective-variety}
\source{hartshorne-algebraic-geometry:I.2}
A projective variety is an irreducible projective algebraic set. A quasi-projective variety is an
open subset of a projective variety.
\uses{def:ha-ch1-projective-algebraic-set,def:ha-ch1-irreducible-subset}
\end{definition}

\begin{proposition}[Projective algebraic sets]
\label{prop:ha-ch1-2-1}
\source{hartshorne-algebraic-geometry:I.2.1}
\dcref{I.2.1}
Unions and arbitrary intersections of projective algebraic sets are algebraic, as are $\varnothing$
and $\mathbb P^n$.
\uses{prop:ha-ch1-1-1}
\end{proposition}
\begin{proof}
Hartshorne leaves the proof to the reader; it is the homogeneous analogue of Proposition 1.1.
\end{proof}

\begin{proposition}[Standard projective charts]
\label{prop:ha-ch1-2-2}
\source{hartshorne-algebraic-geometry:I.2.2}
\dcref{I.2.2}
With $H_i=Z(x_i)$ and $U_i=\mathbb P^n-H_i$, the ratio map
$\varphi_i:U_i\to\mathbb A^n$ is a homeomorphism for the induced/projective and affine Zariski
topologies.
\uses{def:ha-ch1-projective-space,def:ha-ch1-projective-algebraic-set,def:ha-ch1-zariski-topology}
\end{proposition}
\begin{proof}
For $i=0$, dehomogenization sends a homogeneous polynomial $f$ to $f(1,y_1,\ldots,y_n)$;
homogenization sends a polynomial $g$ of degree $d$ to
$x_0^d g(x_1/x_0,\ldots,x_n/x_0)$.  These maps identify projective closed subsets in $U_0$
with affine closed subsets and are inverse, proving the claim.  Other charts are identical.
\end{proof}

\begin{corollary}[Affine chart cover]
\label{cor:ha-ch1-2-3}
\source{hartshorne-algebraic-geometry:I.2.3}
\dcref{I.2.3}
Every projective (respectively quasi-projective) variety is covered by its intersections with the
$U_i$, which are affine (respectively quasi-affine) varieties.
\uses{prop:ha-ch1-2-2}
\end{corollary}
\begin{proof}
The $U_i$ cover projective space because a nonzero homogeneous coordinate tuple has some nonzero
coordinate.  Proposition~\ref{prop:ha-ch1-2-2} identifies $Y\cap U_i$ with a closed subset of
$\mathbb A^n$ when $Y$ is projective, and with an open subset of such a closed set when $Y$ is
quasi-projective.
\end{proof}

\section{Morphisms}

\begin{definition}[Regular function]
\label{def:ha-ch1-regular-function}
\source{hartshorne-algebraic-geometry:I.3}
A function to $k$ is regular at $P$ if on a neighborhood of $P$ it is $g/h$ with $h$ nowhere
zero; in projective space $g,h$ are homogeneous of the same degree. It is regular if it is regular
at every point.
\uses{def:ha-ch1-quasi-affine-variety,def:ha-ch1-projective-variety}
\end{definition}

\begin{definition}[Morphism and isomorphism]
\label{def:ha-ch1-morphism}
\source{hartshorne-algebraic-geometry:I.3}
A morphism is a continuous map pulling regular functions back to regular functions. An isomorphism
is a morphism having a morphism as inverse.
\uses{def:ha-ch1-regular-function}
\end{definition}

\begin{lemma}[Continuity of regular functions]
\label{lem:ha-ch1-3-1}
\source{hartshorne-algebraic-geometry:I.3.1}
\dcref{I.3.1}
Every regular function is continuous.
\end{lemma}
\begin{proof}
It suffices to show that each fiber over $a\in k$ is closed.  On a neighborhood where $f=g/h$,
with $h$ nowhere zero, the fiber is the zero set of $g-ah$; local closedness therefore implies
global closedness.
\end{proof}

\begin{theorem}[Affine variety functions and local rings]
\label{thm:ha-ch1-3-2}
\source{hartshorne-algebraic-geometry:I.3.2}
\dcref{I.3.2}
For affine $Y$, $\mathcal O(Y)\cong A(Y)$; points correspond to maximal ideals; for $P$,
$\mathcal O_{P,Y}\cong A(Y)_{\mathfrak m_P}$ and $\dim\mathcal O_{P,Y}=\dim Y$; and
$K(Y)$ is the fraction field of $A(Y)$ with transcendence degree $\dim Y$.
\uses{def:ha-ch1-affine-coordinate,def:ha-ch1-affine-variety,cor:ha-ch1-1-4,thm:ha-ch1-1-8A}
\end{theorem}
\begin{proof}
Polynomial restriction gives an injective map $A(Y)\to\mathcal O(Y)$.  The affine Nullstellensatz
identifies points with maximal ideals and gives the stated $\mathfrak m_P$.  Local expressions $g/h$
give the surjection $A(Y)_{\mathfrak m_P}\to\mathcal O_{P,Y}$, while injectivity follows from
the preceding injection.  The dimension and transcendence assertions follow from the dimension
theorem.  Finally, inside the fraction field, a domain is the intersection of its localizations at
all maximal ideals; since $\mathcal O(Y)$ lies between $A(Y)$ and this intersection, equality follows.
\end{proof}

\begin{proposition}[Projective chart isomorphism]
\label{prop:ha-ch1-3-3}
\source{hartshorne-algebraic-geometry:I.3.3}
\dcref{I.3.3}
The chart map $\varphi_i:U_i\to\mathbb A^n$ of Proposition 2.2 is an isomorphism of varieties.
\uses{prop:ha-ch1-2-2}
\end{proposition}
\begin{proof}
The dehomogenization and homogenization maps identify local quotients of equal-degree homogeneous
polynomials with local quotients of affine polynomials, so the homeomorphism preserves regular
functions in both directions.
\end{proof}

\begin{theorem}[Functions on a projective variety]
\label{thm:ha-ch1-3-4}
\source{hartshorne-algebraic-geometry:I.3.4}
\dcref{I.3.4}
For projective $Y$ with homogeneous coordinate ring $S(Y)$, $\mathcal O(Y)=k$,
$\mathcal O_{P,Y}=S(Y)_{(\mathfrak m_P)}$, and $K(Y)$ is the degree-zero fraction field
$S(Y)_{((0))}$.
\uses{def:ha-ch1-projective-variety,def:ha-ch1-projective-algebraic-set}
\end{theorem}
\begin{proof}
Chart localization gives the local-ring and function-field assertions.  If a global function $f$
has chart expressions, choose one common degree $N$ so that multiplication by $x_i^N$ sends it
into $S(Y)$.  Consequently $S(Y)[f]$ is a finite $S(Y)$-module, so $f$ is integral over $S(Y)$.
Taking degree-zero parts makes $f$ integral over $S(Y)_0=k$; algebraic closedness gives $f\in k$.
\end{proof}

\begin{proposition}[Maps to affine varieties]
\label{prop:ha-ch1-3-5}
\source{hartshorne-algebraic-geometry:I.3.5}
\dcref{I.3.5}
For any variety $X$ and affine variety $Y$, morphisms $X\to Y$ correspond naturally to
$k$-algebra homomorphisms $A(Y)\to\mathcal O(X)$.
\uses{lem:ha-ch1-3-6}
\end{proposition}
\begin{proof}
Pullback gives the homomorphism.  Conversely, choose affine coordinates for $Y$ and take the
images of their coordinate functions; they define a map to affine space, and the ideal of $Y$
vanishes after applying the homomorphism, so the image lies in $Y$.  Lemma 3.6 makes the map a
morphism, and the two constructions are inverse.
\end{proof}

\begin{lemma}[Coordinate criterion for affine morphisms]
\label{lem:ha-ch1-3-6}
\source{hartshorne-algebraic-geometry:I.3.6}
\dcref{I.3.6}
A map $\psi:X\to Y\subset\mathbb A^n$ is a morphism iff every coordinate function $x_i\circ\psi$
is regular on $X$.
\end{lemma}
\begin{proof}
Necessity is the definition.  For sufficiency, polynomial pullbacks are regular and therefore
continuous; local quotients of polynomials pull back to regular functions, so $\psi$ is a morphism.
\end{proof}

\begin{corollary}[Affine anti-equivalence]
\label{cor:ha-ch1-3-7}
\source{hartshorne-algebraic-geometry:I.3.7}
\dcref{I.3.7}
Affine varieties are isomorphic iff their coordinate rings are isomorphic as $k$-algebras.
\uses{thm:ha-ch1-3-2,prop:ha-ch1-3-5,lem:ha-ch1-3-6}
\end{corollary}
\begin{proof}
A morphism induces pullback on global regular functions, and Theorem~\ref{thm:ha-ch1-3-2} identifies
these rings with the affine coordinate rings.  Conversely an isomorphism of coordinate rings gives,
by Proposition~\ref{prop:ha-ch1-3-5}, morphisms in both directions.  The two composites pull back to
the identity on coordinate functions, hence are the identity by Lemma~\ref{lem:ha-ch1-3-6}.
\end{proof}

\begin{corollary}[Affine varieties and finite type domains]
\label{cor:ha-ch1-3-8}
\source{hartshorne-algebraic-geometry:I.3.8}
\dcref{I.3.8}
$X\mapsto A(X)$ is an arrow-reversing equivalence between affine varieties over $k$ and finitely
generated integral $k$-domains.
\uses{cor:ha-ch1-1-4,prop:ha-ch1-3-5}
\end{corollary}
\begin{proof}
For an affine variety, $A(X)$ is finitely generated and a domain by the affine Nullstellensatz.
Conversely, write a finitely generated domain as $k[x_1,\ldots,x_n]/\mathfrak p$ with $\mathfrak p$
prime; Corollary~\ref{cor:ha-ch1-1-4} makes $Z(\mathfrak p)$ an affine variety with that coordinate
ring.  Proposition~\ref{prop:ha-ch1-3-5} identifies the arrows contravariantly.
\end{proof}

\begin{theorem}[Finiteness of integral closure]
\label{thm:ha-ch1-3-9A}
\source{hartshorne-algebraic-geometry:I.3.9A}
\dcref{I.3.9A}
If $A$ is a finitely generated domain over $k$, $L$ is finite algebraic over $K(A)$, and $A'$ is
the integral closure of $A$ in $L$, then $A'$ is a finite $A$-module and a finitely generated
$k$-algebra.
\end{theorem}
\begin{proof}
Hartshorne cites Zariski--Samuel and gives no proof in Chapter I.
\end{proof}

\section{Rational Maps}

\begin{definition}[Rational and birational maps]
\label{def:ha-ch1-rational-map}
\source{hartshorne-algebraic-geometry:I.4}
A rational map $X\dashrightarrow Y$ is an equivalence class of morphisms from nonempty open
subsets of $X$, where two representatives agree after restriction to a common nonempty open.
It is dominant if its image is dense, and birational if it has an inverse rational map.
\end{definition}

\begin{definition}[Function field]
\label{def:ha-ch1-function-field}
\source{hartshorne-algebraic-geometry:I.4}
For an irreducible variety $X$, its function field $K(X)$ is the field of rational functions,
equivalently the fraction field of the coordinate ring of any dense affine open subset.
\end{definition}

\begin{lemma}[Density determines morphisms]
\label{lem:ha-ch1-4-1}
\source{hartshorne-algebraic-geometry:I.4.1}
\dcref{I.4.1}
Two morphisms from $X$ to $Y$ agreeing on a nonempty open subset agree everywhere.
\end{lemma}
\begin{proof}
Embed $Y$ in projective space.  The product map to $\mathbb P^n\times\mathbb P^n$ has image of
the dense open in the diagonal, which is closed (the equations $x_i y_j=x_j y_i$).  Hence its
whole image lies in the diagonal.
\end{proof}

\begin{lemma}[Principal open as affine]
\label{lem:ha-ch1-4-2}
\source{hartshorne-algebraic-geometry:I.4.2}
\dcref{I.4.2}
If $Y=V(f)\subset\mathbb A^n$, then $\mathbb A^n-Y$ is isomorphic to
$H=V(x_{n+1}f-1)\subset\mathbb A^{n+1}$, and its coordinate ring is $k[x_1,\ldots,x_n]_f$.
\uses{lem:ha-ch1-3-6}
\end{lemma}
\begin{proof}
Projection from $H$ has inverse $(a_1,\ldots,a_n)\mapsto(a_1,\ldots,a_n,1/f(a))$; Lemma 3.6
shows both maps are morphisms.
\end{proof}

\begin{proposition}[Affine basis]
\label{prop:ha-ch1-4-3}
\source{hartshorne-algebraic-geometry:I.4.3}
\dcref{I.4.3}
Every variety has a basis of open affine subsets.
\uses{lem:ha-ch1-4-2}
\end{proposition}
\begin{proof}
Reduce to quasi-affine $Y\subset\mathbb A^n$.  For $P\in U\subset Y$, choose $f\in I(Ybar-Y)$
with $f(P)\ne0$.  Then $Y-f^{-1}(0)$ is an affine closed subset of the affine principal open
$\mathbb A^n-f^{-1}(0)$ by Lemma 4.2, and lies in $U$ after choosing $f$ from the complement.
\end{proof}

\begin{theorem}[Rational maps and function fields]
\label{thm:ha-ch1-4-4}
\source{hartshorne-algebraic-geometry:I.4.4}
\dcref{I.4.4}
Dominant rational maps $X\dashrightarrow Y$ correspond bijectively to $k$-embeddings
$K(Y)\hookrightarrow K(X)$, giving an arrow-reversing equivalence with finitely generated field
extensions of $k$.
\uses{prop:ha-ch1-3-5,lem:ha-ch1-4-1}
\end{theorem}
\begin{proof}
Pullback on a dense domain gives the embedding.  Conversely, choose affine generators of $K(Y)$;
after shrinking $X$ they are regular, and Proposition 3.5 gives a morphism to an affine open of
$Y$.  Lemma 4.1 makes the resulting rational map independent of choices.  A finitely generated
field is the function field of the affine variety defined by the relations among a finite set of
field generators, proving essential surjectivity and compatibility with composition.
\end{proof}

\begin{corollary}[Birational tests]
\label{cor:ha-ch1-4-5}
\source{hartshorne-algebraic-geometry:I.4.5}
\dcref{I.4.5}
For varieties $X,Y$, the following are equivalent: $X,Y$ are birational; they have isomorphic
dense open subsets; and $K(X)\cong K(Y)$ over $k$.
\uses{thm:ha-ch1-4-4}
\end{corollary}
\begin{proof}
Restrict inverse rational maps to common domains for the first implication; an isomorphism of opens
induces an isomorphism of function fields; Theorem 4.4 gives the converse.
\end{proof}

\begin{theorem}[Primitive element]
\label{thm:ha-ch1-4-6A}
\source{hartshorne-algebraic-geometry:I.4.6A}
\dcref{I.4.6A}
A finite separable extension $L/K$ is generated by one element; over an infinite $K$, a generator
can be chosen as a $K$-linear combination of any finite generating set.
\end{theorem}
\begin{proof}
Hartshorne cites Zariski--Samuel.
\end{proof}

\begin{theorem}[Separating transcendence bases]
\label{thm:ha-ch1-4-7A}
\source{hartshorne-algebraic-geometry:I.4.7A}
\dcref{I.4.7A}
Every finitely generated separably generated extension has, inside any generating set, a separating
transcendence basis.
\end{theorem}
\begin{proof}
Hartshorne cites Zariski--Samuel.
\end{proof}

\begin{theorem}[Perfect fields]
\label{thm:ha-ch1-4-8A}
\source{hartshorne-algebraic-geometry:I.4.8A}
\dcref{I.4.8A}
Every finitely generated extension of a perfect field is separably generated.
\end{theorem}
\begin{proof}
Hartshorne cites Zariski--Samuel and Matsumura.
\end{proof}

\begin{proposition}[Birational hypersurface model]
\label{prop:ha-ch1-4-9}
\source{hartshorne-algebraic-geometry:I.4.9}
\dcref{I.4.9}
Every $r$-dimensional variety is birational to a hypersurface in $\mathbb A^{r+1}$ (and to its
projective closure in $\mathbb P^{r+1}$).
\uses{cor:ha-ch1-4-5}
\end{proposition}
\begin{proof}
Choose a separating transcendence basis $x_1,\ldots,x_r$ and, by the primitive-element theorem,
$y$ with $K(X)=k(x_1,\ldots,x_r,y)$.  Clearing denominators in the algebraic equation of $y$
gives an irreducible equation in $r+1$ variables whose hypersurface has function field $K(X)$.
Apply Corollary 4.5.
\end{proof}

\section{Nonsingular Varieties}

\begin{definition}[Local, cotangent, and tangent spaces]
\label{def:ha-ch1-tangent-space}
\source{hartshorne-algebraic-geometry:I.5}
For a point $P$ of an affine variety, let $\mathfrak m_P$ be the maximal ideal of its local ring.
The cotangent space is $\mathfrak m_P/\mathfrak m_P^2$ and the Zariski tangent space is its dual.
\end{definition}

\begin{definition}[Regular local ring and nonsingularity]
\label{def:ha-ch1-regular-local}
\source{hartshorne-algebraic-geometry:I.5}
A noetherian local ring $(A,\mathfrak m,k)$ is regular if
$\dim_k\mathfrak m/\mathfrak m^2=\dim A$. A variety is nonsingular at $P$ when its local ring is
regular, and singular otherwise.
\end{definition}

\begin{definition}[Multiplicity]
\label{def:ha-ch1-multiplicity}
\source{hartshorne-algebraic-geometry:I.5}
The multiplicity of a local ring is the normalized leading coefficient of its Hilbert--Samuel
polynomial; at a point of a variety it is the multiplicity of its local ring.
\end{definition}

\begin{theorem}[Jacobian criterion]
\label{thm:ha-ch1-5-1}
\source{hartshorne-algebraic-geometry:I.5.1}
\dcref{I.5.1}
For an affine variety $Y\subset\mathbb A^n$, $P$ is nonsingular iff $\mathcal O_{P,Y}$ is
regular.  If $\dim Y=r$, this is equivalent to the Jacobian of generators of $I(Y)$ having rank
$n-r$ at $P$.
\end{theorem}
\begin{proof}
Translate $P=(a_i)$ to the origin.  The differential map identifies the cotangent space of affine
space with $k^n$, and the image of $I(Y)$ has dimension equal to the Jacobian rank.  Thus
\(\dim_k\mathfrak m_P/\mathfrak m_P^2+\operatorname{rank}J=n\).  Since
\(\dim\mathcal O_{P,Y}=r\), regularity is equivalent to rank $J=n-r$.
\end{proof}

\begin{proposition}[Embedding-dimension inequality]
\label{prop:ha-ch1-5-2A}
\source{hartshorne-algebraic-geometry:I.5.2A}
\dcref{I.5.2A}
For a noetherian local ring $(A,\mathfrak m,k)$, \(\dim_k\mathfrak m/\mathfrak m^2\ge\dim A\), with equality precisely when $A$ is regular.
\end{proposition}
\begin{proof}
Hartshorne cites Atiyah--Macdonald and Matsumura.
\end{proof}

\begin{theorem}[Openness of the nonsingular locus]
\label{thm:ha-ch1-5-3}
\source{hartshorne-algebraic-geometry:I.5.3}
\dcref{I.5.3}
For every variety $Y$, $\operatorname{Sing}Y$ is a proper closed subset.
\end{theorem}
\begin{proof}
On an affine chart of dimension $r$ it is cut out by $I(Y)$ and all $(n-r)\times(n-r)$ Jacobian
minors, hence is closed.  Birationality reduces properness to an irreducible hypersurface
$f=0$.  If every point were singular, all partial derivatives would vanish on $Y$, hence would
be multiples of $f$; their lower degrees force them to be zero.  In characteristic zero this is
impossible.  In characteristic $p$, $f$ is a polynomial in the $p$th powers of the variables,
and algebraic closedness makes $f$ a $p$th power, contradicting irreducibility.
\end{proof}

\begin{theorem}[Completion of local rings]
\label{thm:ha-ch1-5-4A}
\source{hartshorne-algebraic-geometry:I.5.4A}
\dcref{I.5.4A}
For a noetherian local ring $A$ with completion $\widehat A$: $\widehat A$ is local with maximal
ideal $\mathfrak m\widehat A$ and $A\hookrightarrow\widehat A$; the completion of every finite
$A$-module $M$ is $M\otimes_A\widehat A$; \(\dim\widehat A=\dim A\); and $A$ is regular iff
$\widehat A$ is regular.
\end{theorem}
\begin{proof}
Hartshorne cites Atiyah--Macdonald and Zariski--Samuel.
\end{proof}

\begin{theorem}[Cohen structure theorem]
\label{thm:ha-ch1-5-5A}
\source{hartshorne-algebraic-geometry:I.5.5A}
\dcref{I.5.5A}
If a complete regular local ring of dimension $n$ contains a field, then it is isomorphic to
$k[[x_1,\ldots,x_n]]$ over its residue field $k$.
\end{theorem}
\begin{proof}
Hartshorne cites Matsumura and Zariski--Samuel.
\end{proof}

\begin{theorem}[Elimination theory]
\label{thm:ha-ch1-5-7A}
\source{hartshorne-algebraic-geometry:I.5.7A}
\dcref{I.5.7A}
For homogeneous polynomials $f_1,\ldots,f_r$ with indeterminate coefficients, there are universal
integer-coefficient polynomials in those coefficients, homogeneous in the coefficients of each
$f_i$, whose simultaneous vanishing is equivalent over every field to the existence of a common
nonzero projective zero.
\end{theorem}
\begin{proof}
Hartshorne cites van der Waerden.
\end{proof}

\section{Nonsingular Curves}

\begin{definition}[Curves, valuation rings, and DVRs]
\label{def:ha-ch1-curve-valuation}
\source{hartshorne-algebraic-geometry:I.6}
A curve is a one-dimensional variety. A valuation ring of a field $K$ is a local subring $R$
such that for every $x\in K^*$ either $x$ or $x^{-1}$ lies in $R$. It is discrete when its value
group is $\mathbb Z$, in which case it is a discrete valuation ring (DVR).
\end{definition}

\begin{definition}[Domination and abstract nonsingular curve]
\label{def:ha-ch1-abstract-curve}
\source{hartshorne-algebraic-geometry:I.6}
A local ring $R$ dominates a local ring $A$ when $A\subseteq R$ and the maximal ideal of $R$
contracts to that of $A$. An abstract nonsingular curve is the curve obtained by gluing the local
models associated to the DVRs of its function field.
\end{definition}

\begin{theorem}[Valuation rings]
\label{thm:ha-ch1-6-1A}
\source{hartshorne-algebraic-geometry:I.6.1A}
\dcref{I.6.1A}
A local subring $R\subset K$ is a valuation ring iff for each $x\in K^*$, $x\in R$ or
$x^{-1}\in R$.
\end{theorem}
\begin{proof}
Hartshorne cites Bourbaki and Atiyah--Macdonald.
\end{proof}

\begin{theorem}[One-dimensional normal local rings]
\label{thm:ha-ch1-6-2A}
\source{hartshorne-algebraic-geometry:I.6.2A}
\dcref{I.6.2A}
A one-dimensional noetherian local domain is a DVR iff it is integrally closed.
\end{theorem}
\begin{proof}
Hartshorne cites Atiyah--Macdonald.
\end{proof}

\begin{theorem}[Integral closure of a Dedekind domain]
\label{thm:ha-ch1-6-3A}
\source{hartshorne-algebraic-geometry:I.6.3A}
\dcref{I.6.3A}
The integral closure of a Dedekind domain in a finite extension of its fraction field is Dedekind.
\end{theorem}
\begin{proof}
Hartshorne cites Zariski--Samuel.
\end{proof}

\begin{lemma}[Incomparability of curve local rings]
\label{lem:ha-ch1-6-4}
\source{hartshorne-algebraic-geometry:I.6.4}
\dcref{I.6.4}
If $P\ne Q$ are points of a quasi-projective variety with the same function field, neither local
ring dominates the other.
\end{lemma}
\begin{proof}
Embed in projective space and choose a homogeneous coordinate ratio regular at one point and
having a pole at the other.  It belongs to one local ring but not the other, ruling out domination.
\end{proof}

\begin{lemma}[Valuation-ring intersection]
\label{lem:ha-ch1-6-5}
\source{hartshorne-algebraic-geometry:I.6.5}
\dcref{I.6.5}
For a one-dimensional function field $K/k$ and $x\in K^*$, $x$ belongs to a valuation ring $R$
iff it has nonnegative valuation there; if $x\notin R$, then $x^{-1}$ lies in the maximal ideal.
The intersection of the valuation rings containing $k$ is the relative constant field.
\end{lemma}
\begin{proof}
The membership equivalence is the defining dichotomy of a valuation ring.  Applying it to $x^{-1}$
gives the maximal-ideal assertion; intersecting over all such rings gives the constant-field claim.
\end{proof}

\begin{corollary}[DVRs are curve local rings]
\label{cor:ha-ch1-6-6}
\source{hartshorne-algebraic-geometry:I.6.6}
\dcref{I.6.6}
Every DVR of a one-dimensional function field $K/k$ is isomorphic to the local ring of a point on
a nonsingular affine curve.
\uses{lem:ha-ch1-6-5}
\end{corollary}
\begin{proof}
Choose $y\in R\setminus k$.  The construction in Lemma 6.5 gives a finitely generated normal
one-dimensional $k$-algebra whose localization at a maximal ideal is $R$.
\end{proof}

\begin{proposition}[Abstract model of a nonsingular curve]
\label{prop:ha-ch1-6-7}
\source{hartshorne-algebraic-geometry:I.6.7}
\dcref{I.6.7}
Every nonsingular quasi-projective curve is isomorphic to an abstract nonsingular curve formed from
the DVRs of its function field.
\uses{lem:ha-ch1-6-4,cor:ha-ch1-6-6}
\end{proposition}
\begin{proof}
Map each point to its local DVR.  The map is injective by Lemma 6.4 and surjective onto the chosen
open DVR set by Corollary 6.6.  Affine neighborhoods and the valuation criterion identify the
topology and local rings, hence give an isomorphism.
\end{proof}

\begin{proposition}[Extension across finitely many points]
\label{prop:ha-ch1-6-8}
\source{hartshorne-algebraic-geometry:I.6.8}
\dcref{I.6.8}
A morphism from an open subset of a nonsingular curve to a nonsingular complete curve extends
uniquely across the finitely many omitted points.
\uses{lem:ha-ch1-4-1}
\end{proposition}
\begin{proof}
Embed the target in projective space and write the map by homogeneous coordinates in the function
field.  At an omitted DVR choose a coordinate of minimal valuation; after rescaling all coordinates
lie in the DVR and one is a unit, so they define a point and a morphism there.  Uniqueness follows
from Lemma 4.1.
\end{proof}

\begin{theorem}[Complete nonsingular model]
\label{thm:ha-ch1-6-9}
\source{hartshorne-algebraic-geometry:I.6.9}
\dcref{I.6.9}
Every one-dimensional function field $K/k$ has a nonsingular projective curve $C_K$ whose points
are exactly the DVRs of $K/k$; it is unique up to unique isomorphism.
\uses{lem:ha-ch1-6-4,prop:ha-ch1-6-8}
\end{theorem}
\begin{proof}
Choose finitely many affine normal curve models whose local rings cover all DVRs, and glue them
along common principal affine opens.  The result is nonsingular and, by the finite affine cover
and the projective-coordinate construction, projective.  Any other model has the same DVR points;
Lemma 6.4 identifies them uniquely and Lemma 6.8 extends the resulting birational map everywhere.
\end{proof}

\begin{corollary}[Projective completion of curves]
\label{cor:ha-ch1-6-10}
\source{hartshorne-algebraic-geometry:I.6.10}
\dcref{I.6.10}
Every abstract nonsingular curve is quasi-projective, and every nonsingular quasi-projective curve is
an open subset of a nonsingular projective curve.
\uses{thm:ha-ch1-6-9,prop:ha-ch1-6-7}
\end{corollary}
\begin{proof}
The construction in Theorem~\ref{thm:ha-ch1-6-9} realizes the abstract curve attached to its
function field as an open subset of the complete nonsingular model.  Conversely, Proposition
~\ref{prop:ha-ch1-6-7} identifies a nonsingular quasi-projective curve with the corresponding open
subset of its DVR space.  The omitted set is finite because a quasi-projective curve has a finite
affine cover and the complete model is proper.
\end{proof}

\begin{corollary}[Nonsingular projective model]
\label{cor:ha-ch1-6-11}
\source{hartshorne-algebraic-geometry:I.6.11}
\dcref{I.6.11}
Every curve is birationally equivalent to a nonsingular projective curve.
\uses{thm:ha-ch1-6-9}
\end{corollary}
\begin{proof}
Apply Theorem 6.9 to its one-dimensional function field.
\end{proof}

\begin{corollary}[Equivalent categories of curves]
\label{cor:ha-ch1-6-12}
\source{hartshorne-algebraic-geometry:I.6.12}
\dcref{I.6.12}
The categories of nonsingular projective curves with dominant morphisms, quasi-projective curves
with dominant rational maps, and one-dimensional function fields over $k$ with $k$-homomorphisms
are equivalent.
\uses{prop:ha-ch1-6-8,thm:ha-ch1-6-9}
\end{corollary}
\begin{proof}
Use the function-field functor and the construction $K\mapsto C_K$.  Proposition 6.8 extends the
rational maps to complete models, and uniqueness in Theorem 6.9 proves that the composites are
identity functors up to canonical isomorphism.
\end{proof}

\section{Intersections in Projective Space}

\begin{proposition}[Affine dimension theorem]
\label{prop:ha-ch1-7-1}
\source{hartshorne-algebraic-geometry:I.7.1}
\dcref{I.7.1}
If $Y,Z\subset\mathbb A^n$ have dimensions $r,s$, every irreducible component of $Y\cap Z$ has
dimension at least $r+s-n$.
\end{proposition}
\begin{proof}
For a hypersurface, minimal primes over its equation have height one by Hauptidealsatz, giving
dimension $r-1$.  For general $Z$, identify $Y\cap Z$ with $(Y\times Z)\cap\Delta$ in
$\mathbb A^{2n}$; the diagonal is cut out by $n$ hypersurfaces, so iterating the hypersurface case
gives $(r+s)-n$.
\end{proof}

\begin{theorem}[Projective dimension theorem]
\label{thm:ha-ch1-7-2}
\source{hartshorne-algebraic-geometry:I.7.2}
\dcref{I.7.2}
For varieties $Y,Z\subset\mathbb P^n$ of dimensions $r,s$, every component of $Y\cap Z$ has
dimension at least $r+s-n$; if $r+s-n\ge0$, then $Y\cap Z\ne\varnothing$.
\uses{prop:ha-ch1-7-1}
\end{theorem}
\begin{proof}
The dimension assertion follows on affine charts from Proposition 7.1.  For nonemptiness, take
the affine cones, of dimensions $r+1,s+1$, which meet at the origin.  Proposition 7.1 gives their
intersection dimension at least $r+s-n+1>0$, so it contains a nonzero point, whose projective class
lies in $Y\cap Z$.
\end{proof}

\begin{definition}[Numerical and Hilbert polynomials]
\label{def:ha-ch1-hilbert-polynomial}
\source{hartshorne-algebraic-geometry:I.7}
A numerical polynomial is a polynomial taking integer values at all sufficiently large integers.
For a finite graded module, its Hilbert polynomial is the numerical polynomial agreeing eventually
with the Hilbert function.
\end{definition}

\begin{proposition}[Numerical polynomials]
\label{prop:ha-ch1-7-3}
\source{hartshorne-algebraic-geometry:I.7.3}
\dcref{I.7.3}
(a) Every numerical polynomial has a unique integer expansion \(P(z)=\sum_{i=0}^r c_i\binom zi\).
(b) If a function $f:\mathbb Z\to\mathbb Z$ has eventually numerical-polynomial first difference,
then $f$ agrees eventually with a numerical polynomial.
\end{proposition}
\begin{proof}
Induct on degree.  Since \(\Delta\binom zi=\binom z{i-1}\), the coefficients below the top
degree are integral by induction; eventual integrality of $P$ forces the top coefficient integral.
For (b), expand the difference in the binomial basis, sum it to a polynomial $P$, and observe that
$f-P$ is eventually constant.
\end{proof}

\begin{proposition}[Graded-module filtration]
\label{prop:ha-ch1-7-4}
\source{hartshorne-algebraic-geometry:I.7.4}
\dcref{I.7.4}
Every finite graded module over a noetherian graded ring has a finite graded filtration whose factors
are shifts of $S/\mathfrak p_i$ for homogeneous primes.  Every prime containing $\operatorname{Ann}M$
contains some $\mathfrak p_i$; the minimal such primes are the minimal primes of $M$, and each occurs
with multiplicity equal to $\length_{S_\mathfrak p}M_\mathfrak p$.
\end{proposition}
\begin{proof}
Choose a maximal graded submodule with such a filtration.  In the quotient choose a nonzero
homogeneous element with maximal annihilator; the annihilator is prime, since $abm=0$ and $bm\ne0$
force $a$ into the maximal annihilator.  Adjoining the cyclic submodule extends the filtration,
contradicting maximality unless it is all of $M$.  Localizing at a minimal prime leaves precisely
the factors with that prime, each contributing the residue field, proving the multiplicity claim.
\end{proof}

\begin{theorem}[Hilbert--Serre]
\label{thm:ha-ch1-7-5}
\source{hartshorne-algebraic-geometry:I.7.5}
\dcref{I.7.5}
For a finite graded module $M$ over $S=k[x_0,\ldots,x_n]$, the Hilbert function agrees for all
large integers with a unique polynomial $P_M(z)$, and \(\deg P_M=\dim Z(\operatorname{Ann}M)\).
\uses{prop:ha-ch1-7-4,thm:ha-ch1-7-2,prop:ha-ch1-7-3}
\end{theorem}
\begin{proof}
Use the filtration of Proposition 7.4 and induction on the dimension of the support.  For
$M=S/\mathfrak p$ choose $x_i\notin\mathfrak p$ and use
$0\to M(-1)\xrightarrow{x_i}M\to M/x_iM\to0$; the last support is the hyperplane section,
of one lower dimension by Theorem 7.2.  Proposition 7.3 integrates the first differences.  Additivity
of Hilbert functions over short exact sequences and the filtration prove the general case; eventual
polynomial equality gives uniqueness.
\end{proof}

\begin{definition}[Degree]
\label{def:ha-ch1-degree}
\source{hartshorne-algebraic-geometry:I.7}
The degree of a projective variety is the leading coefficient of its Hilbert polynomial multiplied
by the factorial of its dimension.
\end{definition}

\begin{proposition}[Degree]
\label{prop:ha-ch1-7-6}
\source{hartshorne-algebraic-geometry:I.7.6}
\dcref{I.7.6}
For nonempty $Y\subset\mathbb P^n$, $\deg Y$ is a positive integer.  If $Y=Y_1\cup Y_2$ has
same-dimensional components with smaller-dimensional intersection, degrees add; $\deg\mathbb P^n=1$;
and a hypersurface defined by a degree-$d$ form has degree $d$.
\uses{prop:ha-ch1-7-3}
\end{proposition}
\begin{proof}
The binomial expansion of Proposition 7.3 makes the leading coefficient integral and positive.
The exact sequence
\(0\to S/(I_1\cap I_2)\to S/I_1\oplus S/I_2\to S/(I_1+I_2)\to0\)
shows additivity because the last term has lower-dimensional support.  Since
$P_{\mathbb P^n}=\binom{z+n}{n}$, its degree is one.  Finally
$0\to S(-d)\xrightarrow f S\to S/(f)\to0$ gives
$P_{S/(f)}(z)=\binom{z+n}{n}-\binom{z-d+n}{n}$, whose degree is $d$.
\end{proof}

\begin{definition}[Intersection multiplicity]
\label{def:ha-ch1-intersection-multiplicity}
\source{hartshorne-algebraic-geometry:I.7}
The intersection multiplicity of a component in a hypersurface intersection is the length of the
corresponding localized graded module.
\end{definition}

\begin{theorem}[Intersection with a hypersurface]
\label{thm:ha-ch1-7-7}
\source{hartshorne-algebraic-geometry:I.7.7}
\dcref{I.7.7}
Let $Y\subset\mathbb P^n$ have dimension at least one and let $H$ be a hypersurface not containing
$Y$.  If $Z_1,\ldots,Z_s$ are the components of $Y\cap H$, and
$i(Y,H;Z_j)$ is the multiplicity of the corresponding minimal prime, then
\[
\sum_j i(Y,H;Z_j)\deg Z_j=(\deg Y)(\deg H).
\]
\uses{prop:ha-ch1-7-4}
\end{theorem}
\begin{proof}
For a degree-$d$ equation of $H$, the exact sequence
$0\to(S/I_Y)(-d)\to S/I_Y\to S/(I_Y+I_H)\to0$ gives
$P_M(z)=P_Y(z)-P_Y(z-d)$.  Comparing leading coefficients yields
$d\deg Y/(r-1)!$.  Filter $M$ as in Proposition 7.4; only minimal primes of dimension $r-1$
contribute to the leading coefficient, each with multiplicity $i(Y,H;Z_j)$ and degree $\deg Z_j$.
Equating the coefficients proves the formula.
\end{proof}

\begin{corollary}[Bezout]
\label{cor:ha-ch1-7-8}
\source{hartshorne-algebraic-geometry:I.7.8}
\dcref{I.7.8}
Distinct plane curves of degrees $d,e$ with finite intersection points $P_1,\ldots,P_s$ satisfy
$\sum_i i(Y,Z;P_i)=de$.
\uses{thm:ha-ch1-7-7}
\end{corollary}
\begin{proof}
Apply Theorem 7.7.  Each point has Hilbert polynomial $1$ and degree one.
\end{proof}

\section{What Is Algebraic Geometry?}

This final section is exposition: classification by birational equivalence and isomorphism, the
curve genus/moduli picture, intrinsic invariants, cohomology, arbitrary ground fields, abstract
varieties, reducible algebraic sets, and the transition to schemes.  It contains no numbered
definition, lemma, proposition, theorem, or corollary to include in the blueprint.

\label{chap:hartshorne-schemes}





\section{Sheaves}

\begin{definition}[Presheaf and sheaf]
\label{def:II-1-presheaf}
\source{hartshorne-algebraic-geometry:II.1}
\lean{Hartshorne.Presheaf, Hartshorne.Sheaf, Hartshorne.IsSheaf}
\leanok
A presheaf $\mathcal F$ on $X$ assigns an object $\mathcal F(U)$ to every open $U$ and restriction maps
$\mathcal F(U)\to\mathcal F(V)$ for $V\subset U$, functorially, with $\mathcal F(\varnothing)=0$.
It is a sheaf when sections that agree locally glue uniquely. The definitions apply to sets,
abelian groups, rings, and modules.
More explicitly, if $\{U_i\}$ covers $U$, then restriction to the $U_i$ is injective, and every
family $s_i\in\mathcal F(U_i)$ satisfying
$s_i|_{U_i\cap U_j}=s_j|_{U_i\cap U_j}$ comes from a unique $s\in\mathcal F(U)$.
\end{definition}

\begin{definition}[Stalks and morphisms]
\label{def:II-1-stalk}
\source{hartshorne-algebraic-geometry:II.1}
\lean{Hartshorne.Stalk, Hartshorne.germ, Hartshorne.stalkMap, Hartshorne.germ_restrict}
\leanok
The stalk is $\mathcal F_x=\varinjlim_{x\in U}\mathcal F(U)$. A morphism is a compatible family
of maps on opens and induces maps on stalks.  A germ is represented by a pair $(U,s)$ with $x\in U$;
$(U,s)$ and $(V,t)$ define the same germ exactly when $s$ and $t$ agree on some neighborhood of $x$
contained in $U\cap V$.
\uses{def:II-1-presheaf}
\end{definition}

\begin{proposition}[Sheaf isomorphisms are stalkwise]
\label{prop:II-1-1}
\source{hartshorne-algebraic-geometry:II.1.1}
\dcref{II.1.1}
\lean{Hartshorne.sheaf_iso_iff_stalkMap_iso}
\leanok
A morphism of sheaves is an isomorphism if and only if it induces an isomorphism on every stalk.
\uses{def:II-1-presheaf,def:II-1-stalk}
\end{proposition}
\begin{proof}
The forward implication is immediate. If all stalk maps are injective, a section whose germs vanish
has a cover on which it vanishes, hence is zero. If all are surjective, lift the germ of a target
section near each point; after shrinking, the lifts agree on overlaps by injectivity, and the sheaf
axiom glues them. The glued lift maps to the target section.
\end{proof}


\begin{proposition}[Sheafification]
\label{prop:II-1-2}
\source{hartshorne-algebraic-geometry:II.1.2}
\dcref{II.1.2}
\lean{Hartshorne.sheafification, Hartshorne.sheafification_condition,
Hartshorne.sheafification_stalkIso, Hartshorne.categoricalSheafification,
Hartshorne.categoricalSheafificationUnit, Hartshorne.categoricalSheafificationLift,
Hartshorne.categoricalSheafificationUnit_lift,
Hartshorne.categoricalSheafificationLift_unique,
Hartshorne.categoricalSheafificationUnit_stalk_isIso}
\leanok
Every presheaf $\mathcal F$ admits a sheafification $\mathcal F^a$ and a universal map
$\mathcal F\to\mathcal F^a$; it is unique up to unique isomorphism and has the same stalks as
$\mathcal F$.
\uses{def:II-1-presheaf,def:II-1-stalk}
\end{proposition}
\begin{proof}
Let $\mathcal F^a(U)$ be the functions assigning to each $x\in U$ a germ in $\mathcal F_x$ which,
locally at every $x$, is represented by a section of $\mathcal F$. These functions form a sheaf under
restriction; the germ map is universal because any map to a sheaf is determined locally.
\end{proof}

\begin{definition}[Direct and inverse image]
\label{def:II-1-direct-inverse}
\source{hartshorne-algebraic-geometry:II.1}
\lean{Hartshorne.directImage, Hartshorne.presheafDirectImage,
Hartshorne.presheafInverseImage, Hartshorne.sheafInverseImage,
Hartshorne.sheafInverseImageDirectImageAdjunction,
Hartshorne.directImage_presheaf_isSheaf}
\leanok
For a continuous $f:X\to Y$, define $(f_*\mathcal F)(V)=\mathcal F(f^{-1}V)$. The inverse image
$f^{-1}\mathcal G$ is the sheafification of $U\mapsto\varinjlim_{f(U)\subset V}\mathcal G(V)$.
Restriction to a subspace is inverse image under its inclusion.
\uses{def:II-1-presheaf,prop:II-1-2}
\end{definition}

For a morphism $\varphi:\mathcal F\to\mathcal G$ of presheaves, define the presheaf kernel,
cokernel, and image by
\[
U\longmapsto\ker\varphi(U),\qquad U\longmapsto\operatorname{coker}\varphi(U),
\qquad U\longmapsto\operatorname{im}\varphi(U).
\]
The kernel presheaf of a morphism of sheaves is a sheaf; in general the presheaf cokernel and image
must be sheafified.  Thus kernels are computed sectionwise, while cokernels and images in the sheaf
category are the associated sheaves of the sectionwise constructions.

\begin{definition}[Subsheaves, exactness, and quotients]
\label{def:II-1-subsheaf-exact}
\source{hartshorne-algebraic-geometry:II.1}
A subsheaf $\mathcal F'\subseteq\mathcal F$ is a sheaf whose sections are subgroups of the
sections of $\mathcal F$ and whose restrictions are induced.  The kernel of a sheaf morphism is its
sectionwise kernel, the image is the sheaf associated to its sectionwise image, and a morphism is
injective or surjective according as its kernel is zero or its image is the target.  A sequence is
exact when the image at every term equals the kernel at that term.  The quotient $\mathcal F/\mathcal F'$
is the sheaf associated to $U\mapsto\mathcal F(U)/\mathcal F'(U)$, with stalks
$(\mathcal F/\mathcal F')_x=\mathcal F_x/\mathcal F'_x$.
\uses{def:II-1-presheaf,def:II-1-stalk,prop:II-1-2}
\end{definition}

\section{Schemes}

\begin{lemma}[Closed sets in a spectrum]
\label{lem:II-2-1}
\source{hartshorne-algebraic-geometry:II.2.1}
\dcref{II.2.1}
\lean{Hartshorne.spectrumZeroLocus_mul, Hartshorne.spectrumZeroLocus_iSup,
Hartshorne.spectrumZeroLocus_eq_iff}
\leanok
For ideals $\mathfrak a,\mathfrak b\subset A$,
$V(\mathfrak a\mathfrak b)=V(\mathfrak a)\cup V(\mathfrak b)$,
$V(\sum_i\mathfrak a_i)=\bigcap_iV(\mathfrak a_i)$, and
$V(\mathfrak a)=V(\mathfrak b)$ iff $\sqrt{\mathfrak a}=\sqrt{\mathfrak b}$.
\end{lemma}
\begin{proof}
Use primality for the product formula, the definition of generated ideals for intersections, and
the fact that the radical is the intersection of all primes containing an ideal.
\end{proof}

\begin{definition}[Affine spectrum]
\label{def:II-2-spectrum}
\source{hartshorne-algebraic-geometry:II.2}
\lean{Hartshorne.AffineSpectrum, Hartshorne.spectrumZeroLocus,
Hartshorne.spectrumBasicOpen, Hartshorne.spectrumBasicOpen_isTopologicalBasis,
Hartshorne.affineSpec, Hartshorne.affineStructureSheaf}
 $\operatorname{Spec}A$ is the set of prime ideals with closed sets $V(\mathfrak a)$. Its structure
sheaf consists of locally represented fractions in the local rings $A_{\mathfrak p}$; $D(f)$ is a
basis of opens.
\uses{lem:II-2-1,def:II-1-presheaf}
\end{definition}

\begin{proposition}[Sections of the affine structure sheaf]
\label{prop:II-2-2}
\source{hartshorne-algebraic-geometry:II.2.2}
\dcref{II.2.2}
\lean{Hartshorne.affineStructureSheaf_stalk_isLocalization,
Hartshorne.affineStructureSheaf_stalk_iso, Hartshorne.affineSpec_stalk_iso,
Hartshorne.affineStructureSheaf_basicOpen_isLocalization,
Hartshorne.affineStructureSheaf_basicOpen_iso,
Hartshorne.affineStructureSheaf_globalSections_bijective,
Hartshorne.affineStructureSheaf_globalSectionsIso,
Hartshorne.affineSpec_globalSectionsIso}
\leanok
For $X=\operatorname{Spec}A$,
$\mathcal O_{X,\mathfrak p}=A_{\mathfrak p},\qquad
\Gamma(D(f),\mathcal O_X)=A_f,\qquad\Gamma(X,\mathcal O_X)=A$.
\uses{def:II-2-spectrum,def:II-1-stalk}
\end{proposition}
\begin{proof}
Evaluation gives the stalk map to $A_{\mathfrak p}$; a fraction represents a section on $D(f)$, proving
surjectivity. Equality of germs is equality after multiplying by an element outside $\mathfrak p$,
which proves injectivity. For $D(f)$, injectivity follows by taking annihilators and surjectivity by a
finite $D(h_i)$-cover, clearing denominators on overlaps, and using a power of $f$ in $(h_i)$.
\end{proof}

\begin{definition}[Ringed and locally ringed spaces]
\label{def:II-2-ringed}
\source{hartshorne-algebraic-geometry:II.2}
A ringed space is $(X,\mathcal O_X)$; a morphism $(f,f^\sharp)$ has a continuous $f$ and
$f^\sharp:\mathcal O_Y\to f_*\mathcal O_X$. It is locally ringed when all stalks are local and
morphisms induce local homomorphisms.
\uses{def:II-1-presheaf,def:II-1-stalk,def:II-1-direct-inverse}
\end{definition}

\begin{proposition}[Affine schemes and ring maps]
\label{prop:II-2-3}
\source{hartshorne-algebraic-geometry:II.2.3}
\dcref{II.2.3}
\lean{Hartshorne.affineSpecMap, Hartshorne.affineSpecMap_apply,
Hartshorne.affineSpecMap_continuous, Hartshorne.affineSpec_homEquiv,
Hartshorne.affineSpec_homEquiv_map, Hartshorne.affineSpec_map_homEquiv,
Hartshorne.affineSpec_stalk_isLocalRing,
Hartshorne.affineSpecMap_stalkMap_isLocalHom}
\leanok
$\operatorname{Spec}A$ is locally ringed. A ring map $A\to B$ induces
$\operatorname{Spec}B\to\operatorname{Spec}A$, and every morphism
$\operatorname{Spec}B\to\operatorname{Spec}A$ arises uniquely in this way.
\uses{prop:II-2-2}
\end{proposition}
\begin{proof}
The stalk assertion is Proposition \ref{prop:II-2-2}. A ring map sends a prime to its inverse image,
is continuous on $V(\mathfrak a)$, and localizes to maps $A_{\mathfrak p}\to B_{\mathfrak q}$. Conversely,
take global sections of a locally ringed-space morphism; the induced stalk map shows its underlying
point map is inverse-image of primes, and localization compatibility determines the sheaf map.
\end{proof}

\begin{definition}[Scheme and subschemes]
\label{def:II-2-scheme}
\source{hartshorne-algebraic-geometry:II.2}
An affine scheme is a locally ringed space isomorphic to an affine spectrum; a scheme is locally
affine. Open subschemes have restricted structure sheaves. A closed immersion is a homeomorphism
onto a closed subset with surjective structure-sheaf map.
\uses{def:II-2-spectrum,def:II-2-ringed}
\end{definition}

\begin{lemma}[Gluing schemes]
\label{lem:II-2-4}
\source{hartshorne-algebraic-geometry:II.2.4}
\dcref{II.2.4}
Schemes and morphisms glue from affine open charts and compatible overlap isomorphisms satisfying
the cocycle condition.
\end{lemma}
\begin{proof}
Glue the topological spaces and glue the compatible structure sheaves using the sheaf axioms;
the affine charts descend because overlaps are open subschemes. Morphisms glue locally.
\end{proof}

\begin{definition}[Proj]
\label{def:II-2-proj}
\source{hartshorne-algebraic-geometry:II.2}
For a graded ring $S$, $\operatorname{Proj}S$ is the homogeneous-prime space excluding the irrelevant
ideal, with basic opens $D_+(f)$, and structure sheaf given by degree-zero localizations.
\uses{def:II-2-spectrum,def:II-1-presheaf}
\end{definition}

\begin{proposition}[Proj charts]
\label{prop:II-2-5}
\source{hartshorne-algebraic-geometry:II.2.5}
\dcref{II.2.5}
The $D_+(f)$ form an affine open cover of $\operatorname{Proj}S$ and
$\Gamma(D_+(f),\mathcal O)=S_{(f)}$.
\uses{prop:II-2-2}
\end{proposition}
\begin{proof}
The homogeneous-prime topology is covered by $D_+(f)$ for positive-degree homogeneous $f$. Degree-zero
fractions glue exactly as in Proposition \ref{prop:II-2-2}, giving the affine chart ring $S_{(f)}$.
\end{proof}

\begin{proposition}[Projective space represents line bundles]
\label{prop:II-2-6}
\source{hartshorne-algebraic-geometry:II.2.6}
\dcref{II.2.6}
For a field $k$, a morphism $X\to\mathbb P^n_k$ is equivalent to an invertible sheaf $L$ on $X$ and
global sections $s_0,\ldots,s_n$ generating $L$, up to simultaneous multiplication by an isomorphism.
\uses{def:II-2-scheme,def:II-1-subsheaf-exact}
\end{proposition}
\begin{proof}
Pull back $\mathcal O(1)$ and its coordinate sections. Conversely, the ratios $s_i/s_j$ define compatible
maps to the standard affine charts; gluing gives the morphism and the two constructions are inverse.
\end{proof}

\section{First Properties of Schemes}

\begin{definition}[Connected, reduced, integral, normal]
\label{def:II-3-properties}
\source{hartshorne-algebraic-geometry:II.3}
A scheme is connected or irreducible according to its topological space, reduced when all affine
rings are reduced, integral when reduced and irreducible, and locally Noetherian when it has a cover
by spectra of Noetherian rings. An integral scheme is normal if its local rings are integrally closed.
\end{definition}

\begin{proposition}[Integral schemes]
\label{prop:II-3-1}
\source{hartshorne-algebraic-geometry:II.3.1}
\dcref{II.3.1}
A scheme is integral iff it is reduced and irreducible.
\end{proposition}
\begin{proof}
On an affine open, irreducibility says the nilradical is prime; reducedness makes it zero, so the
coordinate ring is a domain. The converse follows because spectra of domains are irreducible and
localization preserves domains.
\end{proof}

\begin{proposition}[Noetherian schemes]
\label{prop:II-3-2}
\source{hartshorne-algebraic-geometry:II.3.2}
\dcref{II.3.2}
A scheme is locally Noetherian iff every affine open has Noetherian coordinate ring; an affine scheme
is Noetherian iff its coordinate ring is Noetherian.
\end{proposition}
\begin{proof}
Localizations of Noetherian rings are Noetherian, so noetherian affine charts form a basis. If
$D(f_i)$ cover $\operatorname{Spec}A$ and each $A_{f_i}$ is Noetherian, quasi-compactness gives finitely
many $f_i$ generating the unit ideal. For an ideal chain, localization makes each chain stationary;
the equality $\mathfrak a=\bigcap_i(\mathfrak a A_{f_i}\cap A)$ proves the original chain stationary.
\end{proof}

\begin{definition}[Morphisms of finite type and finite]
\label{def:II-3-finite-type}
\source{hartshorne-algebraic-geometry:II.3}
A morphism is locally of finite type when affine chart rings are finitely generated algebras, of
finite type when finitely many charts suffice over each affine target, and finite when inverse images
of affine opens are affine with finite module coordinate rings.
\end{definition}

\begin{definition}[Dimension and codimension]
\label{def:II-3-dimension}
\source{hartshorne-algebraic-geometry:II.3}
Dimension is the supremum of chains of irreducible closed subsets; codimension is the supremum of
chains beginning at a given irreducible closed subset. For $\operatorname{Spec}A$ this is Krull dimension.
\end{definition}

\begin{theorem}[Fibred products]
\label{thm:II-3-3}
\source{hartshorne-algebraic-geometry:II.3.3}
\dcref{II.3.3}
For schemes $X,Y$ over $S$, $X\times_S Y$ exists and is unique up to unique isomorphism; for affine
schemes it is $\operatorname{Spec}(A\otimes_RB)$.
\uses{prop:II-2-3}
\end{theorem}
\begin{proof}
The affine case is the tensor-product universal property and Proposition \ref{prop:II-2-3}.
Products over affine opens are glued along products over overlaps. The resulting projections and
universal morphism glue from the corresponding affine constructions; uniqueness is local.
\end{proof}

\begin{definition}[Fibres and base extension]
\label{def:II-3-fibre}
\source{hartshorne-algebraic-geometry:II.3}
For $f:X\to Y$ and $y\in Y$, $X_y=X\times_Y\operatorname{Spec}\kappa(y)$. Base extension is
$X_{S'}=X\times_SS'$. Fibres and base extensions are associative up to canonical isomorphism.
\end{definition}

\section{Separated and Proper Morphisms}

\begin{definition}[Separated morphism]
\label{def:II-4-separated}
\source{hartshorne-algebraic-geometry:II.4}
A morphism $f:X\to Y$ is separated when its diagonal $\Delta_f:X\to X\times_YX$ is a closed immersion.
\end{definition}

\begin{proposition}[Affine morphisms are separated]
\label{prop:II-4-1}
\source{hartshorne-algebraic-geometry:II.4.1}
\dcref{II.4.1}
Every morphism of affine schemes is separated.
\uses{prop:II-2-3}
\end{proposition}
\begin{proof}
For $A\to B$, the diagonal corresponds to the multiplication map $B\otimes_AB\to B$, which is surjective;
Proposition \ref{prop:II-2-3} identifies it with a closed immersion.
\end{proof}

\begin{corollary}[Separatedness is local on the target]
\label{cor:II-4-2}
\source{hartshorne-algebraic-geometry:II.4.2}
\dcref{II.4.2}
A morphism is separated iff its restriction over every member of an open affine cover of the target is
separated.
\end{corollary}
\begin{proof}
The diagonal is compatible with base change by target opens; closed immersions are local on the target.
\end{proof}

\begin{theorem}[Valuative criterion for separatedness]
\label{thm:II-4-3}
\source{hartshorne-algebraic-geometry:II.4.3}
\dcref{II.4.3}
For a finite-type morphism $f:X\to Y$, $f$ is separated iff for every valuation ring $R$ with fraction field $K$,
a diagram $\operatorname{Spec}K\to X$ over $\operatorname{Spec}R\to Y$ has at most one extension
$\operatorname{Spec}R\to X$.
\end{theorem}
\begin{proof}
Two extensions define a map to the fibre product agreeing on the generic point, hence a map into the
diagonal. A closed diagonal contains the generic point of the valuation spectrum only through its
closed point, proving uniqueness. Conversely, failure of closedness gives a specialization in the
complement; the affine localization and domination lemma produce a valuation ring realizing two
extensions.
\end{proof}

\begin{lemma}[Valuation-ring diagrams]
\label{lem:II-4-4}
\source{hartshorne-algebraic-geometry:II.4.4}
\dcref{II.4.4}
Let $R$ be a valuation ring with fraction field $K$, $T=\operatorname{Spec}R$, and
$U=\operatorname{Spec}K$. A map $U\to X$ is a point $x_\eta$ with $k(x_\eta)=K$; a map
$T\to X$ is points $x_\eta,x_0$ with $x_0$ a specialization of $x_\eta$ and an inclusion
$k(x_\eta)=K$ such that $R$ dominates the local ring of $x_0$ on its reduced irreducible closure.
\end{lemma}
\begin{proof}
The generic point gives the first description. A map from $T$ factors through the reduced closure
of the image of its generic point, and the local homomorphism at the closed point is exactly a
domination by $R$; the converse is obtained by composing $\operatorname{Spec}R\to
\operatorname{Spec}\mathcal O_{x_0}$ with the inclusion into $X$.
\end{proof}

\begin{lemma}[Quasi-compact image criterion]
\label{lem:II-4-5}
\source{hartshorne-algebraic-geometry:II.4.5}
\dcref{II.4.5}
For a quasi-compact morphism $f:X\to Y$, the image $f(X)$ is closed if and only if it is stable
under specialization.
\end{lemma}
\begin{proof}
For the nontrivial implication, reduce to reduced affine $X,Y$ and write $X$ as a finite union of
affines. For a point in the closure of the image, choose a minimal prime below its corresponding
prime; localization and lying-over produce a point of one affine piece over that minimal point.
Stability under specialization then puts the original point in the image.
\end{proof}

\begin{corollary}[Stability of separated morphisms]
\label{cor:II-4-6}
\source{hartshorne-algebraic-geometry:II.4.6}
\dcref{II.4.6}
For noetherian schemes: open and closed immersions are separated; compositions, products over a
base, and base changes of separated morphisms are separated; if $gf$ is separated then $f$ is
separated when $g$ is separated; and separatedness is local on the target.
\end{corollary}
\begin{proof}
Apply the valuative criterion for separatedness and the fibre-product description of base change
and products; the diagonal criterion is local on the target.
\end{proof}

\begin{definition}[Proper morphism]
\label{def:II-4-proper}
\source{hartshorne-algebraic-geometry:II.4}
A morphism is proper if it is separated, of finite type, and universally closed.
\end{definition}

\begin{theorem}[Valuative criterion for properness]
\label{thm:II-4-7}
\source{hartshorne-algebraic-geometry:II.4.7}
\dcref{II.4.7}
For a finite-type morphism f, properness is equivalent to existence and uniqueness of a lift in every
valuation-ring diagram as above.
\end{theorem}
\begin{proof}
Properness gives existence because the image of the generic point in the closure of the image of
$\operatorname{Spec}R$ is closed and affine-localization yields a dominating valuation ring; uniqueness
is separatedness. Conversely, apply the lifting property to valuation rings dominating local rings
at points of a closure to show every image is closed, then use the separatedness criterion.
\end{proof}

\begin{corollary}[Stability of properness]
\label{cor:II-4-8}
\source{hartshorne-algebraic-geometry:II.4.8}
\dcref{II.4.8}
Proper morphisms are stable under composition and arbitrary base change; finite morphisms are proper.
\end{corollary}
\begin{proof}
The valuative criterion is preserved under base change and composition. A finite morphism is affine,
hence separated and finite type, and its image is closed because integral extensions satisfy lying over.
\end{proof}

\begin{theorem}[Projective morphisms are proper]
\label{thm:II-4-9}
\source{hartshorne-algebraic-geometry:II.4.9}
\dcref{II.4.9}
A projective morphism of Noetherian schemes is proper.
\end{theorem}
\begin{proof}
Closed immersions are proper. For $\mathbb P^n_Y\to Y$, homogenize the valuation-ring lifting problem
and, after scaling coordinates by a common element of K, choose a tuple in R with a unit coordinate;
this gives the lift. Apply stability under composition and closed immersion.
\end{proof}

\begin{proposition}[Varieties as schemes]
\label{prop:II-4-10}
\source{hartshorne-algebraic-geometry:II.4.10}
\dcref{II.4.10}
Over an algebraically closed field, the functor from varieties of Chapter I to schemes has image
the quasi-projective integral schemes of finite type; projective varieties correspond to projective
integral schemes. In particular the associated scheme of a variety is integral, separated, and of
finite type.
\end{proposition}
\begin{proof}
The construction on affine charts gives an integral finite-type scheme and glues to a
quasi-projective scheme. Conversely, the closed points of a projective integral scheme form an
irreducible projective variety dense in the scheme; reduced closed subschemes with the same support
are uniquely identified, and the quasi-projective case follows by an open immersion.
\end{proof}

\begin{definition}[Abstract variety]
\label{def:II-4-10-variety}
\source{hartshorne-algebraic-geometry:II.4.10}
An abstract variety is an integral separated scheme of finite type over an algebraically closed
field. A proper abstract variety is complete.
\end{definition}

\begin{theorem}[Integral closure by valuation rings]
\label{thm:II-4-11A}
\source{hartshorne-algebraic-geometry:II.4.11A}
\dcref{II.4.11A}
If $A$ is a subring of a field $K$, the integral closure of $A$ in $K$ is the intersection of all
valuation rings of $K$ containing $A$.
\end{theorem}
\begin{proof}
Hartshorne cites Bourbaki for this algebraic result and gives no proof.
\end{proof}

\section{Sheaves of Modules}

\begin{definition}[Modules and associated sheaves]
\label{def:II-5-module-sheaf}
\source{hartshorne-algebraic-geometry:II.5}
For an $A$-module $M$, define $\widetilde M$ on $\operatorname{Spec}A$ by
$\widetilde M(D(f))=M_f$. An $\mathcal O_X$-module is quasi-coherent if it is locally of this form, and
coherent on a Noetherian scheme if the modules are finitely generated.
\end{definition}

\begin{proposition}[Basic affine module identities]
\label{prop:II-5-1}
\source{hartshorne-algebraic-geometry:II.5.1}
\dcref{II.5.1}
For $\operatorname{Spec}A$, $(\widetilde M)_\mathfrak p=M_\mathfrak p$ and
$\Gamma(D(f),\widetilde M)=M_f$. The map $M\to\Gamma(\operatorname{Spec}A,\widetilde M)$ is an isomorphism.
\uses{prop:II-2-2}
\end{proposition}
\begin{proof}
The proof is the localization argument of Proposition \ref{prop:II-2-2}, with module fractions in place
of ring fractions.
\end{proof}

\begin{proposition}[Quasi-coherent sheaves on affines]
\label{prop:II-5-2}
\source{hartshorne-algebraic-geometry:II.5.2}
\dcref{II.5.2}
If $X=\operatorname{Spec}A$, then $M\mapsto\widetilde M$ is an equivalence between $A$-modules and
quasi-coherent sheaves, with quasi-inverse $\Gamma(X,-)$. For $A\to B$,
$f^*\widetilde M=\widetilde{M\otimes_AB}$.
\uses{prop:II-5-1}
\end{proposition}
\begin{proof}
The unit and counit are isomorphisms on each D(f) by Proposition \ref{prop:II-5-1}; localization
commutes with tensor products, giving the pullback formula.
\end{proof}

\begin{lemma}[Localization criterion]
\label{lem:II-5-3}
\source{hartshorne-algebraic-geometry:II.5.3}
\dcref{II.5.3}
If $f\in A$ and $\mathcal F$ is quasi-coherent on $\operatorname{Spec}A$, then
$\Gamma(D(f),\mathcal F)=\Gamma(X,\mathcal F)_f$.
\end{lemma}
\begin{proof}
It holds for associated sheaves and hence locally; restriction and gluing preserve the asserted
localization.
\end{proof}

\begin{proposition}[Local characterization]
\label{prop:II-5-4}
\source{hartshorne-algebraic-geometry:II.5.4}
\dcref{II.5.4}
An $\mathcal O_X$-module is quasi-coherent iff it is locally the cokernel of a morphism between free
modules; on a Noetherian scheme it is coherent iff the free modules may be chosen finite rank.
\end{proposition}
\begin{proof}
For $\widetilde M$ choose a presentation by free $A$-modules and localize. Conversely, local cokernel
descriptions give localized sections on basic opens and hence associated sheaves.
\end{proof}

\begin{corollary}[Affine equivalence]
\label{cor:II-5-5}
\source{hartshorne-algebraic-geometry:II.5.5}
\dcref{II.5.5}
The functors $M\mapsto\widetilde M$ and $\Gamma$ are mutually inverse on quasi-coherent sheaves.
\uses{prop:II-5-1}
\end{corollary}
\begin{proof}
The unit $M\to\Gamma(\operatorname{Spec}A,\widetilde M)$ and counit
$\widetilde{\Gamma(X,\mathcal F)}\to\mathcal F$ are isomorphisms on every basic open by
Proposition~\ref{prop:II-5-1}; the basic opens form a basis, so the maps are isomorphisms.
\end{proof}

\begin{proposition}[Exactness on affines]
\label{prop:II-5-6}
\source{hartshorne-algebraic-geometry:II.5.6}
\dcref{II.5.6}
For an affine scheme, a sequence of quasi-coherent sheaves is exact iff the sequence of global-section
modules is exact.
\end{proposition}
\begin{proof}
One implication follows from stalkwise exactness. For the converse, localize the exact sequence of
modules at every prime.
\end{proof}

\begin{proposition}[Operations on quasi-coherent modules]
\label{prop:II-5-7}
\source{hartshorne-algebraic-geometry:II.5.7}
\dcref{II.5.7}
Kernels, cokernels, images, and extensions of quasi-coherent sheaves are quasi-coherent; on a
Noetherian scheme the same holds for coherent sheaves.
\uses{prop:II-5-6}
\end{proposition}
\begin{proof}
Reduce to an affine. Kernels, cokernels and images follow from the module equivalence. For an extension,
global sections are exact by Proposition \ref{prop:II-5-6}; sheafify the resulting module sequence and
use the five lemma. Finite generation is preserved over Noetherian rings.
\end{proof}

\begin{proposition}[Direct and inverse image of modules]
\label{prop:II-5-8}
\source{hartshorne-algebraic-geometry:II.5.8}
\dcref{II.5.8}
For $f:X\to Y$, inverse images of quasi-coherent sheaves are quasi-coherent. Direct images are
quasi-coherent when X is Noetherian or f is quasi-compact and separated; in the Noetherian case
coherence is preserved by $f^*$.
\uses{prop:II-5-2,prop:II-5-7}
\end{proposition}
\begin{proof}
The affine cases follow from Proposition \ref{prop:II-5-2}. For direct image, cover a quasi-compact
source by finitely many affines; separatedness makes pairwise intersections affine, while Noetherianity
makes them quasi-compact and finitely coverable by affines. The equalizer sequence for compatible
sections and Proposition \ref{prop:II-5-7} give quasi-coherence.
\end{proof}

\begin{proposition}[Ideal sheaves and closed subschemes]
\label{prop:II-5-9}
\source{hartshorne-algebraic-geometry:II.5.9}
\dcref{II.5.9}
The ideal sheaf of a closed subscheme is quasi-coherent, coherent when X is Noetherian, and every
quasi-coherent ideal sheaf is the ideal sheaf of a unique closed subscheme.
\uses{prop:II-5-8,prop:II-5-7}
\end{proposition}
\begin{proof}
The ideal is the kernel of $\mathcal O_X\to i_*\mathcal O_Y$, so use Proposition \ref{prop:II-5-8}
and Proposition \ref{prop:II-5-7}. Conversely, locally write the ideal as $\widetilde{\mathfrak a}$;
the quotient defines $\operatorname{Spec}(A/\mathfrak a)$, and the affine constructions glue.
\end{proof}

\begin{corollary}[Affine closed subschemes]
\label{cor:II-5-10}
\source{hartshorne-algebraic-geometry:II.5.10}
\dcref{II.5.10}
Ideals of $A$ are in bijection with closed subschemes of $\operatorname{Spec}A$; every such closed subscheme
is affine.
\uses{prop:II-5-9}
\end{corollary}
\begin{proof}
For an ideal $\mathfrak a\subset A$, the quotient map $A\to A/\mathfrak a$ gives the closed immersion
$\operatorname{Spec}(A/\mathfrak a)\hookrightarrow\operatorname{Spec}A$.  Conversely, a closed subscheme
has a quasi-coherent ideal sheaf by Proposition~\ref{prop:II-5-9}; on the affine scheme this is
$\widetilde{\mathfrak a}$ for the ideal of its global sections, and the quotient is
$\operatorname{Spec}(A/\mathfrak a)$.  The two constructions are inverse.
\end{proof}

\begin{proposition}[Proj modules]
\label{prop:II-5-11}
\source{hartshorne-algebraic-geometry:II.5.11}
\dcref{II.5.11}
For graded $S$ and $M$, the associated sheaf on $\operatorname{Proj}S$ satisfies
$\Gamma(D_+(f),\widetilde M)=M_{(f)}$. It is quasi-coherent.
\end{proposition}
\begin{proof}
Apply the affine construction to each degree-zero localization and glue on overlaps.
\end{proof}

\begin{proposition}[Twisting sheaves]
\label{prop:II-5-12}
\source{hartshorne-algebraic-geometry:II.5.12}
\dcref{II.5.12}
The sheaf $\mathcal O_X(n)=\widetilde{S(n)}$ on $X=\operatorname{Proj}S$ is invertible when $X$ is
covered by standard affine charts; $\mathcal O_X(m)\otimes\mathcal O_X(n)\simeq\mathcal O_X(m+n)$.
\end{proposition}
\begin{proof}
On $D_+(f)$, multiplication of homogeneous fractions gives the trivialization; the transition functions
are units and are compatible with tensor products.
\end{proof}

\begin{proposition}[Generation and projective embedding]
\label{prop:II-5-13}
\source{hartshorne-algebraic-geometry:II.5.13}
\dcref{II.5.13}
For $S=A[x_0,\ldots,x_r]$ and $X=\operatorname{Proj}S=\mathbb P^r_A$, $\mathcal O_X(1)$ is invertible and
its coordinate sections generate it. A coherent sheaf on a projective scheme is generated after a
sufficiently positive twist.
\end{proposition}
\begin{proof}
The coordinate sections generate on each $D_+(x_i)$. For a coherent sheaf, choose finite affine
generators on the standard cover, clear denominators after a common twist, and use the finite cover
to obtain global generators.
\end{proof}

\begin{lemma}[Twisted localization]
\label{lem:II-5-14}
\source{hartshorne-algebraic-geometry:II.5.14}
\dcref{II.5.14}
Let $\mathcal L$ be invertible on $X$, let $s\in\Gamma(X,\mathcal L)$, and let $X_s$ be the
open set where $s$ is nonvanishing. If $X$ is quasi-compact and a section of a quasi-coherent
$\mathcal F$ vanishes on $X_s$, then some power of $s$ kills it. If $X$ has a finite affine cover
on which $\mathcal L$ is free and whose pairwise intersections are quasi-compact, every section
of $\mathcal F|_{X_s}$ becomes the restriction of a global section of $\mathcal F\otimes\mathcal L^n$
after multiplying by a sufficiently high power of $s$.
\end{lemma}
\begin{proof}
On each affine trivializing open this is the localization criterion for modules; quasi-compactness
allows finitely many powers to be replaced by one common power.
\end{proof}

\begin{proposition}[Proj reconstruction]
\label{prop:II-5-15}
\source{hartshorne-algebraic-geometry:II.5.15}
\dcref{II.5.15}
If $S$ is generated by $S_1$ over $S_0$, $X=\operatorname{Proj}S$, and $\mathcal F$ is
quasi-coherent, then the natural map $\widetilde{\Gamma_*(\mathcal F)}\to\mathcal F$ is an isomorphism.
\end{proposition}
\begin{proof}
On each standard affine $D_+(f)$, apply the preceding lemma to identify sections with the degree-zero
localization of $\Gamma_*(\mathcal F)$; these identifications agree on overlaps.
\end{proof}

\begin{corollary}[Projective schemes as Proj]
\label{cor:II-5-16}
\source{hartshorne-algebraic-geometry:II.5.16}
\dcref{II.5.16}
If $Y$ is a closed subscheme of $\mathbb P^r_A$, it is $\operatorname{Proj}(S/I)$ for a homogeneous
ideal $I\subset S=A[x_0,\ldots,x_r]$. A scheme over $\operatorname{Spec}A$ is projective iff it is
isomorphic to $\operatorname{Proj}S$ for a graded $S$ with $S_0=A$ finitely generated by $S_1$.
\uses{prop:II-5-15}
\end{corollary}
\begin{proof}
The ideal sheaf of $Y$ is quasi-coherent; Proposition~\ref{prop:II-5-15} identifies it with the
sheaf associated to its homogeneous module of global twisted sections. The converse follows by
presenting $S$ as a quotient of a polynomial ring.
\end{proof}

\begin{theorem}[Serre]
\label{thm:II-5-17}
\source{hartshorne-algebraic-geometry:II.5.17}
\dcref{II.5.17}
If $X$ is projective over a Noetherian ring $A$ and $\mathcal F$ is coherent, then
$\mathcal F(n)$ is generated by global sections for $n\gg0$ and $H^i(X,\mathcal F(n))=0$ for $i>0,n\gg0$.
\end{theorem}
\begin{proof}
Resolve $\mathcal F$ by finite sums of $\mathcal O_X(-m)$ on projective space. The Cech complex of the
standard affine cover computes cohomology; multiplication by powers of the homogeneous coordinates
makes its positive-degree cohomology vanish in high twists. Induct on the length of the resolution.
\end{proof}

\begin{corollary}[Coherent sheaves are quotients of twists]
\label{cor:II-5-18}
\source{hartshorne-algebraic-geometry:II.5.18}
\dcref{II.5.18}
On a projective scheme over a Noetherian ring, every coherent sheaf is a quotient of a finite direct
sum of twisted structure sheaves $\mathcal O_X(n)$.
\end{corollary}
\begin{proof}
By Serre, a sufficiently positive twist is generated by finitely many global sections; the resulting
surjection from a finite sum of $\mathcal O_X$ becomes the assertion after twisting back.
\end{proof}

\begin{theorem}[Finiteness of global sections]
\label{thm:II-5-19}
\source{hartshorne-algebraic-geometry:II.5.19}
\dcref{II.5.19}
If $X$ is projective over a field $k$ and $\mathcal F$ is coherent, then $\Gamma(X,\mathcal F)$ is finite-dimensional
over k. If X is projective over a finitely generated k-algebra A, it is a finite A-module.
\end{theorem}
\begin{proof}
For a graded presentation, reduce to twists on $\operatorname{Proj}S$. The graded module formed from
all sufficiently twisted global sections is integral over the coordinate ring and hence finite by
finiteness of integral closure; each graded piece is finite. The affine pushforward statement follows
from the affine module criterion.
\end{proof}

\begin{corollary}[Coherent direct image]
\label{cor:II-5-20}
\source{hartshorne-algebraic-geometry:II.5.20}
\dcref{II.5.20}
If $f:X\to Y$ is projective of finite type over a field and $\mathcal F$ is coherent, then
$f_*\mathcal F$ is coherent.
\end{corollary}
\begin{proof}
The assertion is affine-local on $Y$ and follows from finite generation of global sections over each
finitely generated coordinate ring.
\end{proof}

\section{Divisors}

\begin{definition}[Weil divisors]
\label{def:II-6-weil}
\source{hartshorne-algebraic-geometry:II.6}
On a Noetherian integral scheme regular in codimension one, a prime divisor is an integral closed
subscheme of codimension one. A Weil divisor is a finite sum $D=\sum n_Y Y$. The local ring at the
generic point of $Y$ is a DVR, giving $v_Y:K(X)^*\to\mathbb Z$.
\end{definition}

\begin{proposition}[Principal divisors]
\label{prop:II-6-1}
\source{hartshorne-algebraic-geometry:II.6.1}
\dcref{II.6.1}
For $f\in K(X)^*$, $(f)=\sum_Yv_Y(f)Y$ has finite support. Principal divisors form a subgroup of Weil
divisors.
\end{proposition}
\begin{proof}
On an affine where $f$ is regular, positive valuations occur only at components of $V(f)$; apply the same
argument to $f^{-1}$ on an affine where it is regular. The valuation identity
$v_Y(fg)=v_Y(f)+v_Y(g)$ proves additivity.
\end{proof}

\begin{definition}[Linear equivalence and class group]
\label{def:II-6-class}
\source{hartshorne-algebraic-geometry:II.6}
$D\sim D'$ when $D-D'=(f)$. The class group is $\operatorname{Cl}X=\operatorname{Div}X/\operatorname{Prin}X$.
\end{definition}

\begin{theorem}[Factoriality and the divisor class group]
\label{thm:II-6-2}
\source{hartshorne-algebraic-geometry:II.6.2}
\dcref{II.6.2}
Let $A$ be a noetherian domain and $X=\operatorname{Spec}A$.  Then $A$ is a
unique factorization domain if and only if $X$ is normal and $\operatorname{Cl}X=0$.
\end{theorem}
\begin{proof}
A UFD is integrally closed, hence $X$ is normal.  If every height-one prime is principal, every
prime divisor is principal and $\operatorname{Cl}X=0$.  Conversely, if $X$ is normal and its class
group is zero, a height-one prime divisor is linearly equivalent to zero, hence is the divisor of
an element of $K(X)^*$; valuation one at that prime and nonnegative valuations elsewhere show that
the element lies in $A$ and generates the prime.  The height-one criterion for a noetherian domain
then gives factoriality.
\end{proof}

\begin{proposition}[Intersection of height-one localizations]
\label{prop:II-6-3A}
\source{hartshorne-algebraic-geometry:II.6.3A}
\dcref{II.6.3A}
If $A$ is an integrally closed noetherian domain, then
\[
A=\bigcap_{\operatorname{ht}\mathfrak p=1}A_{\mathfrak p}
\]
inside the fraction field of $A$, where the intersection runs over all height-one prime ideals.
\end{proposition}
\begin{proof}
This is the standard intersection theorem for Krull domains; Hartshorne cites Matsumura for the
result and does not prove it in the text.
\end{proof}

\begin{definition}[Cartier divisors]
\label{def:II-6-cartier}
\source{hartshorne-algebraic-geometry:II.6}
A Cartier divisor is a compatible collection of rational functions modulo units. It determines an
invertible sheaf $\mathcal O_X(D)$; addition corresponds to tensor product and principal divisors give
$\mathcal O_X((f))\simeq\mathcal O_X$.
\end{definition}

\begin{proposition}[Divisors on projective space]
\label{prop:II-6-4}
\source{hartshorne-algebraic-geometry:II.6.4}
\dcref{II.6.4}
For $n\geq1$, every divisor on $\mathbb P^n$ is linearly equivalent to a unique multiple of a
hyperplane; hence $\operatorname{Cl}(\mathbb P^n)\simeq\mathbb Z$ generated by a hyperplane.
\end{proposition}
\begin{proof}
On the standard affine cover, clearing denominators shows that a divisor of degree zero is principal;
the degree map sends a hyperplane to $1$ and detects the unique multiple.
\end{proof}

\begin{proposition}[Restriction of divisors]
\label{prop:II-6-5}
\source{hartshorne-algebraic-geometry:II.6.5}
\dcref{II.6.5}
If $Y$ is a proper closed subset of a noetherian integral scheme $X$, restriction induces an exact
sequence $\operatorname{Div}_Y(X)\to\operatorname{Cl}(X)\to\operatorname{Cl}(X\setminus Y)\to0$.
\end{proposition}
\begin{proof}
A divisor on the open complement closes to a divisor on $X$, and changing the closure changes it by
a divisor supported on $Y$; principal divisors restrict to principal divisors.
\end{proof}

\begin{proposition}[Affine-line invariance of the class group]
\label{prop:II-6-6}
\source{hartshorne-algebraic-geometry:II.6.6}
\dcref{II.6.6}
If $X$ satisfies the standing hypotheses of this section, then $X\times\mathbb A^1$ also satisfies
them, and
\[
\operatorname{Cl}X\xrightarrow{\sim}\operatorname{Cl}(X\times\mathbb A^1)
\]
via pullback along the projection.
\end{proposition}
\begin{proof}
The product is noetherian, integral, and separated.  Codimension-one points are either pullbacks of
codimension-one points of $X$ or dominate $X$; the latter have local rings which are localizations
of $K(X)[t]$ and hence principal divisor class.  Sending a divisor to the sum of the pullbacks of
its components defines the inverse on class groups; valuation computations show that both composites
are the identity.
\end{proof}

\begin{proposition}[Divisors on nonsingular curves]
\label{prop:II-6-7}
\source{hartshorne-algebraic-geometry:II.6.7}
\dcref{II.6.7}
For a complete nonsingular curve, every Weil divisor is Cartier, and the divisor of a nonzero
rational function is the sum of its valuations at the closed points with finite support.
\end{proposition}
\begin{proof}
The local rings at closed points are DVRs, so local equations exist and glue as Cartier data; finite
support follows by applying regularity to the function and its inverse on affine neighborhoods.
\end{proof}

\begin{proposition}[Finite maps of curves]
\label{prop:II-6-8}
\source{hartshorne-algebraic-geometry:II.6.8}
\dcref{II.6.8}
A nonconstant map of complete nonsingular curves is finite. For $Q\in Y$,
$f^*Q=\sum_{f(P)=Q}v_P(t)P$, where $t$ is a uniformizer at $Q$, and this is independent of $t$.
\end{proposition}
\begin{proof}
A nonconstant map has zero-dimensional fibres; properness of complete curves makes it finite. A changed
uniformizer differs by a unit, whose pullback has valuation zero. Integral closure over the DVR at Q
gives the displayed ramification multiplicities.
\end{proof}

\begin{proposition}[Degree pullback]
\label{prop:II-6-9}
\source{hartshorne-algebraic-geometry:II.6.9}
\dcref{II.6.9}
For a finite map of nonsingular complete curves, $\deg f^*D=(\deg f)\deg D$.
\end{proposition}
\begin{proof}
It suffices to use one point $Q$. The integral closure of $\mathcal O_{Y,Q}$ is a free module of rank
[K(X):K(Y)]; its quotient by a uniformizer has length equal to that rank and also equals the sum
of the ramification indices.
\end{proof}

\begin{corollary}[Principal divisors have degree zero]
\label{cor:II-6-10}
\source{hartshorne-algebraic-geometry:II.6.10}
\dcref{II.6.10}
A principal divisor on a complete nonsingular curve has degree zero.
\end{corollary}
\begin{proof}
Apply the valuation theorem to multiplication by f on the finite-dimensional Riemann--Roch function
space, or compare zeros and poles through a finite map to $\mathbb P^1$; the total valuation sum is zero.
\end{proof}

\begin{proposition}[Cartier and Weil divisors]
\label{prop:II-6-11}
\source{hartshorne-algebraic-geometry:II.6.11}
\dcref{II.6.11}
On an integral separated noetherian normal scheme, Cartier divisors map to Weil divisors by taking
the valuations at codimension-one points, and this map identifies principal Cartier divisors with
principal Weil divisors.
\end{proposition}
\begin{proof}
At a codimension-one point the local ring is a DVR, so a local Cartier equation has a well-defined
order. Compatibility on overlaps gives a Weil divisor; normality makes the construction injective.
\end{proof}

\begin{proposition}[Invertible sheaves and duals]
\label{prop:II-6-12}
\source{hartshorne-algebraic-geometry:II.6.12}
\dcref{II.6.12}
For an invertible sheaf $\mathcal L$, its dual $\mathcal L^{-1}$ is invertible and
$\mathcal L\otimes\mathcal L^{-1}\simeq\mathcal O_X$; isomorphism classes form the Picard group
$\operatorname{Pic}(X)$ under tensor product.
\end{proposition}
\begin{proof}
Trivialize $\mathcal L$ on an open cover. The dual is locally free of rank one, and evaluation gives
the inverse; tensor product gives the group law.
\end{proof}

\begin{proposition}[Cartier divisors and the Picard group]
\label{prop:II-6-13}
\source{hartshorne-algebraic-geometry:II.6.13}
\dcref{II.6.13}
The map $D\mapsto\mathcal O_X(D)$ induces an isomorphism from Cartier divisors modulo principal
divisors to $\operatorname{Pic}(X)$.
\end{proposition}
\begin{proof}
Local equations give the invertible sheaf and changing equations by units gives an isomorphic sheaf.
Conversely, local generators of an invertible sheaf have rational ratios defining inverse Cartier data.
\end{proof}

\begin{corollary}[Cartier-to-Weil injectivity]
\label{cor:II-6-14}
\source{hartshorne-algebraic-geometry:II.6.14}
\dcref{II.6.14}
On an integral scheme, the map from Cartier divisors modulo principal divisors to the divisor class
group is injective.
\end{corollary}
\begin{proof}
If the associated Weil divisor is principal, divide the Cartier data by that rational function; the
resulting local equations are units, so the Cartier divisor is principal.
\end{proof}

\begin{proposition}[Effective Cartier divisors]
\label{prop:II-6-15}
\source{hartshorne-algebraic-geometry:II.6.15}
\dcref{II.6.15}
An effective Cartier divisor is locally defined by a non-zero-divisor. Its ideal sheaf is invertible,
and the quotient defines a closed subscheme of pure codimension one.
\end{proposition}
\begin{proof}
Multiplication by each local equation is injective and identifies the ideal with a free rank-one
module; the local quotients glue to the asserted closed subscheme.
\end{proof}

\begin{corollary}[Locally factorial schemes]
\label{cor:II-6-16}
\source{hartshorne-algebraic-geometry:II.6.16}
\dcref{II.6.16}
On a locally factorial scheme every Weil divisor is Cartier, and the Cartier and Weil class groups
are canonically isomorphic.
\end{corollary}
\begin{proof}
Codimension-one equations extend on factorial affine neighborhoods; apply the Cartier--Weil
identification above.
\end{proof}

\begin{corollary}[Class group of projective space]
\label{cor:II-6-17}
\source{hartshorne-algebraic-geometry:II.6.17}
\dcref{II.6.17}
For $n\geq1$, $\operatorname{Pic}(\mathbb P^n)\simeq\mathbb Z$, generated by $\mathcal O(1)$.
\uses{prop:II-6-4}
\end{corollary}
\begin{proof}
Combine Proposition~\ref{prop:II-6-4} with the Cartier-to-Weil identification.
\end{proof}

\begin{proposition}[Effective Cartier divisors and closed subschemes]
\label{prop:II-6-18}
\source{hartshorne-algebraic-geometry:II.6.18}
\dcref{II.6.18}
Effective Cartier divisors on $X$ are in bijection with closed subschemes whose ideal sheaf is
invertible and locally generated by a non-zero-divisor.
\end{proposition}
\begin{proof}
The two constructions are $D\mapsto\mathcal O_X(-D)$ and an invertible ideal with a local
non-zero-divisor generator to its vanishing divisor; the constructions are inverse.
\end{proof}

\section{Projective Morphisms}

\begin{definition}[Projective morphism]
\label{def:II-7-projective}
\source{hartshorne-algebraic-geometry:II.7}
A morphism is projective if it factors as a closed immersion $X\hookrightarrow\mathbb P^n_Y$. An
invertible sheaf is relatively very ample when it is the pullback of $\mathcal O(1)$ under such an embedding.
\end{definition}

\begin{theorem}[Morphisms to projective space]
\label{thm:II-7-1}
\source{hartshorne-algebraic-geometry:II.7.1}
\dcref{II.7.1}
A morphisms $f:X\to\mathbb P^n_Y$ is equivalent to an invertible sheaf $\mathcal L$ on $X$
together with generating global sections $s_0,\ldots,s_n$, up to the natural change of basis.
\end{theorem}
\begin{proof}
Pull back $\mathcal O(1)$ and its coordinate sections. Conversely, the ratios of the generating
sections define compatible maps to the standard affine charts and glue to $f$.
\end{proof}

\begin{proposition}[Closed immersion criterion]
\label{prop:II-7-2}
\source{hartshorne-algebraic-geometry:II.7.2}
\dcref{II.7.2}
A morphism defined by generating sections of an invertible sheaf is a closed immersion precisely
when the induced maps on the standard affine opens identify their coordinate rings with the relevant
affine coordinate rings.
\end{proposition}
\begin{proof}
Check the assertion on the standard affine cover of projective space; a morphism is a closed immersion
if and only if it is so on an affine open cover of the target.
\end{proof}

\begin{proposition}[Projective embedding criterion]
\label{prop:II-7-3}
\source{hartshorne-algebraic-geometry:II.7.3}
\dcref{II.7.3}
For a finite-type scheme over a field, a finite-dimensional space of sections of an invertible sheaf
defines a closed immersion into projective space iff it separates points and tangent vectors.
\end{proposition}
\begin{proof}
Point separation makes the map injective and an immersion on residue fields; tangent-vector separation
makes the induced local maps surjective on cotangent spaces. The affine criterion then gives a closed
immersion.
\end{proof}

\begin{lemma}[Finite generation from local maps]
\label{lem:II-7-4}
\source{hartshorne-algebraic-geometry:II.7.4}
\dcref{II.7.4}
If a local homomorphism of noetherian local rings induces a finite extension on residue fields and
the target is generated by finitely many elements over the image, then the corresponding morphism is
finite on a neighborhood.
\end{lemma}
\begin{proof}
Choose finitely many generators and clear denominators in the localizations; Nakayama's lemma gives
finite generation after shrinking.
\end{proof}

\begin{proposition}[Ample invertible sheaves]
\label{prop:II-7-5}
\source{hartshorne-algebraic-geometry:II.7.5}
\dcref{II.7.5}
For an invertible sheaf $\mathcal L$ on a noetherian scheme, the following are equivalent: $\mathcal L$
is ample; every coherent sheaf becomes generated by global sections after a positive twist; and a
sufficiently high power of $\mathcal L$ gives a projective embedding on every affine neighborhood.
\end{proposition}
\begin{proof}
The implications follow by applying the finite-generation lemma to affine standard opens and using
the point-and-tangent separation criterion.
\end{proof}

\begin{theorem}[Projective implies proper]
\label{thm:II-7-6}
\source{hartshorne-algebraic-geometry:II.7.6}
\dcref{II.7.6}
Every projective morphism is proper.
\end{theorem}
\begin{proof}
The projection $\mathbb P^n_Y\to Y$ satisfies the valuative criterion by scaling homogeneous coordinates
so one is a unit in the valuation ring. Closed immersions and compositions preserve properness.
\end{proof}

\begin{proposition}[Divisors of zeros and linear systems]
\label{prop:II-7-7}
\source{hartshorne-algebraic-geometry:II.7.7}
\dcref{II.7.7}
A nonzero section of an invertible sheaf determines an effective Cartier divisor of zeros. The
complete linear system of an invertible sheaf is the projective space of its nonzero global sections,
and its associated map is the map defined by those sections.
\end{proposition}
\begin{proof}
Locally trivialize the sheaf; the section is a non-zero-divisor equation and its local equations differ
by units. Ratios of a basis of global sections give the associated projective map.
\end{proof}

\begin{lemma}[Base-point-free linear systems]
\label{lem:II-7-8}
\source{hartshorne-algebraic-geometry:II.7.8}
\dcref{II.7.8}
A linear system has no base points precisely when its sections generate the associated invertible
sheaf; in that case it defines a morphism to projective space.
\uses{thm:II-7-1}
\end{lemma}
\begin{proof}
The stalkwise generation condition is exactly the absence of a common zero, and Theorem~\ref{thm:II-7-1}
then constructs the morphism.
\end{proof}

\begin{lemma}[Proj invariant under twisting]
\label{lem:II-7-9}
\source{hartshorne-algebraic-geometry:II.7.9}
\dcref{II.7.9}
For a graded ring $S$, $\operatorname{Proj}S\simeq\operatorname{Proj}S(d)$ after replacing the grading
by a positive twist; the standard opens and their structure sheaves are unchanged.
\end{lemma}
\begin{proof}
The homogeneous prime ideals and degree-zero localizations are unchanged by a common shift of degrees.
\end{proof}

\begin{theorem}[Relative Proj is projective]
\label{thm:II-7-10}
\source{hartshorne-algebraic-geometry:II.7.10}
\dcref{II.7.10}
If $S$ is a finitely generated graded algebra over $A=S_0$, then $\operatorname{Proj}S\to\operatorname{Spec}A$
is projective.
\end{theorem}
\begin{proof}
Choose homogeneous generators in degree one after a twist; the resulting graded surjection from a
polynomial ring gives a closed immersion into projective space over $A$.
\end{proof}

\begin{proposition}[Relative Proj of a symmetric algebra]
\label{prop:II-7-11}
\source{hartshorne-algebraic-geometry:II.7.11}
\dcref{II.7.11}
For a quasi-coherent module $\mathcal E$ on $Y$, $\operatorname{Proj}\operatorname{Sym}(\mathcal E)$
represents invertible quotients of the pullback of $\mathcal E$.
\end{proposition}
\begin{proof}
This is the affine universal property of Proj applied on a cover of $Y$, with the local constructions
glued by functoriality.
\end{proof}

\begin{proposition}[Universal property of relative Proj]
\label{prop:II-7-12}
\source{hartshorne-algebraic-geometry:II.7.12}
\dcref{II.7.12}
Morphisms $T\to\operatorname{Proj}\operatorname{Sym}(\mathcal E)$ over $Y$ are equivalent to pairs
consisting of an invertible sheaf on $T$ and a surjection from the pullback of $\mathcal E$.
\end{proposition}
\begin{proof}
The universal quotient gives the forward map; local generators of a quotient give homogeneous
coordinates and glue to the inverse.
\end{proof}

\begin{proposition}[Blow-up ideal]
\label{prop:II-7-13}
\source{hartshorne-algebraic-geometry:II.7.13}
\dcref{II.7.13}
For the blow-up $\operatorname{Bl}_\mathcal I X=\operatorname{Proj}\bigoplus_{n\geq0}\mathcal I^n$,
the inverse image of $\mathcal I$ is an invertible ideal sheaf.
\end{proposition}
\begin{proof}
On a standard Proj chart one generator of $\mathcal I$ becomes a unit times the tautological degree-one
generator, so the inverse image is locally principal and hence invertible.
\end{proof}

\begin{proposition}[Universal property of blow-up]
\label{prop:II-7-14}
\source{hartshorne-algebraic-geometry:II.7.14}
\dcref{II.7.14}
The blow-up of $X$ along $\mathcal I$ is universal among morphisms $g:Y\to X$ for which
$g^{-1}\mathcal I\mathcal O_Y$ is invertible.
\end{proposition}
\begin{proof}
An invertible pullback ideal gives a graded algebra map from the Rees algebra to the section algebra
of its powers, hence a unique map to Proj; the tautological ideal proves uniqueness.
\end{proof}

\begin{corollary}[Functoriality of blow-up]
\label{cor:II-7-15}
\source{hartshorne-algebraic-geometry:II.7.15}
\dcref{II.7.15}
If a morphism pulls one ideal sheaf into another, it induces the corresponding morphism of blow-ups;
in particular blow-up commutes with base change in the stated ideal-theoretic sense.
\end{corollary}
\begin{proof}
Apply the universal property to the pullback of the tautological invertible ideal.
\end{proof}

\begin{proposition}[Blow-ups of varieties]
\label{prop:II-7-16}
\source{hartshorne-algebraic-geometry:II.7.16}
\dcref{II.7.16}
The blow-up of a variety along a coherent ideal is projective over the variety and is again a variety.
\end{proposition}
\begin{proof}
Finite generation of the Rees algebra gives projectivity by relative Proj. On affine charts the Rees
algebra is a domain, and the resulting scheme is integral and separated.
\end{proof}

\begin{theorem}[Factorization through a blow-up]
\label{thm:II-7-17}
\source{hartshorne-algebraic-geometry:II.7.17}
\dcref{II.7.17}
Every projective morphism of noetherian schemes factors as a blow-up followed by a closed immersion
into projective space (after choosing a suitable coherent ideal).
\end{theorem}
\begin{proof}
Choose a relatively ample invertible sheaf and finitely many generating sections. The associated
graded algebra gives a Rees algebra after clearing denominators; the universal property of the blow-up
then supplies the factorization.
\end{proof}

\section{Differentials}

\begin{definition}[Kahler differentials]
\label{def:II-8-differentials}
\source{hartshorne-algebraic-geometry:II.8}
For $A\to B$, $\Omega_{B/A}$ represents $A$-derivations: it is generated by symbols $db$ with
$d(b+b')=db+db'$, $d(bb')=b\,db'+b'\,db$, and $da=0$.
\end{definition}

\begin{proposition}[Diagonal description]
\label{prop:II-8-1A}
\source{hartshorne-algebraic-geometry:II.8.1A}
\dcref{II.8.1A}
Let $B$ be an $A$-algebra, let $I$ be the kernel of the multiplication map
$B\otimes_A B\to B$, and define $db=1\otimes b-b\otimes1$ modulo $I^2$.  Then
$(I/I^2,d)$ is a module of relative differentials for $B/A$.
\end{proposition}
\begin{proof}
The displayed map satisfies the derivation identities.  Any $A$-derivation $B\to M$ induces a
$B$-linear map $I/I^2\to M$ by $b\otimes b'\mapsto b\,db'$, and this is the unique such map.
Hartshorne cites Matsumura for the construction.
\end{proof}

\begin{proposition}[Base change and localization]
\label{prop:II-8-2A}
\source{hartshorne-algebraic-geometry:II.8.2A}
\dcref{II.8.2A}
If $A'$ and $B$ are $A$-algebras and $B'=B\otimes_AA'$, then
$\Omega_{B'/A'}\simeq\Omega_{B/A}\otimes_BB'$.  If $S$ is a multiplicative system in $B$, then
$\Omega_{S^{-1}B/A}\simeq S^{-1}\Omega_{B/A}$.
\end{proposition}
\begin{proof}
Extend derivations uniquely across the base change and across inverses; the two universal properties
give the displayed isomorphisms.  Hartshorne cites Matsumura for the result.
\end{proof}

\begin{proposition}[First exact sequence]
\label{prop:II-8-3A}
\source{hartshorne-algebraic-geometry:II.8.3A}
\dcref{II.8.3A}
For ring maps $A\to B\to C$ there is a natural exact sequence of $C$-modules
\[
\Omega_{B/A}\otimes_BC\longrightarrow\Omega_{C/A}\longrightarrow\Omega_{C/B}\longrightarrow0.
\]
\end{proposition}
\begin{proof}
The first map is induced by composition of derivations.  A $B$-derivation is exactly an $A$-derivation
which kills the image of $B$, so the universal property gives exactness; the source cites Matsumura.
\end{proof}

\begin{proposition}[Second exact sequence]
\label{prop:II-8-4A}
\source{hartshorne-algebraic-geometry:II.8.4A}
\dcref{II.8.4A}
If $B$ is an $A$-algebra, $I\subset B$ an ideal, and $C=B/I$, then there is an exact sequence
\[
I/I^2\xrightarrow{\delta}\Omega_{B/A}\otimes_BC\longrightarrow\Omega_{C/A}\longrightarrow0,
\]
where $\delta(\bar b)=db\otimes1$.
\end{proposition}
\begin{proof}
Apply the diagonal description to the quotient map and use the universal property of $\Omega$;
the kernel consists precisely of differentials of elements of $I$, modulo $I^2$.  Hartshorne cites
Matsumura for this exact sequence.
\end{proof}

\begin{corollary}[Finite generation of differentials]
\label{cor:II-8-5}
\source{hartshorne-algebraic-geometry:II.8.5}
\dcref{II.8.5}
If $B$ is a finitely generated $A$-algebra, or a localization of one, then $\Omega_{B/A}$ is a
finitely generated $B$-module.
\end{corollary}
\begin{proof}
Present $B$ as a quotient of a polynomial algebra.  Its module of differentials is generated by the
coordinate differentials, and the second exact sequence and localization preserve finite generation.
\end{proof}

\begin{theorem}[Separability criterion]
\label{thm:II-8-6A}
\source{hartshorne-algebraic-geometry:II.8.6A}
\dcref{II.8.6A}
For a finitely generated extension field $K/k$, $\dim_K\Omega_{K/k}\ge\operatorname{trdeg}_kK$, with
equality if and only if $K/k$ is separably generated.
\end{theorem}
\begin{proof}
Choose a transcendence basis and apply the exact sequence to the finite algebraic extension over the
rational function field.  The basis differentials are independent, and the algebraic part contributes
no additional dimension exactly when it is separable; the source cites Matsumura.
\end{proof}

\begin{proposition}[Residue-field differentials]
\label{prop:II-8-7}
\source{hartshorne-algebraic-geometry:II.8.7}
\dcref{II.8.7}
Let $B$ be a local ring containing a field $k$ isomorphic to its residue field $B/\mathfrak m$.  Then
$\delta:\mathfrak m/\mathfrak m^2\to\Omega_{B/k}\otimes_Bk$ is an isomorphism.
\end{proposition}
\begin{proof}
The second exact sequence identifies the cokernel with $\Omega_{k/k}=0$.  A $k$-derivation on $B$
whose restriction to $\mathfrak m$ vanishes modulo $\mathfrak m^2$ is zero, proving injectivity.
\end{proof}

\begin{theorem}[Regularity via differentials]
\label{thm:II-8-8}
\source{hartshorne-algebraic-geometry:II.8.8}
\dcref{II.8.8}
Let $B$ be a local ring containing a perfect field $k$ isomorphic to its residue field, and assume
$B$ is a localization of a finitely generated $k$-algebra.  Then $\Omega_{B/k}$ is free of rank
$\dim B$ if and only if $B$ is a regular local ring.
\uses{prop:II-8-7}
\end{theorem}
\begin{proof}
By Proposition~\ref{prop:II-8-7}, $\mathfrak m/\mathfrak m^2$ is the cotangent space.  The exact
sequence and separability criterion identify its dimension with the rank of $\Omega_{B/k}$; equality
with $\dim B$ is the regular-local criterion.
\end{proof}

\begin{lemma}[Free-module criterion]
\label{lem:II-8-9}
\source{hartshorne-algebraic-geometry:II.8.9}
\dcref{II.8.9}
If $A$ is a noetherian local integral domain with residue field $k$ and quotient field $K$, and $M$ is
a finite $A$-module satisfying $\dim_k(M\otimes_Ak)=\dim_K(M\otimes_AK)=r$, then $M$ is free of rank $r$.
\end{lemma}
\begin{proof}
Nakayama gives a surjection $A^r\to M$.  Tensoring with $K$ shows that its kernel has rank zero;
torsion-freeness forces the kernel to vanish, so the map is an isomorphism.
\end{proof}

\begin{definition}[Sheaf of relative differentials]
\label{def:II-8-sheaf-differentials}
\source{hartshorne-algebraic-geometry:II.8}
For a morphism $f:X\to Y$ of schemes, the sheaf of relative differentials $\Omega_{X/Y}$ is obtained
on affine opens from the modules $\Omega_{B/A}$ and glued using localization; equivalently, it is
the pullback of the conormal sheaf of the diagonal $X\to X\times_YX$.
\end{definition}

\begin{proposition}[Base change for sheaf differentials]
\label{prop:II-8-10}
\source{hartshorne-algebraic-geometry:II.8.10}
\dcref{II.8.10}
For $f:X\to Y$ and $g:Y'\to Y$, with $X'=X\times_YY'$, one has
$\Omega_{X'/Y'}\simeq g'^*\Omega_{X/Y}$, where $g':X'\to X$ is the projection.
\uses{prop:II-8-2A}
\end{proposition}
\begin{proof}
Work on affine charts and apply Proposition~\ref{prop:II-8-2A}; the local isomorphisms agree on
overlaps by the universal property and therefore glue.
\end{proof}

\begin{proposition}[Transitivity sequence]
\label{prop:II-8-11}
\source{hartshorne-algebraic-geometry:II.8.11}
\dcref{II.8.11}
For morphisms $X\xrightarrow{f}Y\xrightarrow{g}Z$, there is an exact sequence
\[
f^*\Omega_{Y/Z}\longrightarrow\Omega_{X/Z}\longrightarrow\Omega_{X/Y}\longrightarrow0.
\]
\end{proposition}
\begin{proof}
The assertion is the sheafification of the first exact sequence on affine charts.
\end{proof}

\begin{proposition}[Closed-subscheme sequence]
\label{prop:II-8-12}
\source{hartshorne-algebraic-geometry:II.8.12}
\dcref{II.8.12}
If $Z\hookrightarrow X$ is a closed subscheme with ideal sheaf $\mathcal I$ and $X\to Y$ is a
morphism, then there is an exact sequence on $Z$
\[
\mathcal I/\mathcal I^2\xrightarrow{\delta}\Omega_{X/Y}\otimes\mathcal O_Z\longrightarrow\Omega_{Z/Y}\longrightarrow0.
\]
\end{proposition}
\begin{proof}
Apply the second exact sequence on affine charts and glue.  The map sends the class of a local
equation to its differential restricted to $Z$.
\end{proof}

\begin{theorem}[Euler sequence]
\label{thm:II-8-13}
\source{hartshorne-algebraic-geometry:II.8.13}
\dcref{II.8.13}
On $\mathbb P^n_A$,
\[
0\to\Omega_{\mathbb P^n_A/A}\to\mathcal O(-1)^{\oplus(n+1)}
\xrightarrow{(x_0,\ldots,x_n)}\mathcal O\to0.
\]
\end{theorem}
\begin{proof}
On each standard chart, identify differentials of $x_j/x_i$ and check that the kernel of the Euler
map is generated by these relations. The local descriptions agree on overlaps and exactness is
stalkwise.
\end{proof}

\begin{theorem}[Localization of regular local rings]
\label{thm:II-8-14A}
\source{hartshorne-algebraic-geometry:II.8.14A}
\dcref{II.8.14A}
If $(A,\mathfrak m)$ is a regular local ring, every localization $A_\mathfrak p$ is regular.
\end{theorem}
\begin{proof}
A regular system of parameters remains a minimal generating set after localization; the
dimension and embedding-dimension inequality then give regularity at each prime.
\end{proof}

\begin{theorem}[Differential criterion for nonsingularity]
\label{thm:II-8-15}
\source{hartshorne-algebraic-geometry:II.8.15}
\dcref{II.8.15}
For a variety over a perfect field, a point is nonsingular if and only if the stalk of
$\Omega_{X/k}$ is free of rank $\dim X$.
\uses{thm:II-8-6A}
\end{theorem}
\begin{proof}
Use the conormal sequence and Theorem~\ref{thm:II-8-6A}; the cotangent-space dimension equals
the local embedding dimension, which equals the dimension precisely for a regular local ring.
\end{proof}

\begin{corollary}[Open dense nonsingular locus]
\label{cor:II-8-16}
\source{hartshorne-algebraic-geometry:II.8.16}
\dcref{II.8.16}
For a variety over a perfect field, the nonsingular locus is open and dense.
\end{corollary}
\begin{proof}
The rank condition on a finite presentation of $\Omega_{X/k}$ is open, and the generic point is
nonsingular by the differential criterion.
\end{proof}

\begin{theorem}[Conormal characterization]
\label{thm:II-8-17}
\source{hartshorne-algebraic-geometry:II.8.17}
\dcref{II.8.17}
A finite-type variety $X$ over a perfect field is nonsingular if and only if $\Omega_{X/k}$ is
locally free of rank $\dim X$; for a closed immersion $X\hookrightarrow Y$ between nonsingular
varieties, the conormal sequence is exact on the left as well.
\uses{thm:II-8-15}
\end{theorem}
\begin{proof}
The first assertion is Theorem~\ref{thm:II-8-15}. In local polynomial coordinates, regularity
makes the defining equations a regular sequence, so the conormal map is injective.
\end{proof}

\begin{theorem}[Bertini for hyperplane sections]
\label{thm:II-8-18}
\source{hartshorne-algebraic-geometry:II.8.18}
\dcref{II.8.18}
If $X\subset\mathbb P^n$ is nonsingular over an infinite perfect field, a general hyperplane
section of $X$ is nonsingular (or empty).
\end{theorem}
\begin{proof}
The hyperplanes tangent to $X$ form a proper closed subset of the dual projective space by the
dimension estimate. Outside it, the conormal criterion gives a nonsingular section.
\end{proof}

\begin{theorem}[Birational invariance of geometric genus]
\label{thm:II-8-19}
\source{hartshorne-algebraic-geometry:II.8.19}
\dcref{II.8.19}
The geometric genus of a nonsingular projective variety is invariant under birational equivalence.
\end{theorem}
\begin{proof}
Resolve the birational correspondence on a common open set; regular top differential forms extend
across codimension at least two on a nonsingular variety, so the spaces and dimensions agree.
\end{proof}

\begin{corollary}[Canonical sheaf of projective space]
\label{cor:II-8-20}
\source{hartshorne-algebraic-geometry:II.8.20}
\dcref{II.8.20}
$\bigwedge^n\Omega_{\mathbb P^n_A/A}\simeq\mathcal O_{\mathbb P^n_A}(-n-1)$.
\end{corollary}
\begin{proof}
Take the top exterior power of the Euler sequence; the determinant of
$\mathcal O(-1)^{\oplus(n+1)}$ is $\mathcal O(-n-1)$.
\end{proof}

\begin{theorem}[Cohen--Macaulay criteria]
\label{thm:II-8-21A}
\source{hartshorne-algebraic-geometry:II.8.21A}
\dcref{II.8.21A}
For a noetherian local ring, a quotient of a regular local ring by a regular sequence is
Cohen--Macaulay; equivalently, its depth equals its dimension.
\end{theorem}
\begin{proof}
The Koszul complex of a regular sequence is a finite free resolution; its depth computation gives
the equality, and localization preserves the property.
\end{proof}

\begin{theorem}[Serre normality criterion]
\label{thm:II-8-22A}
\source{hartshorne-algebraic-geometry:II.8.22A}
\dcref{II.8.22A}
A noetherian ring is normal if and only if it satisfies $(R_1)$, regularity at codimension-one
primes, and $(S_2)$, depth at least the minimum of $2$ and the local dimension.
\end{theorem}
\begin{proof}
Apply the intersection description of integral closure in height-one valuation rings and the depth
criterion for extension across codimension at least two.
\end{proof}

\begin{proposition}[Local complete intersections]
\label{prop:II-8-23}
\source{hartshorne-algebraic-geometry:II.8.23}
\dcref{II.8.23}
A local complete intersection in a nonsingular variety is Cohen--Macaulay and is regular in
codimension one.
\uses{thm:II-8-21A}
\end{proposition}
\begin{proof}
Its ideal is locally generated by a regular sequence, so Theorem~\ref{thm:II-8-21A} gives
Cohen--Macaulayness; the codimension-one localizations are hypersurfaces in regular local rings.
\end{proof}

\begin{theorem}[Blow-up along a local complete intersection]
\label{thm:II-8-24}
\source{hartshorne-algebraic-geometry:II.8.24}
\dcref{II.8.24}
The blow-up of a nonsingular variety along a local complete intersection is nonsingular.
\end{theorem}
\begin{proof}
On an affine chart the center is generated by a regular sequence; the blow-up charts are polynomial
extensions of the quotient by all but one generator, hence regular by the Jacobian criterion.
\end{proof}

\begin{theorem}[Separable scalar extension]
\label{thm:II-8-25A}
\source{hartshorne-algebraic-geometry:II.8.25A}
\dcref{II.8.25A}
If $K/k$ is a separable field extension and $X$ is a nonsingular variety over $k$, then
$X_K=X\times_k\operatorname{Spec}K$ is nonsingular.
\end{theorem}
\begin{proof}
The exact differential sequence for $k\subset K$ and separability give $\Omega_{K/k}=0$; base
change therefore preserves the locally free differential criterion for nonsingularity.
\end{proof}

\section{Formal Schemes}

\begin{definition}[Adic rings and formal spectra]
\label{def:II-9-adic}
\source{hartshorne-algebraic-geometry:II.9}
An adic ring $A$ is complete and separated for the topology defined by an ideal of definition $I$. Its
formal spectrum $\operatorname{Spf}A$ has the open prime ideals containing a power of $I$ and the completed
structure sheaf.
\end{definition}

\begin{definition}[Formal completion]
\label{def:II-9-completion}
\source{hartshorne-algebraic-geometry:II.9}
For a closed subscheme defined by $\mathcal I$, the formal completion is the ringed space represented
by the compatible thickenings $X_n=(X,\mathcal O_X/\mathcal I^{n+1})$. A coherent formal module is a
compatible inverse system of coherent modules on $X_n$.
\end{definition}

\begin{proposition}[Affine formal schemes]
\label{prop:II-9-1}
\source{hartshorne-algebraic-geometry:II.9.1}
\dcref{II.9.1}
For an adic ring $A$, sections on a basic formal open are the corresponding completed localization;
the compatible quotients recover $A/I^{n+1}$, and $\operatorname{Spf}A$ is the inverse limit of
$\operatorname{Spec}(A/I^{n+1})$.
\end{proposition}
\begin{proof}
Complete the localization along the ideal of definition. Its reductions modulo $I^{n+1}$ are the
ordinary affine structure sheaves, and completeness identifies sections with the inverse limit.
\end{proof}

\begin{proposition}[Formal functions]
\label{prop:II-9-2}
\source{hartshorne-algebraic-geometry:II.9.2}
\dcref{II.9.2}
A morphism into a formal completion is equivalent to a compatible system of morphisms into all
infinitesimal thickenings; coherent formal modules are equivalent to compatible coherent systems
under adic completeness.
\end{proposition}
\begin{proof}
Take inverse limits on affine charts. Compatibility gives a continuous map of complete rings, and
the universal property of completion gives the converse. Finite generation permits passage between
modules and their adic completions.
\end{proof}


\begin{theorem}[Completed modules]
\label{thm:II-9-3A}
\source{hartshorne-algebraic-geometry:II.9.3A}
\dcref{II.9.3A}
For a Noetherian ring $A$ and ideal $I$, completion is exact on finitely generated modules, and the
completed module is finite over the completed ring; an already complete module is recovered by completion.
\end{theorem}
\begin{proof}
Artin--Rees identifies the induced filtrations, so inverse limits preserve the exact sequence; finite
generators complete to generators, and completeness gives the canonical isomorphism.
\end{proof}

\begin{proposition}[Formal affine schemes]
\label{prop:II-9-4}
\source{hartshorne-algebraic-geometry:II.9.4}
\dcref{II.9.4}
If $X=\operatorname{Spec}A$ and $Y=V(I)$, the formal completion is
$\operatorname{Spf}\widehat A$ with reductions $\operatorname{Spec}(A/I^{n+1})$.
\end{proposition}
\begin{proof}
Basic formal opens have completed localization rings, whose reductions are the affine structure sheaves
of the thickenings; taking the inverse limit gives $\operatorname{Spf}\widehat A$.
\end{proof}

\begin{proposition}[Independence of ideal of definition]
\label{prop:II-9-5}
\source{hartshorne-algebraic-geometry:II.9.5}
\dcref{II.9.5}
Any two ideals of definition on a Noetherian formal scheme give canonically the same formal scheme and
the same category of coherent formal modules.
\end{proposition}
\begin{proof}
Powers of either ideal contain powers of the other, so the inverse systems are cofinal and have
canonically isomorphic limits; the affine identifications glue.
\end{proof}

\begin{proposition}[Coherent formal modules]
\label{prop:II-9-6}
\source{hartshorne-algebraic-geometry:II.9.6}
\dcref{II.9.6}
A coherent formal module is locally the completion of a finite module, and each reduction modulo a
power of an ideal of definition is coherent.
\end{proposition}
\begin{proof}
Use finite presentations on affine formal charts; localization and completion commute for finite modules.
\end{proof}

\begin{theorem}[Formal coherent-module equivalence]
\label{thm:II-9-7}
\source{hartshorne-algebraic-geometry:II.9.7}
\dcref{II.9.7}
Coherent formal modules are equivalent to compatible systems of coherent modules on all infinitesimal
thickenings.
\end{theorem}
\begin{proof}
Reduction gives the compatible system. Conversely, lift finite affine presentations compatibly by
completeness, glue the resulting completions, and use the affine criterion to obtain inverse functors.
\end{proof}

\begin{corollary}[Exactness of completion]
\label{cor:II-9-8}
\source{hartshorne-algebraic-geometry:II.9.8}
\dcref{II.9.8}
Completion preserves short exact sequences of coherent formal modules.
\uses{thm:II-9-7}
\end{corollary}
\begin{proof}
Apply Theorem \ref{thm:II-9-7} and exactness on each finite thickening.
\end{proof}

\begin{corollary}[Kernels, cokernels, and images]
\label{cor:II-9-9}
\source{hartshorne-algebraic-geometry:II.9.9}
\dcref{II.9.9}
Kernels, cokernels, and images of morphisms of coherent formal modules are coherent.
\uses{thm:II-9-7}
\end{corollary}
\begin{proof}
Compute these objects on every thickening and apply Theorem \ref{thm:II-9-7}.
\end{proof}

\label{chap:hartshorne-cohomology}



\section{Derived functors}
\label{ha-ch3-sec1}

\begin{definition}[Abelian category, complexes, and exact functors]
\label{ha-ch3-def-abelian}
\source{hartshorne-algebraic-geometry:III.1}
An abelian category has abelian Hom groups, finite direct sums, kernels and
cokernels, and the usual normality and factorization axioms.  A complex is a
sequence $d^{i}:A^{i}\to A^{i+1}$ with $d^{i+1}d^i=0$; its cohomology is
$\ker d^i/\operatorname{im}d^{i-1}$.  A functor is left exact if it preserves
the left three terms of every short exact sequence.  An object is injective if
$\operatorname{Hom}(-,I)$ is exact, and an injective resolution is an exact
embedding into a complex of injectives.  An object is $F$-acyclic if
$R^iF(A)=0$ for $i>0$; a category has enough injectives if every object embeds
in an injective object.  For a left exact functor $F$, the derived functors are
$R^iF(A)=H^i(F(I^\bullet))$ for an injective resolution $I^\bullet$.
\end{definition}

\begin{theorem}[Derived functors]
\label{ha-ch3-thm-derived}
\dcref{III.1.1A}
\source{hartshorne-algebraic-geometry:III.1.1A}
If $\mathcal A$ has enough injectives and $F:\mathcal A\to\mathcal B$ is
additive left exact, then $R^iF(A)=H^i(F(I^\bullet))$ is independent of the
injective resolution and is functorial and additive.  There is a natural
isomorphism $R^0F\cong F$, and each short exact sequence
$0\to A'\to A\to A''\to0$ gives a functorial long exact sequence with
connecting maps $\delta^i:R^iF(A'')\to R^{i+1}F(A')$.  Morphisms of short
exact sequences commute with the connecting maps, and $R^iF(I)=0$ for
$i>0$ and $I$ injective.

\uses{ha-ch3-def-abelian}
\end{theorem}
\begin{proof}

Comparison maps between injective resolutions are unique up to homotopy, so
applying $F$ gives canonically isomorphic cohomology.  The short exact
sequence is replaced by a short exact sequence of resolutions; the long
exact cohomology sequence gives the connecting maps.  Homotopic comparison
maps induce the same cohomology maps.  An injective has the resolution
$0\to I\to I\to0$, proving the vanishing.

\end{proof}

\begin{proposition}[Acyclic resolutions]
\label{ha-ch3-prop-acyclic-resolution}
\dcref{III.1.2A}
\source{hartshorne-algebraic-geometry:III.1.2A}
If $0\to A\to J^0\to J^1\to\cdots$ is exact and every $J^i$ is
$F$-acyclic, then $R^iF(A)\cong H^i(F(J^\bullet))$ naturally.

\uses{ha-ch3-thm-derived,ha-ch3-def-abelian}
\end{proposition}
\begin{proof}

Embed the acyclic resolution and an injective resolution into a common
comparison diagram.  The quotient complexes are acyclic after applying $F$
by induction and the long exact sequence, hence the comparison is a
quasi-isomorphism.

\end{proof}

\begin{definition}[Cohomological $\delta$-functor and universality]
\label{ha-ch3-def-delta}
\source{hartshorne-algebraic-geometry:III.1}
A covariant $\delta$-functor is functors $T^i$ with connecting maps giving
long exact sequences and commuting with morphisms of short exact sequences.
It is universal if a map in degree zero to another $\delta$-functor extends
uniquely in every degree.  A functor is effaceable if every object embeds into
an object on which it vanishes.
\end{definition}

\begin{theorem}[Effaceability criterion]
\label{ha-ch3-thm-effaceable}
\dcref{III.1.3A}
\source{hartshorne-algebraic-geometry:III.1.3A}
An effaceable positive-degree $\delta$-functor is universal.

\uses{ha-ch3-def-delta}
\end{theorem}
\begin{proof}

Embed successively in objects killing the given positive-degree functor and
use the long exact sequence to define the extension degree by degree.  The
connecting maps force uniqueness.

\end{proof}

\begin{corollary}[Universal property of derived functors]
\label{ha-ch3-cor-universal-derived}
\dcref{III.1.4}
\source{hartshorne-algebraic-geometry:III.1.4}
For a left exact $F$ on a category with enough injectives, $(R^iF)$ is a
universal $\delta$-functor with degree zero $F$.  Conversely, every universal
$\delta$-functor has left exact degree zero and is naturally isomorphic to the
derived functors of that degree-zero functor.

\uses{ha-ch3-def-delta,ha-ch3-thm-effaceable,ha-ch3-thm-derived}
\end{corollary}
\begin{proof}

Every object embeds in an injective, so positive derived functors are
effaceable; apply III.1.3A.  The converse follows by applying universality to
the derived functors of $T^0$.

\end{proof}

\section{Cohomology of sheaves}
\label{ha-ch3-sec2}
\begin{proposition}[Enough injectives for modules]
\label{ha-ch3-prop-module-injective}\dcref{III.2.1A}
\source{hartshorne-algebraic-geometry:III.2.1A}
Every module over a ring embeds in an injective module.

\uses{ha-ch3-def-abelian}
\end{proposition}
\begin{proof}

Embed the module in its injective envelope, or equivalently apply Baer's criterion: extend the
identity map from the module to an injective hull and regard the hull as the required injective module.

\end{proof}
\begin{proposition}[Enough injective sheaves]
\label{ha-ch3-prop-sheaf-injective}\dcref{III.2.2}
\source{hartshorne-algebraic-geometry:III.2.2}
For every ringed space $(X,\mathcal O_X)$, the category of $\mathcal O_X$-modules
has enough injectives.

\uses{ha-ch3-def-abelian}
\end{proposition}
\begin{proof}

Embed each stalk $\mathcal F_x$ into an injective module $I_x$ and embed
$\mathcal F$ into the product of the skyscraper direct images $j_{x*}I_x$.
The target is injective because its Hom functor is a product of exact stalk
functors followed by exact Hom functors.

\end{proof}
\begin{corollary}[Enough injective abelian sheaves]
\label{ha-ch3-cor-sheaf-injective}\dcref{III.2.3}
\source{hartshorne-algebraic-geometry:III.2.3}
The category of sheaves of abelian groups on any topological space has enough
injectives.

\uses{ha-ch3-prop-sheaf-injective}
\end{corollary}
\begin{proof}

For an abelian sheaf $\mathcal F$, embed each stalk $\mathcal F_x$ in an injective abelian group
$I_x$.  The map sending a section to its germs embeds $\mathcal F$ in the product of the skyscraper
sheaves $i_{x*}I_x$.  A product of skyscraper injectives is injective: a map from a subsheaf extends
stalkwise, and the sheaf axiom assembles the extensions.

\end{proof}
\begin{definition}[Sheaf cohomology and flasque sheaves]
\label{ha-ch3-def-cohomology-flasque}
\source{hartshorne-algebraic-geometry:III.2}
For an abelian sheaf $\mathcal F$, $H^i(X,\mathcal F)$ is the $i$th right
derived functor of $\Gamma(X,-)$.  A sheaf is flasque when all restriction
maps are surjective.
\uses{ha-ch3-def-abelian,ha-ch3-thm-derived}
\end{definition}
\begin{lemma}[Injectives are flasque]
\label{ha-ch3-lem-injective-flasque}\dcref{III.2.4}
\source{hartshorne-algebraic-geometry:III.2.4}
Every injective $\mathcal O_X$-module is flasque.

\uses{ha-ch3-def-cohomology-flasque}
\end{lemma}
\begin{proof}

For $V\subset U$, the inclusion of extension-by-zero structure sheaves
$\mathcal O_V\hookrightarrow\mathcal O_U$ and injectivity give a surjection
$\operatorname{Hom}(\mathcal O_U,I)\to\operatorname{Hom}(\mathcal O_V,I)$,
which is $I(U)\to I(V)$.

\end{proof}
\begin{proposition}[Flasque acyclicity]
\label{ha-ch3-prop-flasque-acyclic}\dcref{III.2.5}
\source{hartshorne-algebraic-geometry:III.2.5}
If $\mathcal F$ is flasque, then $H^i(X,\mathcal F)=0$ for $i>0$.

\uses{ha-ch3-def-cohomology-flasque,ha-ch3-lem-injective-flasque}
\end{proposition}
\begin{proof}

Embed $\mathcal F$ in an injective $I$ and let $Q$ be the quotient.  Both
$I$ and $Q$ are flasque, and $0\to\Gamma(F)\to\Gamma(I)\to\Gamma(Q)\to0$
is exact.  The long exact sequence and induction on degree give the claim.

\end{proof}
\begin{proposition}[Global sections as derived functors]
\label{ha-ch3-prop-cohomology-derived}\dcref{III.2.6}
\source{hartshorne-algebraic-geometry:III.2.6}
The derived functors of $\Gamma(X,-)$ on $\mathcal O_X$-modules are the
groups $H^i(X,-)$ defined on abelian sheaves.

\uses{ha-ch3-def-cohomology-flasque,ha-ch3-thm-derived,ha-ch3-prop-acyclic-resolution}
\end{proposition}
\begin{proof}
Use an injective resolution, which is flasque by III.2.4 and
acyclic by III.2.5, and apply III.1.2A.
\end{proof}
\begin{theorem}[Grothendieck vanishing]
\label{ha-ch3-thm-grothendieck-vanishing}\dcref{III.2.7}
\source{hartshorne-algebraic-geometry:III.2.7}
If $X$ is noetherian of dimension $n$, then $H^i(X,\mathcal F)=0$ for every
abelian sheaf $\mathcal F$ and $i>n$.

\end{theorem}
\begin{proof}

Induct on dimension and number of irreducible components.  Reduce by the
closed/open exact sequence to an irreducible $X$.  Express a sheaf as a
filtered direct limit of finitely generated subsheaves; cohomology commutes
with these limits because limits of flasques are flasque on a noetherian
space.  Reduce a finitely generated sheaf to a quotient of a constant sheaf
on an open set.  The kernel is treated by noetherian induction on its support;
the constant sheaf on an irreducible space is flasque, and the closed
complement has smaller dimension.

\end{proof}
\begin{lemma}[Limits of flasque sheaves]
\label{ha-ch3-lem-limits-flasque}\dcref{III.2.8}
\source{hartshorne-algebraic-geometry:III.2.8}
On a noetherian space, a filtered direct limit of flasque sheaves is flasque.

\end{lemma}
\begin{proof}

For $V\subseteq U$, choose a finite affine (hence quasi-compact) cover of $U$ refining a cover on
which a representative section is defined.  Surjectivity of each restriction map in the system gives
compatible lifts on this finite cover; the sheaf axiom glues them.  Thus every section of the colimit
over $V$ lifts to $U$.

\end{proof}
\begin{proposition}[Cohomology and direct limits]
\label{ha-ch3-prop-cohomology-direct-limits}\dcref{III.2.9}
\source{hartshorne-algebraic-geometry:III.2.9}
For a filtered direct system of abelian sheaves on a noetherian space,
$H^i(X,\varinjlim\mathcal F_\alpha)\cong\varinjlim H^i(X,\mathcal F_\alpha)$;
in particular cohomology commutes with arbitrary direct sums.

\end{proposition}
\begin{proof}

The canonical maps form morphisms of delta-functors.  Efface both sides by
the functorial sheaf of discontinuous sections; the limit is flasque by
III.2.8, so universality (III.1.3A) identifies the two delta-functors.

\end{proof}
\begin{lemma}[Closed-subset extension]
\label{ha-ch3-lem-closed-extension}\dcref{III.2.10}
\source{hartshorne-algebraic-geometry:III.2.10}
For a closed inclusion $j:Y\hookrightarrow X$,
$H^i(Y,\mathcal F)\cong H^i(X,j_*\mathcal F)$.

\end{lemma}
\begin{proof}
Apply a flasque resolution on $Y$ and extend each term by zero.
\end{proof}

\section{Noetherian affine schemes}
\label{ha-ch3-sec3}
\begin{proposition}[Krull's theorem]
\label{ha-ch3-prop-krull}\dcref{III.3.1A}
\source{hartshorne-algebraic-geometry:III.3.1A}
If $A$ is noetherian, $M\subset N$ are finite $A$-modules and $\mathfrak a$
is an ideal, the $\mathfrak a$-adic topology on $M$ is induced from $N$.

\end{proposition}
\begin{proof}

The book cites the Artin--Rees lemma (Atiyah--Macdonald, or Bourbaki) for
this assertion; no independent proof is supplied here.

\end{proof}
\begin{lemma}[Torsion in an injective module]
\label{ha-ch3-lem-torsion-injective}\dcref{III.3.2}
\source{hartshorne-algebraic-geometry:III.3.2}
For an injective $A$-module $I$, the submodule $\Gamma_{\mathfrak a}(I)$ of
$\mathfrak a$-power torsion is injective.

\end{lemma}
\begin{proof}

For a map from an ideal $\mathfrak b$ to the torsion submodule, finite
generation and Krull's theorem make it factor through
$\mathfrak b/(\mathfrak b\cap\mathfrak a^n)$.  Extend this map to $A/\mathfrak a^n$
using injectivity of $I$; its image is torsion, proving Baer's criterion.

\end{proof}
\begin{lemma}[Localization of injectives]
\label{ha-ch3-lem-localize-injective}\dcref{III.3.3}
\source{hartshorne-algebraic-geometry:III.3.3}
For injective $I$ over a noetherian ring, $I\to I_f$ is surjective for every
$f\in A$.

\end{lemma}
\begin{proof}

The ascending annihilators of powers of $f$ stabilize.  Represent an element
of $I_f$ by $y/f^r$, extend the resulting map from the stabilized principal
ideal to $A$ by injectivity, and the image of $1$ maps to the given element.

\end{proof}
\begin{proposition}[Injective quasi-coherent sheaves are flasque]
\label{ha-ch3-prop-affine-injective-flasque}\dcref{III.3.4}
\source{hartshorne-algebraic-geometry:III.3.4}
If $I$ is injective over noetherian $A$, then $\widetilde I$ on
$\operatorname{Spec}A$ is flasque.

\end{proposition}
\begin{proof}

Use noetherian induction on the support.  Restriction to a principal open is
surjective by III.3.3; the difference is supported on the closed complement,
where its torsion submodule is injective by III.3.2 and induction applies.

\end{proof}
\begin{theorem}[Affine vanishing]
\label{ha-ch3-thm-affine-vanishing}\dcref{III.3.5}
\source{hartshorne-algebraic-geometry:III.3.5}
For $X=\operatorname{Spec}A$ noetherian and $\mathcal F$ quasi-coherent,
$H^i(X,\mathcal F)=0$ for $i>0$ and $\Gamma(X,\mathcal F)$ recovers its
module.
\end{theorem}
\begin{proof}
Resolve the module of global sections by injectives, sheafify,
and use III.3.4 and III.2.5; the resulting global-section complex is exact.
\end{proof}
\begin{corollary}[Flasque quasi-coherent embedding]
\label{ha-ch3-cor-flasque-qcoh}\dcref{III.3.6}
\source{hartshorne-algebraic-geometry:III.3.6}
Every quasi-coherent sheaf on a noetherian scheme embeds in a flasque
quasi-coherent sheaf.
\uses{ha-ch3-prop-affine-injective-flasque}
\end{corollary}
\begin{proof}

Cover $X$ by finitely many affine opens.  On each affine, embed the corresponding module in an
injective module and use Proposition~\ref{ha-ch3-prop-affine-injective-flasque}.  The resulting
local embeddings glue after taking their product; the product is quasi-coherent and flasque, and the
stalkwise maps give the required global embedding.

\end{proof}
\begin{theorem}[Serre's affineness criterion]
\label{ha-ch3-thm-serre-affine}\dcref{III.3.7}
\source{hartshorne-algebraic-geometry:III.3.7}
For a noetherian scheme $X$, the following are equivalent: $X$ is affine;
$H^i(X,\mathcal F)=0$ for every quasi-coherent $\mathcal F$ and $i>0$; and
$H^1(X,\mathcal J)=0$ for every coherent ideal sheaf $\mathcal J$.

\end{theorem}
\begin{proof}

The first implication is III.3.5.  For the converse, use vanishing for ideal
sheaves to find, around each closed point, an affine principal open $X_f$.
Choose finitely many $f_i$ covering $X$.  The kernel of
$\mathcal O_X^{\oplus m}\to\mathcal O_X$, $(a_i)\mapsto\sum f_i a_i$,
has a filtration with coherent ideal quotients, so its $H^1$ vanishes.  Global
sections therefore express $1$ as a combination of the $f_i$, and the affine
criterion applies.

\end{proof}

\section{Cech cohomology}
\label{ha-ch3-sec4}
\begin{definition}[Cech complex]
\label{ha-ch3-def-cech}
\source{hartshorne-algebraic-geometry:III.4}
For an ordered open cover $\mathfrak U=(U_i)$, set
$C^p(\mathfrak U,\mathcal F)=\prod_{i_0<\cdots<i_p}\mathcal F(U_{i_0\cdots i_p})$
with the alternating restriction differential, and define
$\check H^p(\mathfrak U,\mathcal F)=H^p(C^\bullet)$.
\end{definition}
\begin{lemma}[Cech degree zero]
\label{ha-ch3-lem-cech-zero}\dcref{III.4.1}
\source{hartshorne-algebraic-geometry:III.4.1}
The canonical map $H^0(\mathfrak U,\mathcal F)\to\Gamma(X,\mathcal F)$ is an
isomorphism.
\end{lemma}
\begin{proof}
A zero cocycle is a compatible family of sections, hence
glues uniquely by the sheaf axiom.
\end{proof}
\begin{lemma}[Sheafified Cech resolution]
\label{ha-ch3-lem-cech-resolution}\dcref{III.4.2}
\source{hartshorne-algebraic-geometry:III.4.2}
The sheafified Cech complex is a resolution of $\mathcal F$.

\end{lemma}
\begin{proof}

Exactness is stalkwise.  At a point choose one cover member containing it;
insertion of that index gives a contracting homotopy in positive degrees.

\end{proof}
\begin{proposition}[Flasque Cech acyclicity]
\label{ha-ch3-prop-cech-flasque}\dcref{III.4.3}
\source{hartshorne-algebraic-geometry:III.4.3}
If $\mathcal F$ is flasque, then $\check H^p(\mathfrak U,\mathcal F)=0$ for
$p>0$.
\end{proposition}
\begin{proof}
The sheafified resolution consists of flasque sheaves, so it
computes both derived and Cech cohomology, and III.2.5 gives vanishing.
\end{proof}
\begin{lemma}[Cech comparison map]
\label{ha-ch3-lem-cech-comparison-map}\dcref{III.4.4}
\source{hartshorne-algebraic-geometry:III.4.4}
There is a natural map $\check H^p(\mathfrak U,\mathcal F)\to H^p(X,\mathcal F)$,
functorial in $\mathcal F$.

\end{lemma}
\begin{proof}

The sheafified Cech resolution maps to an injective resolution of $\mathcal F$ by the comparison
theorem for resolutions.  Applying $\Gamma(X,-)$ gives a cochain map from the Cech complex to an
injective complex; its induced cohomology map is independent of the chosen comparison up to homotopy.

\end{proof}
\begin{theorem}[Cech comparison for affine covers]
\label{ha-ch3-thm-cech-comparison}\dcref{III.4.5}
\source{hartshorne-algebraic-geometry:III.4.5}
If $X$ is noetherian separated, $\mathfrak U$ is an affine open cover, and
$\mathcal F$ is quasi-coherent, then the comparison map is an isomorphism in
every degree.
\end{theorem}
\begin{proof}
Embed $\mathcal F$ in a flasque quasi-coherent sheaf and
induct on degree using the long exact sequences.  All finite intersections are
affine, so their section sequences are exact by III.3.5; the flasque term has
zero positive Cech cohomology by III.4.3.
\end{proof}

\section{Projective space}
\label{ha-ch3-sec5}
\begin{theorem}[Cohomology of projective space]
\label{ha-ch3-thm-projective-space}\dcref{III.5.1}
\source{hartshorne-algebraic-geometry:III.5.1}
Let $X=\mathbf P_A^r$, $r\ge1$, over noetherian $A$.  Then
$\bigoplus_nH^0(X,\mathcal O_X(n))\cong A[x_0,\ldots,x_r]$;
$H^i(X,\mathcal O_X(n))=0$ for $0<i<r$; $H^r(X,\mathcal O_X(-r-1))\cong A$;
and multiplication gives a perfect pairing
$H^0(\mathcal O(n))\times H^r(\mathcal O(-n-r-1))\to A$.

\end{theorem}
\begin{proof}

Use the standard affine cover and the Cech comparison theorem.  The top
Cech quotient is free on Laurent monomials with every exponent negative;
this gives the top group, its grading, and the pairing with nonnegative
monomials.  Localizing at $x_r$ makes the intermediate cohomology vanish;
the hyperplane exact sequence identifies multiplication by $x_r$ with a
bijective shift in intermediate degrees, while localization already makes
each class $x_r$-power torsion.  Thus those groups vanish.

\end{proof}
\begin{theorem}[Serre finiteness and eventual vanishing]
\label{ha-ch3-thm-serre-finiteness}\dcref{III.5.2}
\source{hartshorne-algebraic-geometry:III.5.2}
For $X$ projective over noetherian $A$ with a very ample $\mathcal O_X(1)$ and
$\mathcal F$ coherent, $H^i(X,\mathcal F)$ is finite over $A$, and
$H^i(X,\mathcal F(n))=0$ for $i>0$ and all $n\gg0$.

\end{theorem}
\begin{proof}

Embed $X$ in projective space and use III.5.1 for sums of twists.  Resolve a
coherent sheaf by a finite sum of twists and induct on the cohomological
degree using the long exact sequence; noetherianity preserves finite
generation and the same induction gives eventual vanishing.

\end{proof}
\begin{proposition}[Cohomological criterion for ampleness]
\label{ha-ch3-prop-ample-criterion}\dcref{III.5.3}
\source{hartshorne-algebraic-geometry:III.5.3}
For an invertible sheaf $\mathcal L$ on a proper noetherian $A$-scheme,
$\mathcal L$ is ample iff for every coherent $\mathcal F$,
$H^i(X,\mathcal F\otimes\mathcal L^n)=0$ for $i>0$ and $n\gg0$.

\end{proposition}
\begin{proof}

The forward implication follows after replacing $\mathcal L$ by a very ample
power and applying III.5.2 to finitely many residue classes of exponents.
Conversely apply vanishing to the ideal of each closed point; global sections
surject onto the skyscraper quotient, hence generate every twist locally by
Nakayama.  A finite cover and a common exponent show all coherent sheaves
are eventually generated, which is the ampleness criterion.

\end{proof}

\section{Ext groups and sheaves}
\label{ha-ch3-sec6}
\begin{definition}[Ext]
\label{ha-ch3-def-ext}
\source{hartshorne-algebraic-geometry:III.6}
$\mathcal H om(\mathcal F,\mathcal G)$ is the sheaf of local homomorphisms,
and $\mathcal E xt^i(\mathcal F,\mathcal G)$ is the $i$th right derived
functor of $\mathcal H om(\mathcal F,-)$.  The groups
$\operatorname{Ext}^i_X(\mathcal F,\mathcal G)$ are the right derived
functors of $\operatorname{Hom}_X(\mathcal F,-)$.
\end{definition}
\begin{lemma}[Restriction of injectives]\label{ha-ch3-lem-ext-restriction}\dcref{III.6.1}
\source{hartshorne-algebraic-geometry:III.6.1}
Injective sheaves remain injective after restriction to an open subset.

\end{lemma}
\begin{proof}

Restriction to an open subset has extension by zero as an exact left adjoint.  The adjunction and
injectivity of the original sheaf therefore extend every map into its restriction.

\end{proof}
\begin{proposition}[Restriction of sheaf Ext]\label{ha-ch3-prop-ext-restriction}\dcref{III.6.2}
\source{hartshorne-algebraic-geometry:III.6.2}
For $U\subset X$, $\mathcal E xt_X^i(\mathcal F,\mathcal G)|_U\cong
\mathcal E xt_U^i(\mathcal F|_U,\mathcal G|_U)$.
\uses{ha-ch3-lem-ext-restriction}
\end{proposition}
\begin{proof}

Restrict an injective resolution of $\mathcal G$ and use Lemma~\ref{ha-ch3-lem-ext-restriction}.
Restriction commutes with sheaf Hom, so the two resulting complexes agree on $U$ and have isomorphic
cohomology sheaves.

\end{proof}
\begin{proposition}[Ext from the structure sheaf]\label{ha-ch3-prop-ext-structure}\dcref{III.6.3}
\source{hartshorne-algebraic-geometry:III.6.3}
$\mathcal E xt^0(\mathcal O_X,\mathcal G)=\mathcal G$, higher sheaf Ext from
$\mathcal O_X$ vanishes, and $\operatorname{Ext}^i(\mathcal O_X,\mathcal G)=H^i(X,\mathcal G)$.

\end{proposition}
\begin{proof}

$\mathcal H om(\mathcal O_X,\mathcal G)=\mathcal G$, and $\mathcal O_X$ is locally free of rank one,
so its higher sheaf Ext vanishes.  Taking global sections of an injective resolution of $\mathcal G$
identifies global Ext with sheaf cohomology.

\end{proof}
\begin{proposition}[Long exact Ext sequences]\label{ha-ch3-prop-ext-les}\dcref{III.6.4}
\source{hartshorne-algebraic-geometry:III.6.4}
A short exact sequence in the first variable gives the usual long exact
sequences for both global Ext and sheaf Ext.

\end{proposition}
\begin{proof}
Apply Hom into an injective resolution; Hom into an injective is
exact in the first variable, and use the long exact cohomology sequence.
\end{proof}
\begin{proposition}[Locally free resolutions]\label{ha-ch3-prop-ext-resolution}\dcref{III.6.5}
\source{hartshorne-algebraic-geometry:III.6.5}
If $\mathcal F$ has a locally free finite-rank resolution $\mathcal L_\bullet$,
then $\mathcal E xt^i(\mathcal F,\mathcal G)=H^i(\mathcal H om(\mathcal L_\bullet,\mathcal G))$.

\end{proposition}
\begin{proof}

Apply $\mathcal H om(-,\mathcal G)$ to the resolution.  Since every $\mathcal L_j$ is locally free,
the resulting complex computes the derived Hom object and its cohomology is the stated sheaf Ext.

\end{proof}
\begin{lemma}[Tensoring injectives]\label{ha-ch3-lem-tensor-injective}\dcref{III.6.6}
\source{hartshorne-algebraic-geometry:III.6.6}
If $\mathcal L$ is locally free of finite rank and $I$ injective, then
$\mathcal L\otimes I$ is injective.

\end{lemma}
\begin{proof}

Locally $\mathcal L$ is finite free, so $\mathcal L\otimes I$ is a finite direct sum of copies of
$I$.  Finite direct sums of injectives are injective, and the assertion is local for sheaves.

\end{proof}
\begin{proposition}[Ext and locally free tensor factors]\label{ha-ch3-prop-ext-tensor}\dcref{III.6.7}
\source{hartshorne-algebraic-geometry:III.6.7}
$\operatorname{Ext}^i(\mathcal F\otimes\mathcal L,\mathcal G)\cong
\operatorname{Ext}^i(\mathcal F,\mathcal L^\vee\otimes\mathcal G)$, and likewise for sheaf Ext.

\end{proposition}
\begin{proof}

The adjunction $\mathcal H om(\mathcal F\otimes\mathcal L,\mathcal G)
\cong\mathcal H om(\mathcal F,\mathcal L^\vee\otimes\mathcal G)$ is termwise valid because
$\mathcal L$ is finite locally free.  Resolve $\mathcal G$ injectively and use the preceding lemma.

\end{proof}
\begin{proposition}[Stalks of sheaf Ext]\label{ha-ch3-prop-ext-stalk}\dcref{III.6.8}
\source{hartshorne-algebraic-geometry:III.6.8}
For coherent $\mathcal F$ on a noetherian scheme,
$(\mathcal E xt^i(\mathcal F,\mathcal G))_x\cong
\operatorname{Ext}^i_{\mathcal O_{X,x}}(\mathcal F_x,\mathcal G_x)$.

\end{proposition}
\begin{proof}
Work affine and use a free resolution of the coherent module;
stalks are exact and commute with Hom from finite free modules.
\end{proof}
\begin{proposition}[Ext twisting comparison]\label{ha-ch3-prop-ext-twist}\dcref{III.6.9}
\source{hartshorne-algebraic-geometry:III.6.9}
For coherent $\mathcal F,\mathcal G$ on projective $X$, and fixed $i$, for
$n\gg0$ the natural maps from global sections of $\mathcal E xt^i(\mathcal F,\mathcal G(n))$
to $\operatorname{Ext}^i(\mathcal F,\mathcal G(n))$ are isomorphisms.

\end{proposition}
\begin{proof}
Resolve $\mathcal F$ by locally free sheaves and induct on its
length, using III.5.2 and exactness of sufficiently twisted global sections.
\end{proof}
\begin{proposition}[Projective dimension]\label{ha-ch3-prop-projective-dimension}\dcref{III.6.10A}
\source{hartshorne-algebraic-geometry:III.6.10A}
For a module, projective dimension is the length of its shortest projective
resolution.

\end{proposition}
\begin{proof}

A projective resolution can be shortened exactly when the corresponding syzygy is projective.  Taking
the infimum of the lengths of all projective resolutions gives the invariant, with value $\infty$
when no finite resolution exists.

\end{proof}
\begin{proposition}[Regular local rings]\label{ha-ch3-prop-regular-local}\dcref{III.6.11A}
\source{hartshorne-algebraic-geometry:III.6.11A}
Over a regular local ring, finite projective dimension equals dimension minus
depth.

\end{proposition}
\begin{proof}

A regular local ring has finite global dimension $\dim A$.  The Auslander--Buchsbaum formula gives
$\operatorname{pd}_A M+\operatorname{depth}_A M=\operatorname{depth}A=\dim A$ for every finite module
$M$ of finite projective dimension.

\end{proof}
\begin{proposition}[Ext detects depth]\label{ha-ch3-prop-ext-depth}\dcref{III.6.12A}
\source{hartshorne-algebraic-geometry:III.6.12A}
The Ext groups against the residue field detect the depth of a finite module.

\end{proposition}
\begin{proof}

For $(A,\mathfrak m,k)$ local, take a minimal free resolution of $M$; all differentials have entries
in $\mathfrak m$, so after applying $\operatorname{Hom}_A(-,k)$ the differentials vanish.  The first
nonzero group $\operatorname{Ext}^i_A(k,M)$ is therefore in degree $\operatorname{depth}_A M$.

\end{proof}

\section{Serre duality}
\label{ha-ch3-sec7}
\begin{theorem}[Duality for projective space]\label{ha-ch3-thm-duality-projective}\dcref{III.7.1}
\source{hartshorne-algebraic-geometry:III.7.1}
For $X=\mathbf P_k^n$ and $\omega_X=\mathcal O_X(-n-1)$,
$H^n(X,\omega_X)\cong k$, the pairing
$\operatorname{Hom}(\mathcal F,\omega_X)\times H^n(X,\mathcal F)\to k$
is perfect, and $\operatorname{Ext}^i(\mathcal F,\omega_X)\cong
H^{n-i}(X,\mathcal F)^\vee$ for coherent $\mathcal F$.

\end{theorem}
\begin{proof}
The first assertion and the line-bundle case follow from III.5.1;
resolve a coherent sheaf by sums of twists and use the five lemma for degree
zero and universality of coeffaceable contravariant delta-functors in higher
degrees.
\end{proof}
\begin{definition}[Dualizing sheaf]\label{ha-ch3-def-dualizing}
\source{hartshorne-algebraic-geometry:III.7}
For proper $n$-dimensional $X/k$, a dualizing sheaf is coherent $\omega_X$ with
a trace $H^n(X,\omega_X)\to k$ inducing perfect Hom--top-cohomology pairings.
\end{definition}
\begin{proposition}[Uniqueness of dualizing sheaves]\label{ha-ch3-prop-dualizing-unique}\dcref{III.7.2}
\source{hartshorne-algebraic-geometry:III.7.2}
A dualizing sheaf with trace is unique up to a unique trace-preserving
isomorphism.
\end{proposition}
\begin{proof}
Use the representing property on the two sheaves to get
mutually inverse maps; uniqueness follows from the same property.
\end{proof}
\begin{lemma}[Ext vanishing by codimension]\label{ha-ch3-lem-ext-codim}\dcref{III.7.3}
\source{hartshorne-algebraic-geometry:III.7.3}
If $X\subset\mathbf P^N$ has codimension $r$, then
$\mathcal E xt^i(\mathcal O_X,\omega_{\mathbf P^N})=0$ for $i<r$.

\end{lemma}
\begin{proof}

At a point of $X$, a free resolution of the local defining ideal has length at least the codimension
by the depth inequality.  Applying $\operatorname{Hom}(-,\omega_{\mathbf P^N})$ therefore has no
cohomology below degree $r$; stalkwise vanishing gives the sheaf assertion.

\end{proof}
\begin{lemma}[The dualizing Ext sheaf]\label{ha-ch3-lem-dualizing-ext}\dcref{III.7.4}
\source{hartshorne-algebraic-geometry:III.7.4}
With $\omega_X=\mathcal E xt^r(\mathcal O_X,\omega_{\mathbf P^N})$,
$\operatorname{Hom}_X(\mathcal F,\omega_X)\cong
\operatorname{Ext}_{\mathbf P^N}^r(\mathcal F,\omega_{\mathbf P^N})$.
\uses{ha-ch3-lem-ext-codim}
\end{lemma}
\begin{proof}

Use the local-to-global Ext spectral sequence and the vanishing below $r$ from Lemma
~\ref{ha-ch3-lem-ext-codim}.  Its degree-$r$ edge map is the displayed isomorphism, compatible
with restriction to affine opens and hence global.

\end{proof}
\begin{proposition}[Existence of dualizing sheaves]\label{ha-ch3-prop-dualizing-existence}\dcref{III.7.5}
\source{hartshorne-algebraic-geometry:III.7.5}
Every projective scheme over a field has a dualizing sheaf.

\end{proposition}
\begin{proof}
Embed in projective space and use the Ext sheaf of III.7.4;
projective-space duality supplies the trace and representing property.
\end{proof}
\begin{theorem}[Duality for a projective scheme]\label{ha-ch3-thm-duality-projective-scheme}\dcref{III.7.6}
\source{hartshorne-algebraic-geometry:III.7.6}
For projective equidimensional $n$-fold $X/k$ with dualizing sheaf $\omega_X$,
there are natural maps $\operatorname{Ext}^i(\mathcal F,\omega_X)\to
H^{n-i}(X,\mathcal F)^\vee$.  They are all isomorphisms iff $X$ is
Cohen--Macaulay and equidimensional, equivalently iff every locally free
$\mathcal F$ has $H^i(X,\mathcal F(-q))=0$ for $i<n$ and $q\gg0$.

\end{theorem}
\begin{proof}
Universality gives the maps.  Embed in $\mathbf P^N$ and compare
depth/projective dimension with Ext vanishing to prove the equivalence of the
first two conditions.  Under the vanishing both contravariant delta-functors
are universal, so the maps are isomorphisms; the converse follows by taking
locally free sheaves and applying projective-space duality.
\end{proof}
\begin{corollary}[Cohen--Macaulay duality]\label{ha-ch3-cor-duality-cm}\dcref{III.7.7}
\source{hartshorne-algebraic-geometry:III.7.7}
For Cohen--Macaulay equidimensional projective $X$, duality holds for locally
free sheaves.
\uses{ha-ch3-thm-duality-projective-scheme}
\end{corollary}
\begin{proof}

For a Cohen--Macaulay equidimensional scheme, the depth criterion gives the vanishing hypothesis in
Theorem~\ref{ha-ch3-thm-duality-projective-scheme}; specialize that theorem to locally free
$\mathcal F$.

\end{proof}
\begin{corollary}[Normal vanishing]\label{ha-ch3-cor-normal-vanishing}\dcref{III.7.8}
\source{hartshorne-algebraic-geometry:III.7.8}
If $X$ is normal of dimension at least two, then
$H^i(X,\mathcal F(-q))=0$ for $i<2$ and $q\gg0$.
\uses{ha-ch3-thm-duality-projective-scheme}
\end{corollary}
\begin{proof}

Normality implies Serre's condition $S_2$, so local depth is at least two away from codimension one.
The Ext/depth criterion in Theorem~\ref{ha-ch3-thm-duality-projective-scheme} gives the stated
vanishing after a sufficiently negative twist.

\end{proof}
\begin{corollary}[Connected ample divisors]\label{ha-ch3-cor-connected-divisor}\dcref{III.7.9}
\source{hartshorne-algebraic-geometry:III.7.9}
An ample effective divisor on a normal projective variety of dimension at least
two is connected.

\end{corollary}
\begin{proof}

Apply the normal vanishing statement to the structure sheaf and use the exact
sequence of the divisor; the resulting $H^0$ calculation forces connectedness.

\end{proof}
\begin{proposition}[Koszul regular sequence]\label{ha-ch3-prop-koszul}\dcref{III.7.10A}
\source{hartshorne-algebraic-geometry:III.7.10A}
If $f_1,\ldots,f_r$ is an $M$-regular sequence, the positive homology of its
Koszul complex with coefficients in $M$ vanishes and degree zero is
$M/(f_1,\ldots,f_r)M$.

\end{proposition}
\begin{proof}

The book cites Matsumura (Theorem 43, p. 135) and Serre (IV.A) for the
Koszul exactness assertion; no proof is supplied here.

\end{proof}
\begin{theorem}[Dualizing sheaf of a local complete intersection]\label{ha-ch3-thm-lci-dualizing}\dcref{III.7.11}
\source{hartshorne-algebraic-geometry:III.7.11}
If $X\subset\mathbf P^N$ is a codimension-$r$ local complete intersection with
ideal $\mathcal I$, then
$\omega_X\cong\omega_{\mathbf P^N}\otimes\bigwedge^r(\mathcal I/\mathcal I^2)^\vee$;
it is invertible.
\end{theorem}
\begin{proof}
Locally resolve $\mathcal O_X$ by the Koszul complex of a
regular sequence.  Its dual computes the top Ext and changes by the
determinant under a change of generators, exactly compensated by
$\bigwedge^r(\mathcal I/\mathcal I^2)^\vee$.
\end{proof}
\begin{corollary}[Canonical sheaf on a nonsingular variety]\label{ha-ch3-cor-nonsingular-duality}\dcref{III.7.12}
\source{hartshorne-algebraic-geometry:III.7.12}
For a nonsingular projective variety, $\omega_X$ is the canonical sheaf.
\uses{ha-ch3-thm-lci-dualizing}
\end{corollary}
\begin{proof}

The conormal sequence for a nonsingular closed embedding is locally split with a regular sequence of
equations.  The local-complete-intersection formula of Theorem~\ref{ha-ch3-thm-lci-dualizing}
therefore identifies the dualizing sheaf with $\bigwedge^{\dim X}\Omega_X$.

\end{proof}
\begin{corollary}[Serre duality for nonsingular varieties]\label{ha-ch3-cor-serre-nonsingular}\dcref{III.7.13}
\source{hartshorne-algebraic-geometry:III.7.13}
Serre duality holds with the canonical sheaf; in particular
$H^n(X,\omega_X)\cong k$ and for curves $p_a=p_g$.
\uses{ha-ch3-thm-duality-projective-scheme}
\end{corollary}
\begin{proof}

Apply Theorem~\ref{ha-ch3-thm-duality-projective-scheme} with $\mathcal F=\mathcal O_X$ and use
the preceding identification of $\omega_X$.  For a curve, the equality of the dimensions of
$H^1(X,\mathcal O_X)$ and regular differentials is exactly $p_a=p_g$.

\end{proof}
\begin{theorem}[Existence of residues]\label{ha-ch3-thm-residues-existence}\dcref{III.7.14.1}
\source{hartshorne-algebraic-geometry:III.7.14.1}
Let $X$ be a complete nonsingular curve over an algebraically closed field
$k$, let $K$ be its function field, and let $\Omega_K$ be the space of
meromorphic differentials.  For each closed point $P$ there is a unique
$k$-linear map $\operatorname{res}_P:\Omega_K\to k$ such that, for a local
parameter $t$, $\operatorname{res}_P(t^n\,dt)=0$ for $n\ne-1$ and
$\operatorname{res}_P(t^{-1}dt)=1$.

\end{theorem}
\begin{proof}

The existence and parameter-independence are cited in the text to Serre,
*Algebraic Groups and Class Fields*, Chap. II, and to Tate's construction;
the book does not give a proof here.

\end{proof}
\begin{theorem}[Residue theorem]\label{ha-ch3-thm-residue-theorem}\dcref{III.7.14.2}
\source{hartshorne-algebraic-geometry:III.7.14.2}
For every $\omega\in\Omega_K$, $\sum_{P\in X}\operatorname{res}_P(\omega)=0$.

\end{theorem}
\begin{proof}

The residue theorem is cited in the text to Serre and Tate; no proof is
provided in Hartshorne at this point.

\end{proof}

\section{Higher direct images}
\label{ha-ch3-sec8}
\begin{definition}[Higher direct image]\label{ha-ch3-def-higher-direct-image}
\source{hartshorne-algebraic-geometry:III.8}
$R^if_*\mathcal F$ is the $i$th derived functor of direct image.
\end{definition}
\begin{proposition}[Stalk description]\label{ha-ch3-prop-direct-image-stalk}\dcref{III.8.1}
\source{hartshorne-algebraic-geometry:III.8.1}
The sheaf $R^if_*\mathcal F$ is the sheaf associated to
$U\mapsto H^i(f^{-1}U,\mathcal F)$.

\end{proposition}
\begin{proof}

Take an injective resolution $\mathcal F\to I^\bullet$.  Direct image is left exact, and on an
open $U\subseteq Y$ its cochain complex is $\Gamma(f^{-1}U,I^\bullet)$.  Its cohomology is
$H^i(f^{-1}U,\mathcal F)$, and sheafifying this presheaf gives $R^if_*\mathcal F$.

\end{proof}
\begin{corollary}[Restriction of direct images]\label{ha-ch3-cor-direct-image}\dcref{III.8.2}
\source{hartshorne-algebraic-geometry:III.8.2}
Restriction to an open $V\subset Y$ identifies $(R^if_*\mathcal F)|_V$ with
$R^i(f|_{f^{-1}V})_*\mathcal F$.

\end{corollary}
\begin{proof}

Restrict the complex in the preceding proof.  The sections on an open $W\subseteq V$ are still
$H^i(f^{-1}W,\mathcal F)$, so the associated sheaves agree.

\end{proof}
\begin{corollary}[Flasque vanishing]\label{ha-ch3-cor-flasque-vanishing}\dcref{III.8.3}
\source{hartshorne-algebraic-geometry:III.8.3}
$R^if_*$ vanishes on flasque sheaves.

\end{corollary}
\begin{proof}

For a flasque $\mathcal F$, every inverse-image open $f^{-1}U$ is flasque by restriction.  Its
positive cohomology vanishes, so the stalk description gives $R^if_*\mathcal F=0$ for $i>0$.

\end{proof}
\begin{proposition}[Direct image on module categories]\label{ha-ch3-prop-direct-image-composition}\dcref{III.8.4}
\source{hartshorne-algebraic-geometry:III.8.4}
Let $f:X\to Y$ be a morphism of ringed spaces.  The functors $R^if_*$ on
sheaves of modules are the derived functors of
$f_*:\operatorname{Mod}(X)\to\operatorname{Mod}(Y)$.
\uses{ha-ch3-prop-cohomology-derived}
\end{proposition}
\begin{proof}

This is the derived-functor comparison stated in the book; it follows by
calculating with injective resolutions and Proposition~III.2.6.

\end{proof}
\begin{proposition}[Affine direct images]\label{ha-ch3-prop-affine-direct-image}\dcref{III.8.5}
\source{hartshorne-algebraic-geometry:III.8.5}
Let $X$ be noetherian, let $f:X\to Y$ be a morphism of schemes, and let
$Y=\operatorname{Spec}A$ be affine.  For every quasi-coherent $\mathcal F$ on
$X$ there is a natural isomorphism
\[
R^if_*\mathcal F\cong\widetilde{H^i(X,\mathcal F)}.
\]

\end{proposition}
\begin{proof}

The text proves this by identifying both sides as universal delta-functors,
using the affine case and the vanishing of cohomology for flasque sheaves.

\end{proof}
\begin{corollary}[Quasi-coherence of direct images]\label{ha-ch3-cor-direct-image-affine}\dcref{III.8.6}
\source{hartshorne-algebraic-geometry:III.8.6}
Let $f:X\to Y$ be a morphism of schemes with $X$ noetherian.  If
$\mathcal F$ is quasi-coherent, then each $R^if_*\mathcal F$ is
quasi-coherent.
\uses{ha-ch3-prop-affine-direct-image}
\end{corollary}
\begin{proof}

This follows locally on affine opens of $Y$ from Proposition~III.8.5 and
the quasi-coherent affine calculation.

\end{proof}
\begin{corollary}[Separated affine computation]\label{ha-ch3-cor-separated-direct-image}\dcref{III.8.7}
\source{hartshorne-algebraic-geometry:III.8.7}
In the separated noetherian case, higher direct images are computed on affine
covers by Cech complexes.

\end{corollary}
\begin{proof}

Apply the affine-cover Cech comparison theorem to $f^{-1}U$ for each affine $U\subseteq Y$.
Separatedness makes finite intersections affine, and the identifications are compatible with
restriction in $U$, giving the claimed sheaf calculation.

\end{proof}
\begin{theorem}[Coherence of proper direct images]\label{ha-ch3-thm-direct-image-coherent}\dcref{III.8.8}
\source{hartshorne-algebraic-geometry:III.8.8}
Let $f:X\to Y$ be projective between noetherian schemes, let $\mathcal F$ be
coherent, and let $\mathcal L=\mathcal O_X(1)$ be very ample over $Y$.  Then
(a) for every $n>0$, the natural map
$f^*f_*\mathcal F(n)\to\mathcal F(n)$ is surjective; (b) each
$R^if_*\mathcal F$ is coherent; and (c) $R^if_*\mathcal F(n)=0$ for
$i>0$ and $n\gg0$.

\end{theorem}
\begin{proof}
Reduce to projective space, use the finite generation and eventual
vanishing of III.5.2 on affine opens, and glue the resulting finite modules.
\end{proof}

\section{Flat morphisms}
\label{ha-ch3-sec9}
\begin{proposition}[Flatness criteria]\label{ha-ch3-prop-flat-criteria}\dcref{III.9.1A}
\source{hartshorne-algebraic-geometry:III.9.1A}
For an $A$-module $M$ the following hold: (a) $M$ is flat iff
$-\otimes_A M$ is exact; (b) base extension preserves flatness; (c) flatness
is transitive; (d) flatness is local under localization; (e) in a short exact
sequence, if two terms are flat then so is the third; and (f) a finite module
over a local noetherian ring is flat iff it is free.

\end{proposition}
\begin{proof}

The proof is cited in the text to Atiyah--Macdonald, Chap. 2, and Bourbaki;
the book does not reprove these standard module-theoretic criteria here.

\end{proof}
\begin{definition}[Flat morphism]\label{ha-ch3-def-flat}
\source{hartshorne-algebraic-geometry:III.9}
A morphism is flat when the induced local ring maps are flat.
\end{definition}
\begin{proposition}[Localization and base change of flatness]\label{ha-ch3-prop-flat-preservation}\dcref{III.9.2}
\source{hartshorne-algebraic-geometry:III.9.2}
The properties of flat modules in Proposition~III.9.1A globalize: localization,
base change, and composition preserve flatness.
\uses{ha-ch3-prop-flat-criteria}
\end{proposition}
\begin{proof}

This follows from the corresponding module statements in
Proposition~III.9.1A, applied on affine charts.

\end{proof}
\begin{proposition}[Base change for quasi-coherent sheaves]\label{ha-ch3-prop-flat-base-change}\dcref{III.9.3}
\source{hartshorne-algebraic-geometry:III.9.3}
Let $f:X\to Y$ be a separated morphism of finite type between noetherian
schemes, let $g:Y'\to Y$ be flat, and let $X'=X\times_Y Y'$ with projection
$g':X'\to X$.  Then, for quasi-coherent $\mathcal F$,
\[
g^*R^if_*\mathcal F\simeq R^ig'_*g'^*\mathcal F.
\]

\end{proposition}
\begin{proof}

The proof is the Cech calculation on affine covers: flat base change tensors
the Cech complex with the new base ring, and separatedness keeps all finite
intersections affine.

\end{proof}
\begin{corollary}[Affine flat base change]\label{ha-ch3-cor-flat-affine}\dcref{III.9.4}
\source{hartshorne-algebraic-geometry:III.9.4}
If $Y=\operatorname{Spec}A$ and $y\in Y$ has residue field $k(y)$, then
\[
H^i(X,\mathcal F)\otimes_A k(y)\simeq H^i(X_y,\mathcal F_y)
\]
under the hypotheses of Proposition~III.9.3.
\uses{ha-ch3-prop-flat-base-change}
\end{corollary}
\begin{proof}

Apply Proposition~III.9.3 to the base change $\operatorname{Spec}k(y)\to Y$.

\end{proof}
\begin{proposition}[Flatness and fiber dimensions]\label{ha-ch3-prop-flat-fibers}\dcref{III.9.5}
\source{hartshorne-algebraic-geometry:III.9.5}
Let $f:X\to Y$ be a morphism of finite type over a field $k$, and assume
$f$ is flat.  Then for every $x\in X$, with $y=f(x)$,
\[
\dim_x(X_y)=\dim_xX-\dim_yY.
\]

\end{proposition}
\begin{proof}

This is the local dimension formula for a finite-type flat algebra, as cited
in the text.

\end{proof}
\begin{corollary}[Flat families over regular curves]\label{ha-ch3-cor-flat-curve}\dcref{III.9.6}
\source{hartshorne-algebraic-geometry:III.9.6}
Let $f:X\to Y$ be flat, of finite type over a field, with $Y$ irreducible.
If $Y$ is regular of dimension one, then the following are equivalent: every
associated point of $X$ maps to the generic point of $Y$, and every
irreducible component of every fiber has the expected dimension.
\uses{ha-ch3-prop-flat-fibers}
\end{corollary}
\begin{proof}

Use the non-zero-divisor criterion for a parameter of the regular curve and
the dimension formula of Proposition~III.9.5.

\end{proof}
\begin{proposition}[Flatness and associated points]\label{ha-ch3-prop-flat-specialization}\dcref{III.9.7}
\source{hartshorne-algebraic-geometry:III.9.7}
Let $f:X\to Y$ be a morphism with $Y$ integral and regular of dimension one.
Then $f$ is flat iff every associated point of $X$ maps to the generic point
of $Y$; if $X$ is reduced, this is equivalent to every irreducible component
of $X$ dominating $Y$.

\end{proposition}
\begin{proof}

This is the associated-point flatness criterion, proved in the text by the
local criterion for flatness.

\end{proof}
\begin{proposition}[Flat closure over a curve]\label{ha-ch3-prop-flat-limitations}\dcref{III.9.8}
\source{hartshorne-algebraic-geometry:III.9.8}
Let $Y$ be a regular integral curve, let $P\in Y$ be closed, and let
$X\subset\mathbf P^n_{Y-P}$ be flat over $Y-P$.  The scheme-theoretic closure
$\overline X\subset\mathbf P^n_Y$ is flat over $Y$.

\end{proposition}
\begin{proof}

The proof is the local associated-point argument given in the text: the
closure has no associated point over $P$, so the parameter of the regular
curve is a non-zero-divisor and the local criterion gives flatness.

\end{proof}
\begin{theorem}[Flat families of projective schemes]\label{ha-ch3-thm-flat-family}\dcref{III.9.9}
\source{hartshorne-algebraic-geometry:III.9.9}
For an integral noetherian base $T$ and a flat projective family
$X\subset\mathbf P_T^n$, the Hilbert polynomial of the fibers is constant.

\end{theorem}
\begin{proof}
The graded coordinate module is flat over the base in each large
degree; III.5.2 and the Hilbert polynomial calculation identify its fiber
dimensions, which therefore agree on the integral base.
\end{proof}
\begin{corollary}[Constancy on connected bases]\label{ha-ch3-cor-flat-family}\dcref{III.9.10}
\source{hartshorne-algebraic-geometry:III.9.10}
For connected bases the Hilbert polynomial is constant.

\end{corollary}
\begin{proof}

The coefficients of the fiber Hilbert polynomial are locally constant by the flat-family theorem.
An integer-valued locally constant function is constant on a connected base.

\end{proof}
\begin{theorem}[Normal families over a nonsingular curve]\label{ha-ch3-thm-normal-family}\dcref{III.9.11}
\source{hartshorne-algebraic-geometry:III.9.11}
An algebraic family of normal varieties parametrized by a nonsingular curve is
a flat family of schemes.
\uses{ha-ch3-lem-hironaka}
\end{theorem}
\begin{proof}

Flatness follows from the local flatness criterion.  At a point of a fiber,
let $t$ be a uniformizer on the curve and $\mathfrak p$ the unique minimal
prime over $(t)$.  The generic-point multiplicity hypothesis makes $t$ a
uniformizer in $A_{\mathfrak p}$, while the fiber's normality makes
$A/\mathfrak p$ normal.  Lemma III.9.12 gives $\mathfrak p=tA$, so the
scheme-theoretic fiber is reduced and equals the prescribed variety.

\end{proof}
\begin{lemma}[Hironaka]\label{ha-ch3-lem-hironaka}\dcref{III.9.12}
\source{hartshorne-algebraic-geometry:III.9.12}
For a local noetherian domain, the relevant intersection of principal ideals
in a flat finite-type algebra is controlled by the generic fiber; this gives
the specialization lemma used in the normal-family result.

\end{lemma}
\begin{proof}

Let $t$ be a parameter of the one-dimensional base and $A$ the local algebra.  Flatness makes $t$
 a non-zero-divisor, while normality of the generic and special fibers identifies the contraction of
 $(t)$ with the intersection of the height-one principal ideals above it.  Krull intersection then
 gives $\bigcap_{n\ge1}t^nA=0$ and the claimed control of the special fiber.

\end{proof}

\begin{corollary}[Normal-family genus]\label{ha-ch3-cor-normal-genus}\dcref{III.9.13}
\source{hartshorne-algebraic-geometry:III.9.13}
In a flat family of normal projective varieties the arithmetic genus is
constant.

\end{corollary}
\begin{proof}

The arithmetic genus is the fixed value of the Hilbert polynomial at $0$ (up to the usual sign and
constant term).  Apply the constancy of the Hilbert polynomial in a flat projective family.

\end{proof}

\section{Smooth morphisms}
\label{ha-ch3-sec10}
\begin{definition}[Smooth morphism]\label{ha-ch3-def-smooth}
\source{hartshorne-algebraic-geometry:III.10}
A finite-type morphism is smooth of relative dimension $n$ when it is flat and
its geometric fibers are nonsingular $n$-folds; equivalently it has the formal
lifting property and locally free relative differentials of rank $n$.
\end{definition}
\begin{proposition}[Differentials]\label{ha-ch3-prop-differentials}\dcref{III.10.1}
\source{hartshorne-algebraic-geometry:III.10.1}
For $X\to Y\to Z$ there is a right-exact sequence
$f^*\Omega_{Y/Z}\to\Omega_{X/Z}\to\Omega_{X/Y}\to0$; smoothness is
characterized by local freeness of the last term together with flatness.

\end{proposition}
\begin{proof}

For affine rings $A\to B\to C$, a $C$-derivation of $C$ over $A$ restricts to a $B$-derivation after
quotienting by derivations coming from $B$; the universal property gives the exact sequence.  Localize
to obtain the sheaf statement.  The infinitesimal lifting criterion identifies smoothness with
flatness and locally free relative differentials of the expected rank.

\end{proof}
\begin{theorem}[Jacobian criterion]\label{ha-ch3-thm-jacobian}\dcref{III.10.2}
\source{hartshorne-algebraic-geometry:III.10.2}
For finite-type schemes over a field, smoothness is equivalent to the expected
rank condition on differentials/Jacobian at every point.

\end{theorem}
\begin{proof}
Present the local algebra by generators and relations; the formal
lifting criterion is equivalent to solving the linearized relation equations,
which is exactly the Jacobian rank condition.
\end{proof}
\begin{lemma}[Regular local algebra]\label{ha-ch3-lem-regular-local}\dcref{III.10.3A}
\source{hartshorne-algebraic-geometry:III.10.3A}
The dimension, embedding dimension, and projective dimension relations for a
local homomorphism give the regularity criterion used in the smoothness proof.

\end{lemma}
\begin{proof}

For a local map $(A,\mathfrak m)\to(B,\mathfrak n)$, the conormal exact sequence compares
$\mathfrak n/\mathfrak n^2$ with $\Omega_{B/A}\otimes k(\mathfrak n)$.  The depth and dimension
equalities in a regular local ring make the Jacobian rank equal to the relative codimension; conversely
that rank equality forces the maximal ideal to be generated by the dimension number of parameters.

\end{proof}
\begin{proposition}[Composition and base change for smooth maps]\label{ha-ch3-prop-smooth-composition}\dcref{III.10.4}
\source{hartshorne-algebraic-geometry:III.10.4}
Composites and base changes of smooth morphisms are smooth.
\uses{ha-ch3-prop-differentials}
\end{proposition}
\begin{proof}

Flatness is stable under composition and tensor product.  The differential sequence in
Proposition~\ref{ha-ch3-prop-differentials} shows that the relative differentials of a composite are
locally free of the sum of the ranks, and base change preserves the same presentation and rank.

\end{proof}
\begin{lemma}[Generic separability]\label{ha-ch3-lem-generic-separable}\dcref{III.10.5}
\source{hartshorne-algebraic-geometry:III.10.5}
A dominant finite-type morphism of integral schemes is generically smooth
after removing the inseparable locus; in characteristic zero this holds
without a separability qualification.

\end{lemma}
\begin{proof}

Choose a separating transcendence basis of the extension of function fields.  The module of
Kähler differentials has the expected dimension after inverting one nonzero determinant of the
Jacobian.  Its nonvanishing locus is dense exactly when the extension is separable; in characteristic
zero every finite extension is separable.

\end{proof}
\begin{proposition}[Generic smoothness]\label{ha-ch3-prop-smooth-nonsingular}\dcref{III.10.6}
\source{hartshorne-algebraic-geometry:III.10.6}
A dominant morphism of nonsingular varieties is smooth on a dense open set.

\end{proposition}
\begin{proof}

At the generic point the induced extension of function fields is separable.  By the generic
separability lemma, a Jacobian minor is nonzero there; its nonvanishing locus is a dense open.  The
Jacobian criterion identifies the restriction over this open with a smooth morphism.

\end{proof}
\begin{corollary}[Generic smoothness over a perfect field]\label{ha-ch3-cor-bertini}\dcref{III.10.7}
\source{hartshorne-algebraic-geometry:III.10.7}
Over a perfect field, a finite-type morphism is smooth on a dense open when its
generic extension is separable.

\end{corollary}
\begin{proof}

The generic separability lemma gives a dense open where the differential rank is maximal.  Perfectness
 makes residue-field extensions separable, so geometric regularity agrees with regularity there; the
 Jacobian criterion then gives smoothness.

\end{proof}
\begin{theorem}[Homogeneous-space smoothness]\label{ha-ch3-thm-homogeneous}\dcref{III.10.8}
\source{hartshorne-algebraic-geometry:III.10.8}
A homogeneous space under an algebraic group is nonsingular, and its general
hyperplane sections satisfy the Bertini conclusion.

\end{theorem}
\begin{proof}

Translation by the group identifies all tangent spaces, so it is enough to check smoothness at the
identity coset, where the stabilizer quotient gives the expected tangent dimension.  Apply generic
smoothness to the universal hyperplane section to obtain the Bertini assertion.

\end{proof}
\begin{corollary}[Bertini theorem]\label{ha-ch3-cor-bertini-section}\dcref{III.10.9}
\source{hartshorne-algebraic-geometry:III.10.9}
A general hyperplane section of a nonsingular projective variety is
nonsingular under the stated characteristic hypotheses.

\end{corollary}
\begin{proof}

Apply the generic smoothness theorem to the universal hyperplane family.  The nonsmooth locus has
 proper image in the dual projective space, so a hyperplane outside that image has a nonsingular
 section.

\end{proof}

\section{Formal functions}
\label{ha-ch3-sec11}
\begin{theorem}[Theorem on formal functions]\label{ha-ch3-thm-formal-functions}\dcref{III.11.1}
\source{hartshorne-algebraic-geometry:III.11.1}
Let $f:X\to Y$ be projective noetherian, $y\in Y$, and $\mathcal F$ coherent.
Writing $X_n=X\times_Y\operatorname{Spec}(\mathcal O_{Y,y}/\mathfrak m_y^{n+1})$,
there is a natural isomorphism
\[\widehat{(R^if_*\mathcal F)}_y\cong\varprojlim_nH^i(X_n,\mathcal F|_{X_n}).\]

\end{theorem}
\begin{proof}
Embed $X$ in projective space, resolve $\mathcal F$ by sums of
twists, and apply the finite generation and eventual vanishing theorem to the
resulting complexes.  Completion commutes with their finite cohomology, and
passage to the inverse limit gives the displayed map and its inverse.
\end{proof}
\begin{corollary}[Completion and base change]\label{ha-ch3-cor-formal-functions}\dcref{III.11.2}
\source{hartshorne-algebraic-geometry:III.11.2}
The completed direct image is compatible with completion and base change.

\end{corollary}
\begin{proof}

Reduce the formal-functions isomorphism modulo $\mathfrak m_y^{n+1}$.  The inverse system is then the
 cohomology of the corresponding thickening, which is exactly the base-change complex; passing to the
 inverse limit gives the compatibility.

\end{proof}
\begin{corollary}[Affine formal functions]\label{ha-ch3-cor-formal-affine}\dcref{III.11.3}
\source{hartshorne-algebraic-geometry:III.11.3}
In the affine case, the completed direct-image modules are finite.

\end{corollary}
\begin{proof}

On an affine base, the cohomology modules in the theorem on formal functions are finite by
Serre finiteness.  Their inverse limit is therefore a finitely generated module over the completed
local ring.

\end{proof}
\begin{corollary}[Zariski main theorem]\label{ha-ch3-cor-zariski-main}\dcref{III.11.4}
\source{hartshorne-algebraic-geometry:III.11.4}
A proper birational morphism to a normal scheme has
$f_*\mathcal O_X=\mathcal O_Y$.

\end{corollary}
\begin{proof}

The inclusion $\mathcal O_Y\hookrightarrow f_*\mathcal O_X$ is an isomorphism over the generic point.
For a normal affine open $\operatorname{Spec}A\subset Y$, a section on $f^{-1}\operatorname{Spec}A$
lies in the fraction field and is regular at every codimension-one point because $f$ is proper and
birational.  Normality gives $A=\bigcap_{\operatorname{ht}\mathfrak p=1}A_{\mathfrak p}$, so the
section belongs to $A$.

\end{proof}
\begin{corollary}[Stein factorization]\label{ha-ch3-cor-stein}\dcref{III.11.5}
\source{hartshorne-algebraic-geometry:III.11.5}
A proper morphism factors through a finite morphism after taking the relative
Spec of its direct-image algebra.

\end{corollary}
\begin{proof}

Set $Y'=\operatorname{Spec}_Yf_*\mathcal O_X$.  Properness and coherence make $f_*\mathcal O_X$
 a finite $\mathcal O_Y$-algebra, so $Y'\to Y$ is finite.  The adjunction map $X\to Y'$ is proper
 with geometrically connected fibers, and its composite with $Y'\to Y$ is $f$.

\end{proof}

\section{Semicontinuity}
\label{ha-ch3-sec12}
\begin{proposition}[Universal complexes]\label{ha-ch3-prop-universal-complex}\dcref{III.12.1}
\source{hartshorne-algebraic-geometry:III.12.1}
For a bounded complex of finite free modules over a noetherian ring, its
cohomology after tensoring with a residue field is represented by a bounded
complex of finite free modules with differentials in the maximal ideal.

\end{proposition}
\begin{proof}

Over a local ring, split off every unit entry occurring in a differential.  Each such entry gives a
contractible two-term summand.  Removing all of them leaves a homotopy-equivalent complex whose
 differential matrices have entries in the maximal ideal; the construction localizes and glues.

\end{proof}
\begin{proposition}[Fiber dimensions of complexes]\label{ha-ch3-prop-fiber-dimensions}\dcref{III.12.2}
\source{hartshorne-algebraic-geometry:III.12.2}
The resulting fiber dimensions are controlled by the ranks of the
differentials.

\end{proposition}
\begin{proof}

For a complex of vector spaces, $\dim H^i=\dim C^i-\operatorname{rank}d^{i-1}-\operatorname{rank}d^i$.
Apply this identity after tensoring the universal complex with $k(y)$.

\end{proof}
\begin{lemma}[Minimal complexes]\label{ha-ch3-lem-minimal-complex}\dcref{III.12.3}
\source{hartshorne-algebraic-geometry:III.12.3}
Over a local ring, a complex with differentials in the maximal ideal has fiber
cohomology whose dimension is the rank of the corresponding free term minus
the ranks of adjacent differentials.

\end{lemma}
\begin{proof}

The differentials vanish after tensoring with the residue field, so the fiber cohomology is the
corresponding vector-space kernel modulo image.  Its dimension is the alternating rank expression in
the preceding proposition, and Nakayama lifts the rank conditions back to the local ring.

\end{proof}
\begin{proposition}[Equivalent complex conditions]\label{ha-ch3-prop-complex-conditions}\dcref{III.12.4}
\source{hartshorne-algebraic-geometry:III.12.4}
For a complex of finite free modules, the following are equivalent: a fiber
cohomology dimension is locally constant; the relevant cohomology module is
free and commutes with residue-field base change; and the neighboring
differential has the required constant rank.

\end{proposition}
\begin{proof}

Localize at a point and replace the complex by the minimal complex of III.12.1.  The rank formula of
III.12.2 shows that constant fiber dimension is equivalent to constant rank of the neighboring
differential.  A constant-rank map between finite free modules has locally free kernel and cokernel,
and tensoring with residue fields preserves them; the converse follows by taking dimensions.

\end{proof}
\begin{proposition}[Natural fiber map]\label{ha-ch3-prop-fiber-map}\dcref{III.12.5}
\source{hartshorne-algebraic-geometry:III.12.5}
There is a natural map from the cohomology of a finite complex tensored with
$k(y)$ to the cohomology of the tensor complex, and its kernel/cokernel are
controlled by the neighboring cohomology module.

\end{proposition}
\begin{proof}

Tensor the short exact sequences defining cycles and boundaries with $k(y)$ and use the resulting
Tor exact sequence.  The edge map from $H^i(C^\bullet)\otimes k(y)$ to $H^i(C^\bullet\otimes k(y))$
has kernel the image of $\operatorname{Tor}_1(H^{i+1}(C^\bullet),k(y))$ and cokernel a quotient of
$H^{i+1}(C^\bullet)[\mathfrak m_y]$.

\end{proof}
\begin{corollary}[Local freeness criterion]\label{ha-ch3-cor-local-free-cohomology}\dcref{III.12.6}
\source{hartshorne-algebraic-geometry:III.12.6}
Constancy of the relevant fiber dimension makes the cohomology module locally
free and makes the fiber map an isomorphism.
\uses{ha-ch3-prop-complex-conditions}
\end{corollary}
\begin{proof}

Use Proposition~\ref{ha-ch3-prop-complex-conditions}: constancy gives the required constant rank,
so the cohomology module is locally free and the Tor terms in the natural fiber map vanish.

\end{proof}
\begin{definition}[Upper semicontinuity]\label{ha-ch3-def-upper-semicontinuity}\dcref{III.12.7}
\source{hartshorne-algebraic-geometry:III.12.7}
A function is upper semicontinuous when each locus where its value is at most a
fixed integer is open.
\end{definition}
\begin{theorem}[Semicontinuity]\label{ha-ch3-thm-semicontinuity}\dcref{III.12.8}
\source{hartshorne-algebraic-geometry:III.12.8}
For projective $f:X\to Y$ with $Y$ noetherian and coherent $\mathcal F$ flat
over $Y$, $y\mapsto\dim_{k(y)}H^i(X_y,\mathcal F_y)$ is upper semicontinuous.

\end{theorem}
\begin{proof}
Represent $R^if_*\mathcal F$ locally by a finite complex of free
modules.  The preceding rank description shows that the locus where fiber
cohomology has dimension at most $N$ is open.
\end{proof}
\begin{corollary}[Grauert and base change]\label{ha-ch3-cor-grauert}\dcref{III.12.9}
\source{hartshorne-algebraic-geometry:III.12.9}
If a fiber cohomology dimension is constant near $y$, $R^if_*\mathcal F$ is
locally free there and commutes with arbitrary residue-field base change.

\end{corollary}
\begin{proof}

The semicontinuity theorem makes the constant-dimension locus open.  On that neighborhood apply the
local freeness criterion to the finite free complex representing $R^if_*\mathcal F$.

\end{proof}
\begin{proposition}[Cohomology and base change criterion]\label{ha-ch3-prop-cohomology-base-change}\dcref{III.12.10}
\source{hartshorne-algebraic-geometry:III.12.10}
The base-change map $(R^if_*\mathcal F)\otimes k(y)\to H^i(X_y,\mathcal F_y)$
is surjective precisely under the neighboring-map condition; if it is
surjective, it is an isomorphism near $y$ and $R^{i-1}f_*\mathcal F$ is locally
free there.
\uses{ha-ch3-prop-fiber-map}
\end{proposition}
\begin{proof}

Represent the derived direct image locally by a finite free complex.  The natural fiber map is the
edge map in the Tor exact sequence of Proposition~\ref{ha-ch3-prop-fiber-map}; surjectivity is
equivalent to vanishing of the neighboring Tor term.  Nakayama then makes the neighboring differential
constant rank near $y$, so the map is an isomorphism there and the previous cohomology module is free.

\end{proof}
\begin{theorem}[Cohomology and base change]\label{ha-ch3-thm-cohomology-base-change}\dcref{III.12.11}
\source{hartshorne-algebraic-geometry:III.12.11}
Let $f:X\to Y$ be projective, $Y$ noetherian, and $\mathcal F$ coherent and
flat over $Y$.  The natural map
$(R^if_*\mathcal F)\otimes k(y)\to H^i(X_y,\mathcal F_y)$ is an isomorphism
near $y$ whenever the degree-$i$ map is surjective at $y$; in that case the
preceding direct image is locally free near $y$.

\end{theorem}
\begin{proof}
Apply III.12.10 to the finite free complex representing direct
image cohomology and use the rank/minimal-complex criterion of III.12.4.
\end{proof}

\label{chap:hartshorne-curves}



\section{Riemann--Roch Theorem}
\label{ha-ch4-s1}\source{hartshorne-algebraic-geometry:IV.1}
\begin{convention}[Curves and divisors]\label{ha-ch4-conv}
\source{hartshorne-algebraic-geometry:IV.1}
A curve is a complete nonsingular integral curve over an algebraically closed
field \(k\).  For \(D=\sum n_PP\), put
\(\deg D=\sum n_P\), \(\mathcal L(D)=\{f:(f)+D\ge0\}\cup\{0\}\), and
\(l(D)=h^0(X,\mathcal L(D))\).  The complete system \(|D|\) is
\(\mathbf P(H^0(X,\mathcal L(D)))\), of dimension \(l(D)-1\).
\end{convention}

\begin{proposition}[Genus]\label{ha-ch4-p11}\dcref{IV.1.1}
\source{hartshorne-algebraic-geometry:IV.1.1}
\(p_a(X)=p_g(X)=h^1(X,\mathcal O_X)=:g\).
\end{proposition}
\begin{proof}
\(p_a=h^1(\mathcal O_X)\) is III, Ex. 5.3, and Serre duality identifies
\(H^1(\mathcal O_X)^\vee\) with \(H^0(\omega_X)\).
\end{proof}

\begin{lemma}[Degree zero]\label{ha-ch4-l12}\dcref{IV.1.2}
\source{hartshorne-algebraic-geometry:IV.1.2}
If \(l(D)\ne0\), then \(\deg D\ge0\); if also \(\deg D=0\), then \(D\sim0\).
\end{lemma}
\begin{proof}
\(|D|\) contains an effective representative.  An effective divisor of degree
zero is zero.
\end{proof}

\begin{theorem}[Riemann--Roch]\label{ha-ch4-t13}\dcref{IV.1.3}
\source{hartshorne-algebraic-geometry:IV.1.3}
\[
l(D)-l(K-D)=\deg D+1-g.
\]
\end{theorem}
\begin{proof}
Serre duality reduces the assertion to
\(\chi(\mathcal L(D))=\deg D+1-g\).  For \(D=0\) this is
\(h^0(\mathcal O_X)-h^1(\mathcal O_X)=1-g\).  Tensor
\(0\to\mathcal L(-P)\to\mathcal O_X\to k(P)\to0\) by \(\mathcal L(D+P)\);
additivity gives \(\chi(\mathcal L(D+P))=\chi(\mathcal L(D))+1\).
Induction by adding and subtracting points proves the formula.
\end{proof}

\section{Hurwitz's Theorem}
\label{ha-ch4-s2}\source{hartshorne-algebraic-geometry:IV.2}
\begin{definition}[Ramification]\label{ha-ch4-d2}
\source{hartshorne-algebraic-geometry:IV.2}
For finite \(f:X\to Y\), \(e_P=v_P(t)\) for a parameter \(t\) at \(f(P)\).
Ramification means \(e_P>1\), and it is tame if characteristic zero or
\(p\nmid e_P\).  Separability means \(K(X)/K(Y)\) is separable.
\end{definition}

\begin{definition}[Divisors and linear systems]
\label{ha-ch4-def-divisors}
\source{hartshorne-algebraic-geometry:IV.1--IV.3}
For a divisor $D$ on a complete nonsingular curve, write
$\mathcal L(D)=\{f\in K(X):(f)+D\ge0\}\cup\{0\}$ and
$l(D)=\dim_kH^0(X,\mathcal L(D))$.  The complete linear system is
$|D|=\mathbf P H^0(X,\mathcal L(D))$; a linear system is base-point-free if
no point belongs to every member, and very ample if it separates points and
tangent vectors.  A divisor is ample precisely when it has positive degree.
\end{definition}

\begin{proposition}[Differential sequence]\label{ha-ch4-p21}\dcref{IV.2.1}
\source{hartshorne-algebraic-geometry:IV.2.1}
\[
0\to f^*\Omega_Y\to\Omega_X\to\Omega_{X/Y}\to0.
\]
\end{proposition}
\begin{proof}
The standard sequence is exact except possibly on the left.  Its first two
terms are invertible, and the map is nonzero at the generic point because
\(\Omega_{X/Y}=0\) for a separable function-field extension.
\end{proof}

\begin{proposition}[Different]\label{ha-ch4-p22}\dcref{IV.2.2}
\source{hartshorne-algebraic-geometry:IV.2.2}
\(\Omega_{X/Y}\) is torsion supported exactly at ramification points, and
\(\length(\Omega_{X/Y})_P=v_P(dt/du)\).  This equals \(e_P-1\) tamely and is
larger than \(e_P-1\) wildly.
\end{proposition}
\begin{proof}
Write \(t=au^e\).  Then \(dt=aeu^{e-1}du+u^e da\).  The first term has
valuation \(e-1\) when \(e\) is nonzero in \(k\), and in the wild case the
valuation is at least \(e\).
\end{proof}

\begin{proposition}[Canonical divisors]\label{ha-ch4-p23}\dcref{IV.2.3}
\source{hartshorne-algebraic-geometry:IV.2.3}
\[
K_X\sim f^*K_Y+R,\qquad
R=\sum_P\length(\Omega_{X/Y})_P\,P.
\]
\uses{ha-ch4-p21}
\end{proposition}
\begin{proof}
Tensor the sequence of Proposition 2.1 by \(\Omega_X^{-1}\).  The ideal of
the ramification subscheme is \(\mathcal L(-R)\), so
\(f^*\Omega_Y\otimes\Omega_X^{-1}\simeq\mathcal L(-R)\); take divisors.
\end{proof}

\begin{corollary}[Hurwitz]\label{ha-ch4-c24}\dcref{IV.2.4}
\source{hartshorne-algebraic-geometry:IV.2.4}
\[
2g(X)-2=(\deg f)(2g(Y)-2)+\deg R,
\]
and tamely \(\deg R=\sum(e_P-1)\).
\uses{ha-ch4-p23}
\end{corollary}
\begin{proof}
Take degrees in Proposition 2.3, using \(\deg K=2g-2\) and
\(\deg f^*D=(\deg f)\deg D\).
\end{proof}

\begin{proposition}[Purely inseparable maps]\label{ha-ch4-p25}\dcref{IV.2.5}
\source{hartshorne-algebraic-geometry:IV.2.5}
If \(K(X)/K(Y)\) is purely inseparable, \(X,Y\) are abstractly isomorphic,
\(f\) is a composite of relative Frobenius maps, and \(g(X)=g(Y)\).
\end{proposition}
\begin{proof}
For degree \(p^r\), \(K(X)=K(Y)^{1/p^r}\).  The composite relative Frobenius
has this extension, and curves are determined by their function fields.
\end{proof}

\section{Embeddings in Projective Space}
\label{ha-ch4-s3}\source{hartshorne-algebraic-geometry:IV.3}
\begin{proposition}[Linear systems]\label{ha-ch4-p31}\dcref{IV.3.1}
\source{hartshorne-algebraic-geometry:IV.3.1}
\(|D|\) is base-point-free iff \(\dim|D-P|=\dim|D|-1\) for all \(P\); \(D\)
is very ample iff \(\dim|D-P-Q|=\dim|D|-2\) for all \(P,Q\), including
\(P=Q\).
\end{proposition}
\begin{proof}
The exact sequence at \(P\) identifies the surjectivity of
\(|D-P|\to|D|\) with a base point.  The closed-immersion criterion translates
separation of points and tangent vectors into the two stated dimension drops.
\end{proof}

\begin{corollary}[Numerical bounds]\label{ha-ch4-c32}\dcref{IV.3.2}
\source{hartshorne-algebraic-geometry:IV.3.2}
\(\deg D\ge2g\) implies no base points, and \(\deg D\ge2g+1\) implies very
ample.
\uses{ha-ch4-p31}
\end{corollary}
\begin{proof}
Riemann--Roch makes the relevant \(D-P\), respectively \(D-P-Q\), nonspecial,
and Proposition 3.1 applies.
\end{proof}

\begin{corollary}[Ample divisors]\label{ha-ch4-c33}\dcref{IV.3.3}
\source{hartshorne-algebraic-geometry:IV.3.3}
\(D\) is ample iff \(\deg D>0\).
\uses{ha-ch4-c32}
\end{corollary}
\begin{proof}
An ample divisor has a positive-degree very ample multiple.  A positive-degree
divisor has a very ample multiple by Corollary 3.2.
\end{proof}

\begin{proposition}[Projection criterion]\label{ha-ch4-p34}\dcref{IV.3.4}
\source{hartshorne-algebraic-geometry:IV.3.4}
Projection from \(O\notin X\subset\mathbf P^n\) is a closed immersion iff
\(O\) lies on no secant and no tangent line of \(X\).
\end{proposition}
\begin{proof}
The projection system is cut out by hyperplanes through \(O\).  Such
hyperplanes separate points exactly off secants and tangent vectors exactly
off tangent lines.
\end{proof}

\begin{proposition}[Projection dimension]\label{ha-ch4-p35}\dcref{IV.3.5}
\source{hartshorne-algebraic-geometry:IV.3.5}
If \(X\subset\mathbf P^n\) is a curve and \(n\ge4\), some projection embeds it
in \(\mathbf P^{n-1}\).
\uses{ha-ch4-p34}
\end{proposition}
\begin{proof}
The secant and tangent varieties have dimensions at most \(3\) and \(2\), so
their union is proper; apply Proposition 3.4 to a point outside it.
\end{proof}

\begin{corollary}[Embedding in \(\mathbf P^3\)]\label{ha-ch4-c36}\dcref{IV.3.6}
\source{hartshorne-algebraic-geometry:IV.3.6}
Every curve embeds in \(\mathbf P^3\).
\uses{ha-ch4-p35}
\end{corollary}
\begin{proof}
Embed in some projective space by a sufficiently positive divisor and iterate
Proposition 3.5.
\end{proof}

\begin{proposition}[Nodal projection]\label{ha-ch4-p37}\dcref{IV.3.7}
\source{hartshorne-algebraic-geometry:IV.3.7}
Projection from \(O\in\mathbf P^3\) is birational with at most nodes iff \(O\)
lies on finitely many secants, no tangent or multisecant, and no secant with
coplanar tangent lines.
\end{proposition}
\begin{proof}
The first condition gives generic injectivity.  The other conditions make
each double image transverse with distinct tangent directions, hence nodal;
each forbidden incidence gives a worse singularity.
\end{proof}

\begin{proposition}[Tangent degeneracy]\label{ha-ch4-p38}\dcref{IV.3.8}
\source{hartshorne-algebraic-geometry:IV.3.8}
If every secant of a nonplanar curve is a multisecant, or every pair of
tangents is coplanar, then one point lies on every tangent.
\end{proposition}
\begin{proof}
Projection from a point in the first case gives coplanarity at a general
unramified fibre.  In the second, intersect two tangents at \(A\); the plane
they span meets \(X\) finitely, and closedness extends the forced condition
\(A\in L_R\) from the complement to every \(R\).
\end{proof}

\begin{theorem}[Samuel]\label{ha-ch4-t39}\dcref{IV.3.9}
\source{hartshorne-algebraic-geometry:IV.3.9}
The only strange curves in projective space are a line and a characteristic-two
conic.
\end{theorem}
\begin{proof}
After projection and coordinates around the common tangent point, Hurwitz for
the two auxiliary projections gives \(2g-2=-d\) when the point is off \(X\),
and \(2g-2=-d-1\) when it lies on \(X\).  Thus the alternatives are
\((g,d)=(0,2)\) and \((0,1)\); the conic is strange precisely in
characteristic \(2\).
\end{proof}

\begin{theorem}[Plane nodal model]\label{ha-ch4-t310}\dcref{IV.3.10}
\source{hartshorne-algebraic-geometry:IV.3.10}
Every curve in \(\mathbf P^3\) projects birationally to a plane curve with at
most nodes.
\uses{ha-ch4-t39,ha-ch4-p38,ha-ch4-p37}
\end{theorem}
\begin{proof}
Theorem 3.9 and Proposition 3.8 leave an open set of centres avoiding the
tangent, multisecant and coplanar-tangent loci.  The incidence map of secants
has general finite fibres on a nonempty open set, so a centre on only finitely
many secants exists; apply Proposition 3.7.
\end{proof}

\begin{corollary}[Birational nodal model]\label{ha-ch4-c311}\dcref{IV.3.11}
\source{hartshorne-algebraic-geometry:IV.3.11}
Every curve is birationally equivalent to a plane curve with at most nodes.
\uses{ha-ch4-c36,ha-ch4-t310}
\end{corollary}
\begin{proof}
Use Corollary 3.6 followed by Theorem 3.10.
\end{proof}

\section{Elliptic Curves}
\label{ha-ch4-s4}\source{hartshorne-algebraic-geometry:IV.4}
\begin{definition}[Elliptic curve]\label{ha-ch4-d4}
\source{hartshorne-algebraic-geometry:IV.4}
An elliptic curve is a genus-one curve with chosen \(P_0\).  In characteristic
\(\ne2\), normalize the four branch points to \(0,1,\lambda,\infty\), and set
\(j=2^8(\lambda^2-\lambda+1)^3/(\lambda^2(\lambda-1)^2)\).
\end{definition}

\begin{definition}[Elliptic and canonical data]
\label{ha-ch4-def-elliptic-data}
\source{hartshorne-algebraic-geometry:IV.4--IV.5}
An elliptic curve is a genus-one curve with a chosen origin $P_0$.  Its
degree-zero Picard functor is represented by the Jacobian.  For a nonsingular
curve of genus $g\ge2$, the canonical divisor is represented by
$\Omega_X$, and the canonical linear system is $|K|$.
\end{definition}

\begin{theorem}[The \(j\)-invariant]\label{ha-ch4-t41}\dcref{IV.4.1}
\source{hartshorne-algebraic-geometry:IV.4.1}
Over an algebraically closed field of characteristic \(\ne2\), \(j\) is
intrinsic, classifies elliptic curves up to isomorphism, and every element
occurs.
\uses{ha-ch4-l44,ha-ch4-l45,ha-ch4-p46}
\end{theorem}
\begin{proof}
Degree-two maps differ by Lemma 4.4 and their parameters by the six
cross-ratio transforms of Lemma 4.5, under which \(j\) is invariant.
Conversely equal \(j\)'s give parameters in one orbit and hence isomorphic
Legendre cubics by Proposition 4.6.  The defining degree-six equation realizes
every \(j\).
\end{proof}

\begin{lemma}[Involution]\label{ha-ch4-l42}\dcref{IV.4.2}
\source{hartshorne-algebraic-geometry:IV.4.2}
For \(P,Q\in X\), an involution \(\sigma\) satisfies
\(\sigma(P)=Q\) and \(R+\sigma(R)\sim P+Q\).
\end{lemma}
\begin{proof}
\(|P+Q|\) is a base-point-free degree-two system and its deck involution has
exactly the asserted fibres.
\end{proof}
\begin{corollary}[Transitivity]\label{ha-ch4-c43}\dcref{IV.4.3}
\source{hartshorne-algebraic-geometry:IV.4.3}
\(\operatorname{Aut}X\) acts transitively on \(X\).
\uses{ha-ch4-l42}
\end{corollary}
\begin{proof}
For $P,Q\in X$, the involution of Lemma~\ref{ha-ch4-l42} associated with $P+Q$ sends $P$ to
$Q$.  Hence an automorphism carries any prescribed point to any other point.
\end{proof}
\begin{lemma}[Degree-two maps]\label{ha-ch4-l44}\dcref{IV.4.4}
\source{hartshorne-algebraic-geometry:IV.4.4}
Any two degree-two maps \(f_1,f_2:X\to\mathbf P^1\) satisfy
\(f_2\sigma=\tau f_1\) for source and target automorphisms \(\sigma,\tau\).
\uses{ha-ch4-c43}
\end{lemma}
\begin{proof}
Send a ramification point of \(f_1\) to one of \(f_2\) by Corollary 4.3;
both maps then come from the same \(|2P|\).
\end{proof}
\begin{lemma}[Cross-ratio orbit]\label{ha-ch4-l45}\dcref{IV.4.5}
\source{hartshorne-algebraic-geometry:IV.4.5}
The orbit is \(\lambda,\lambda^{-1},1-\lambda,(1-\lambda)^{-1},
\lambda/(\lambda-1),(\lambda-1)/\lambda\).
\end{lemma}
\begin{proof}
Evaluate \((c-a)/(b-a)\) over all orderings of \(0,1,\lambda\).
\end{proof}

\begin{proposition}[Legendre equation]\label{ha-ch4-p46}\dcref{IV.4.6}
\source{hartshorne-algebraic-geometry:IV.4.6}
In characteristic \(\ne2\), \(X\) embeds as
\(y^2=x(x-1)(x-\lambda)\), with \(P_0=(0,1,0)\), and \(\lambda\) is defined
up to the preceding orbit.
\end{proposition}
\begin{proof}
Choose bases \(1,x\in H^0(2P_0)\), \(1,x,y\in H^0(3P_0)\).  The relation in
\(H^0(6P_0)\) is \(y^2+a_1xy+a_3y=x^3+a_2x^2+a_4x+a_6\). Complete the
square and normalize two roots by an affine change of \(x\).
\end{proof}

\begin{corollary}[Automorphism orders]\label{ha-ch4-c47}\dcref{IV.4.7}
\source{hartshorne-algebraic-geometry:IV.4.7}
\(|\operatorname{Aut}(X,P_0)|\) is \(2,4,6,12\) in the four \(j\)/characteristic
cases displayed in the book.
\uses{ha-ch4-l45}
\end{corollary}
\begin{proof}
Count the stabilizer of the branch set in the orbit of Lemma 4.5, with two
lifts for each permutation.
\end{proof}

\begin{proposition}[Group law morphisms]\label{ha-ch4-p48}\dcref{IV.4.8}
\source{hartshorne-algebraic-geometry:IV.4.8}
Negation and addition \(X\times X\to X\) are morphisms.
\uses{ha-ch4-l42}
\end{proposition}
\begin{proof}
Lemma 4.2 gives negation and translations; the third intersection with a line
on the plane cubic is rational in the two points, and translation extends over
the diagonal.
\end{proof}
\begin{lemma}[Homomorphism]\label{ha-ch4-l49}\dcref{IV.4.9}
\source{hartshorne-algebraic-geometry:IV.4.9}
Every morphism of elliptic curves preserving origins is a group homomorphism.
\end{lemma}
\begin{proof}
Pull back the divisor relation \(P+Q\sim R+P_0\).
\end{proof}
\begin{proposition}[Integer endomorphisms]\label{ha-ch4-p410}\dcref{IV.4.10}
\source{hartshorne-algebraic-geometry:IV.4.10}
For characteristic \(\ne2\), \(\mathbf Z\hookrightarrow\operatorname{End}(X,P_0)\),
and every nonzero integer endomorphism is finite.
\end{proposition}
\begin{proof}
Induct using finiteness of \(2_X\), the odd identity
\(2_Xn_X=(2n)_X\), and the even factorization \(2r_X=2_Xr_X\).
\end{proof}

\begin{theorem}[Jacobian]\label{ha-ch4-t411}\dcref{IV.4.11}
\source{hartshorne-algebraic-geometry:IV.4.11}
The elliptic curve with
\(\mathcal L=\mathcal L(\Delta)\otimes p_1^*\mathcal L(-P_0)\) represents its
degree-zero Picard functor and has the divisor-law group structure.
\end{theorem}
\begin{proof}
Twist a degree-zero family by \(P_0\).  Riemann--Roch and base change give a
unique relative effective divisor of degree one, hence a section and a unique
map to \(X\).  Its graph identifies the universal sheaf; untwist.
\end{proof}

\begin{theorem}[Weierstrass functions]\label{ha-ch4-t412b}\dcref{IV.4.12B}
\source{hartshorne-algebraic-geometry:IV.4.12B}
The elliptic-function field is generated by \(\wp,\wp'\), satisfying
\((\wp')^2=4\wp^3-g_2\wp-g_3\).  Proof cited to Hurwitz--Courant.
\end{theorem}
\begin{proof}
The book cites Hurwitz--Courant for this analytic theorem; no proof is
provided in Hartshorne.
\end{proof}
\begin{theorem}[Elliptic divisors]\label{ha-ch4-t413b}\dcref{IV.4.13B}
\source{hartshorne-algebraic-geometry:IV.4.13B}
\(\sum n_i(a_i)\) is a principal divisor on \(\mathbf C/\Lambda\) iff
\(\sum n_i=0\) and \(\sum n_i a_i=0\). Proof cited.
\end{theorem}
\begin{proof}
The book cites the classical theory of elliptic functions for this divisor
criterion; no proof is supplied in Hartshorne.
\end{proof}
\begin{theorem}[Lattice realization]\label{ha-ch4-t414b}\dcref{IV.4.14B}
\source{hartshorne-algebraic-geometry:IV.4.14B}
Every nonzero-discriminant pair \(c_2,c_3\) is realized by a lattice up to
scaling. Proof cited.
\end{theorem}
\begin{proof}
The book cites the analytic theory of elliptic functions for this realization;
no proof is supplied in Hartshorne.
\end{proof}
\begin{theorem}[Modular classification]\label{ha-ch4-t415b}\dcref{IV.4.15B}
\source{hartshorne-algebraic-geometry:IV.4.15B}
\(J(\tau)=J(\tau')\) iff \(\tau'=(a\tau+b)/(c\tau+d)\) with
\(ad-bc=\pm1\), and each value has a unique representative in \(G\). Proof
cited.
\end{theorem}
\begin{proof}
The book cites the standard modular-function theorem for this classification;
no proof is supplied in Hartshorne.
\end{proof}
\begin{theorem}[Complex group]\label{ha-ch4-t416}\dcref{IV.4.16}
\source{hartshorne-algebraic-geometry:IV.4.16}
\(X(\mathbf C)\cong\mathbf R/\mathbf Z\times\mathbf R/\mathbf Z\), with
\(n\)-torsion \((\mathbf Z/n)^2\).
\end{theorem}
\begin{proof}Uniformization gives \(X=\mathbf C/\Lambda\), \(\Lambda\simeq\mathbf Z^2\),
and \(\frac1n\Lambda/\Lambda\simeq(\mathbf Z/n)^2\).\end{proof}
\begin{corollary}[Multiplication]\label{ha-ch4-c417}\dcref{IV.4.17}
\source{hartshorne-algebraic-geometry:IV.4.17}
Multiplication by \(n\) is finite of degree \(n^2\), since its kernel has that
order and it is separable.
\end{corollary}
\begin{proof}
Under $X(\mathbf C)\cong\mathbf C/\Lambda$, multiplication by $n$ has kernel
$n^{-1}\Lambda/\Lambda\cong(\mathbf Z/n)^2$.  It is a nonconstant morphism of complete nonsingular
curves, hence finite, and characteristic zero makes it separable; its degree is the kernel order $n^2$.
\end{proof}
\begin{proposition}[Analytic endomorphisms]\label{ha-ch4-p418}\dcref{IV.4.18}
\source{hartshorne-algebraic-geometry:IV.4.18}
Endomorphisms correspond injectively as a ring to \(\alpha\) with
\(\alpha\Lambda\subseteq\Lambda\).
\end{proposition}
\begin{proof}A holomorphic additive lift is multiplication by \(\alpha\); descent is
equivalent to lattice preservation.\end{proof}
\begin{theorem}[Complex multiplication]\label{ha-ch4-t419}\dcref{IV.4.19}
\source{hartshorne-algebraic-geometry:IV.4.19}
Complex multiplication occurs iff \(\tau\in\mathbf Q(\sqrt{-d})\), and the
endomorphism ring is the order specified by the integral conditions
\(2br,b(r^2+ds^2)\in\mathbf Z\) for \(\tau=r+s\sqrt{-d}\).
\end{theorem}
\begin{proof}Writing \(\alpha=a+b\tau\), \(\alpha\tau=c+e\tau\), elimination gives
quadratic equations for \(\tau\) and integral equations for \(\alpha\);
substitution proves the converse and the displayed order.\end{proof}
\begin{corollary}[CM count]\label{ha-ch4-c420}\dcref{IV.4.20}
\source{hartshorne-algebraic-geometry:IV.4.20}
Only countably many complex \(j\)-values have complex multiplication, since
there are countably many imaginary quadratic orders.
\end{corollary}
\begin{proof}
An endomorphism outside $\mathbf Z$ makes the lattice an order in an imaginary quadratic field, and
there are countably many such fields and orders.  Each order gives one $j$-value by the modular
classification, so the set of CM values is countable.
\end{proof}
\begin{proposition}[Hasse coefficient]\label{ha-ch4-p421}\dcref{IV.4.21}
\source{hartshorne-algebraic-geometry:IV.4.21}
For a cubic \(f=0\), Hasse invariant zero iff the coefficient of
\((xyz)^{p-1}\) in \(f^{p-1}\) is zero.
\end{proposition}
\begin{proof}The cubic exact sequence identifies \(H^1(\mathcal O_X)\) with
\(H^2(\mathcal O_{\mathbf P^2}(-3))\), whose generator is \((xyz)^{-1}\).
Frobenius sends it to \(f^{p-1}(xyz)^{-p}\), so the asserted coefficient is
the Frobenius scalar.\end{proof}
\begin{corollary}[Hasse polynomial]\label{ha-ch4-c422}\dcref{IV.4.22}
\source{hartshorne-algebraic-geometry:IV.4.22}
For \(y^2=x(x-1)(x-\lambda)\), Hasse zero iff
\(\sum_{i=0}^{(p-1)/2}{(p-1)/2\choose i}^2\lambda^i=0\).
\uses{ha-ch4-p421}
\end{corollary}
\begin{proof}Homogenize and extract the coefficient in Proposition 4.21.\end{proof}
\begin{corollary}[Supersingular count]\label{ha-ch4-c423}\dcref{IV.4.23}
\source{hartshorne-algebraic-geometry:IV.4.23}
There are at most \(\lfloor p/12\rfloor+2\) supersingular \(j\)'s.
\end{corollary}
\begin{proof}The Hasse polynomial has degree \((p-1)/2\), and \(\lambda\mapsto j\)
is six-to-one except at two orbits.\end{proof}

\section{The Canonical Embedding}
\label{ha-ch4-s5}\source{hartshorne-algebraic-geometry:IV.5}
\begin{lemma}[Canonical base points]\label{ha-ch4-l51}\dcref{IV.5.1}
\source{hartshorne-algebraic-geometry:IV.5.1}
If \(g\ge2\), \(|K|\) has no base points.
\uses{ha-ch4-p31}
\end{lemma}
\begin{proof}\(\dim|K|=g-1\), \(l(P)=1\), and Riemann--Roch gives
\(\dim|K-P|=g-2\); use Proposition 3.1.\end{proof}
\begin{proposition}[Canonical very ampleness]\label{ha-ch4-p52}\dcref{IV.5.2}
\source{hartshorne-algebraic-geometry:IV.5.2}
\(|K|\) is very ample iff \(X\) is nonhyperelliptic.
\uses{ha-ch4-p31}
\end{proposition}
\begin{proof}Proposition 3.1 and Riemann--Roch reduce this to \(l(P+Q)=1\).
Failure is equivalent to a \(g^1_2\), i.e. hyperellipticity.\end{proof}
\begin{proposition}[Hyperelliptic canonical map]\label{ha-ch4-p53}\dcref{IV.5.3}
\source{hartshorne-algebraic-geometry:IV.5.3}
For a hyperelliptic genus-\(g\) curve, the \(g^1_2\) is unique, the canonical
map has degree two onto a rational normal curve of degree \(g-1\), and
\(|K|\) is the sum of \(g-1\) fibres.
\end{proposition}
\begin{proof}The canonical map collapses the degree-two fibres.  Degree and genus
force its normalization to be \(\mathbf P^1\), image degree \(g-1\), and map
degree two.  A second \(g^1_2\) would give a second factorization.  Hyperplane
sections give the final assertion.\end{proof}
\begin{theorem}[Clifford]\label{ha-ch4-t54}\dcref{IV.5.4}
\source{hartshorne-algebraic-geometry:IV.5.4}
For effective special \(D\), \(\dim|D|\le\frac12\deg D\), with equality only
for \(0,K\), or hyperelliptic multiples of the unique \(g^1_2\).
\uses{ha-ch4-l55}
\end{theorem}
\begin{proof}Apply Lemma 5.5 to \(D,K-D\) and combine with Riemann--Roch.
Equality is analyzed by induction on degree using the common-part exact
sequence; degree two starts the hyperelliptic case, and induction makes \(D\)
a multiple of its \(g^1_2\).\end{proof}

\begin{lemma}[Addition of systems]\label{ha-ch4-l55}\dcref{IV.5.5}
\source{hartshorne-algebraic-geometry:IV.5.5}
\(\dim|D|+\dim|E|\le\dim|D+E|\) for effective \(D,E\).
\end{lemma}
\begin{proof}The addition map is finite-to-one and induced by multiplication of
sections, so its image has the sum of dimensions.\end{proof}

\section{Classification of Curves in \(\mathbf P^3\)}
\label{ha-ch4-s6}\source{hartshorne-algebraic-geometry:IV.6}
\begin{proposition}[Halphen]\label{ha-ch4-p61}\dcref{IV.6.1}
\source{hartshorne-algebraic-geometry:IV.6.1}
For \(g\ge2\), a nonspecial very ample divisor of degree \(d\) exists iff
\(d\ge g+3\).
\end{proposition}
\begin{proof}Riemann--Roch and the embedding dimension exclude \(d\le g+2\);
the boundary case would be a plane curve with contradictory canonical genus.
For \(d\ge g+3\), the bad divisors in \(X^d\) are \(E+P+Q\) with \(E\)
special; Clifford's dimension count makes their locus proper.\end{proof}
\begin{corollary}[Space-curve existence]\label{ha-ch4-c62}\dcref{IV.6.2}
\source{hartshorne-algebraic-geometry:IV.6.2}
Such a curve in \(\mathbf P^3\) exists iff \(g=0,d\ge1\), \(g=1,d\ge3\), or
\(g\ge2,d\ge g+3\).
\uses{ha-ch4-p61}
\end{corollary}
\begin{proof}Combine Sections 3 and Proposition 6.1, then project to \(\mathbf P^3\).
\end{proof}
\begin{proposition}[Special hyperplane section]\label{ha-ch4-p63}\dcref{IV.6.3}
\source{hartshorne-algebraic-geometry:IV.6.3}
For a nonplanar curve with special hyperplane section, \(d\ge6\) and
\(g\ge d/2+1\); for \(d=6\) it is the canonical genus-four curve.
\end{proposition}
\begin{proof}Clifford gives \(\dim|D|\le d/2\), nonplanarity gives
\(\dim|D|\ge3\), and speciality gives \(d\le2g-2\).  Equality at \(d=6\)
leaves only the canonical Clifford equality case, since hyperelliptic multiples
are not very ample.\end{proof}
\begin{theorem}[Castelnuovo]\label{ha-ch4-t64}\dcref{IV.6.4}
\source{hartshorne-algebraic-geometry:IV.6.4}
\[
g\le\begin{cases}\frac14d^2-d+1&d\text{ even},\\
\frac14(d^2-1)-d+1&d\text{ odd}.\end{cases}
\]
Equality is attained for every \(d\ge3\), and equality curves lie on quadrics.
\end{theorem}
\begin{proof}Choose a hyperplane section with no three collinear.  Unions of
planes through successive pairs give
\(\dim|nD|-\dim|(n-1)D|\ge\min(d,2n+1)\).  Summation and
\(\dim|nD|=nd-g\) for large \(n\) give the two parity bounds.  Equality forces
a nonzero quadratic equation.  Curves of type \((s,s)\) and \((s,s+1)\) on a
smooth quadric attain equality.\end{proof}

\label{chap:hartshorne-surfaces}




\section{Geometry on a Surface}
\label{ha-v1}
\source{hartshorne-algebraic-geometry:V.1}

\begin{convention}[Surfaces, curves, and numerical equivalence]
\source{hartshorne-algebraic-geometry:V.1}
Throughout V, a surface is a nonsingular projective surface over an algebraically
closed field, and a curve is an effective divisor unless a different meaning is
specified.  A point is closed, divisors are Cartier divisors, linear equivalence
is denoted by \(\sim\), and \(\operatorname{Num}X\) is the group of divisors
modulo numerical equivalence.
\end{convention}

\begin{definition}[Local intersection, self-intersection, and canonical divisor]
\source{hartshorne-algebraic-geometry:V.1}
For curves $C,D$ with no common component, define the local intersection
multiplicity at $P$ by
\[
(C.D)_P=\length_{\mathcal O_{X,P}}\mathcal O_{X,P}/(f,g),
\]
for local equations $f,g$.  The self-intersection of a nonsingular curve is
$C^2=\deg(\mathcal O_X(C)|_C)$, equivalently the degree of its normal bundle.
The canonical divisor $K_X$ is represented by
$\omega_X=\bigwedge^2\Omega_{X/k}$.
\end{definition}

\begin{theorem}[Intersection pairing]
\label{ha-v1-1}\dcref{V.1.1}\source{hartshorne-algebraic-geometry:V.1.1}
There is a unique pairing
\[
 \operatorname{Div}X\times\operatorname{Div}X\longrightarrow\mathbb Z,
 \qquad (C,D)\longmapsto C.D,
\]
such that: (i) if nonsingular curves meet transversally, \(C.D\) is the number
of their intersection points; (ii) \(C.D=D.C\); (iii) it is additive in each
variable; and (iv) it depends only on the linear-equivalence classes of the two
divisors.
\uses{ha-v1-2,ha-v1-3}
\end{theorem}
\begin{proof}
For a very ample divisor \(A\), Bertini gives a member of \(|A|\) that is
nonsingular and transverse to any prescribed finite collection of curves
(Lemma~\ref{ha-v1-2}).  Write arbitrary divisors as differences
\(C\sim C'-E'\), \(D\sim D'-F'\), with all four terms nonsingular and chosen
transversally.  Set
\[
 C.D=C'.D'-C'.F'-E'.D'+E'.F'.
\]
Replacing one member by another in the same very ample system changes the four
intersection counts by equal amounts, by Lemma~\ref{ha-v1-3}; hence the signed
count is well defined.  It is visibly additive and symmetric, and agrees with
the prescribed transverse count.  Every divisor is a difference of such curves,
so uniqueness follows.
\end{proof}

\begin{lemma}[Bertini choice]
\label{ha-v1-2}\dcref{V.1.2}\source{hartshorne-algebraic-geometry:V.1.2}
If \(C_1,\ldots,C_r\) are irreducible curves and \(A\) is very ample, a general
member of \(|A|\) is irreducible, nonsingular, and transverse to every \(C_i\).

\end{lemma}
\begin{proof}
Embed \(X\) by \(|A|\).  Bertini gives a nonsingular irreducible general
hyperplane section.  For each \(C_i\), the hyperplanes tangent to the embedded
curve or containing a non-transverse tangent direction form a proper closed
subset of the dual projective space.  Avoiding their finite union gives the
assertion.
\end{proof}

\begin{lemma}[Intersection with a smooth curve]
\label{ha-v1-3}\dcref{V.1.3}\source{hartshorne-algebraic-geometry:V.1.3}
If \(C\) is nonsingular and \(D\) is transverse to it, then
\[
 C.D=\deg_C\bigl(\mathcal L(D)\otimes\mathcal O_C\bigr).
\]

\end{lemma}
\begin{proof}
The defining equation of \(D\) restricts to a section of
\(\mathcal L(D)|_C\), whose zero scheme is \(C\cap D\).  Transversality makes
the zero scheme reduced, and the exact sequence
\[
0\to\mathcal L(-D)|_C\to\mathcal O_C\to\mathcal O_{C\cap D}\to0
\]
has Euler characteristic equal to the length of this zero scheme.  On a smooth
curve, that length is the degree of \(\mathcal L(D)|_C\).
\end{proof}

\begin{proposition}[Local intersection formula]
\label{ha-v1-4}\dcref{V.1.4}\source{hartshorne-algebraic-geometry:V.1.4}
If curves \(C,D\) have no common component, then
\[
 C.D=\sum_{P\in C\cap D}(C.D)_P,qquad
 (C.D)_P=\length_{\mathcal O_{X,P}}\mathcal O_{X,P}/(f,g),
\]
where \(f,g\) are local equations at \(P\).
\uses{ha-v1-1}
\end{proposition}
\begin{proof}
Choose a nonsingular curve linearly equivalent to one divisor and transverse
to the other, and use Theorem~\ref{ha-v1-1}.  The displayed exact sequence,
now interpreted on the finite scheme \(C\cap D\), identifies its Euler
characteristic with the sum of the local lengths.  Additivity and linear
equivalence then give the formula for arbitrary \(C,D\).
\end{proof}

\begin{proposition}[Adjunction formula]
\label{ha-v1-5}\dcref{V.1.5}\source{hartshorne-algebraic-geometry:V.1.5}
For a nonsingular curve \(C\) of genus \(g\) on \(X\),
\[
 2g-2=C.(C+K_X).
\]

\end{proposition}
\begin{proof}
The conormal sequence and the determinant of the tangent sequence give
\(\omega_C\simeq(\omega_X\otimes\mathcal O_X(C))|_C\).  Taking degrees and
using \(\deg\omega_C=2g-2\) yields the formula.
\end{proof}

\begin{theorem}[Riemann--Roch for surfaces]
\label{ha-v1-6}\dcref{V.1.6}\source{hartshorne-algebraic-geometry:V.1.6}
Put \(l(D)=h^0(X,\mathcal L(D))\), \(s(D)=h^1(X,\mathcal L(D))\), and
\(p_a=\chi(\mathcal O_X)-1\).  Then
\[
 l(D)-s(D)+l(K_X-D)=\frac12D.(D-K_X)+1+p_a.
\]
\uses{ha-v1-5}
\end{theorem}
\begin{proof}
Serre duality gives \(h^2(\mathcal L(D))=l(K_X-D)\), so it suffices to
compute \(\chi(\mathcal L(D))\).  Write \(D=C-E\), with \(C,E\) effective
and without common components, and use
\(0\to\mathcal L(-E)\to\mathcal O_X\to\mathcal O_E\to0\) and its twist by
\(\mathcal L(C)\).  Additivity of Euler characteristics reduces the calculation
to \(\chi(\mathcal O_C)\) and \(\chi(\mathcal O_E)\).  Curve Riemann--Roch,
adjunction, and Theorem~\ref{ha-v1-5} give
\[
 \chi(\mathcal L(D))=1+p_a+\tfrac12D.(D-K_X),
\]
which is the assertion.
\end{proof}

\begin{lemma}[Vanishing in large positive degree]
\label{ha-v1-7}\dcref{V.1.7}\source{hartshorne-algebraic-geometry:V.1.7}
If \(H\) is ample, there is an integer \(n_0\) such that
\(H^2(X,\mathcal L(D))=0\) whenever \(D.H>n_0\).

\end{lemma}
\begin{proof}
By duality this is equivalent to
\(H^0(X,\mathcal L(K_X-D))=0\).  Choose \(n_0\) larger than the \(H\)-degree
of every component of an effective representative of \(K_X-D\) that can
occur in a fixed bounded family.  If a section existed, \(K_X-D\) would be
effective and would have bounded positive \(H\)-degree, contradicting
\(D.H>n_0\).  The boundedness follows from ampleness and the finite-dimensional
spaces of divisors of bounded degree.
\end{proof}

\begin{corollary}[Effectivity criterion]
\label{ha-v1-8}\dcref{V.1.8}\source{hartshorne-algebraic-geometry:V.1.8}
If \(D.H>0\) and \(D^2>0\), then \(nD\) is linearly equivalent to an effective
divisor for all sufficiently large \(n\).
\uses{ha-v1-6,ha-v1-7}
\end{corollary}
\begin{proof}
Apply Theorem~\ref{ha-v1-6} to \(nD\).  Lemma~\ref{ha-v1-7} makes the second
cohomology term vanish for large \(n\), while the quadratic term
\(\frac12n^2D^2\) dominates the linear term and the fixed constant.  Thus
\(h^0(nD)>0\), so \(|nD|\ne\varnothing\).
\end{proof}

\begin{theorem}[Hodge index theorem]
\label{ha-v1-9}\dcref{V.1.9}\source{hartshorne-algebraic-geometry:V.1.9}
If \(H\) is ample and \(D\not\equiv0\) with \(D.H=0\), then \(D^2<0\).
Equivalently, the intersection form on \(\operatorname{Num}X_\mathbb R\) has
signature \((1,\rho-1)\).
\uses{ha-v1-8}
\end{theorem}
\begin{proof}
For small rational \(\epsilon>0\), apply Corollary~\ref{ha-v1-8} to
\(D+\epsilon H\) and to suitable integral multiples.  If \(D^2>0\), the
resulting effective divisors contradict positivity against the ample class
after subtracting their \(H\)-components.  If \(D^2=0\), perturbation and the
same argument produce a nonzero class orthogonal to \(H\) with negative square,
and equality forces numerical proportionality to \(H\), contrary to
\(D.H=0\).  Hence the orthogonal complement of \(H\) is negative definite.
\end{proof}

\begin{theorem}[Nakai--Moishezon criterion]
\label{ha-v1-10}\dcref{V.1.10}\source{hartshorne-algebraic-geometry:V.1.10}
A divisor \(D\) on a nonsingular projective surface is ample if and only if
\(D^2>0\) and \(D.C>0\) for every irreducible curve \(C\).

\end{theorem}
\begin{proof}
Necessity follows from positivity of an ample restriction and of its top
self-intersection.  Conversely replace \(D\) by a linearly equivalent effective
divisor and use the Hodge index theorem to show that \(D\) has positive degree
on every component of its reduced support.  The restriction of a sufficiently
large multiple to that support is ample; the exact sequence
\(0\to\mathcal O_X(nD-D_{\mathrm{red}})\to\mathcal O_X(nD)\to
\mathcal O_{D_{\mathrm{red}}}(nD)\to0\), together with Serre vanishing, makes
\(|nD|\) separate points and tangent vectors off the support as well.  The
associated morphism has finite fibers, hence is finite by Stein factorization;
its pullback of an ample divisor is a positive multiple of \(D\), so \(D\) is
ample.
\end{proof}

\section{Ruled Surfaces}
\label{ha-v2}\source{hartshorne-algebraic-geometry:V.2}

\begin{definition}[Geometrically ruled surface]
\source{hartshorne-algebraic-geometry:V.2}
A geometrically ruled surface is a surface \(\pi:X\to C\) with a section and
all fibers \(f\simeq\mathbb P^1\).  For a divisor \(D\), write
\(\mathcal L(D)=\mathcal O_X(D)\), and let \(g=g(C)\).
\end{definition}

\begin{notation}[Normalized ruled notation]
\source{hartshorne-algebraic-geometry:V.2}
For a normalized presentation $X=\mathbb P_C(\mathcal E)$, put
$e=-\deg\mathcal E$ and choose the section $C_0$ with
$\mathcal O_X(C_0)\simeq\mathcal O_X(1)$.  Let $f$ be a fiber.  Then every
numerical divisor class is $aC_0+bf$, with $C_0^2=-e$, $C_0.f=1$, and
$f^2=0$.
\end{notation}

\begin{lemma}[Direct images on fibers]
\label{ha-v2-1}\dcref{V.2.1}\source{hartshorne-algebraic-geometry:V.2.1}
If \(D.f=n\ge0\), then \(\pi_*\mathcal L(D)\) is locally free of rank \(n+1\),
\(R^1\pi_*\mathcal L(D)=0\), and \(\pi_*\mathcal O_X=\mathcal O_C\).

\end{lemma}
\begin{proof}
The restriction to each fiber is \(\mathcal O_{\mathbb P^1}(n)\), whose
\(H^0\) has dimension \(n+1\) and whose \(H^1\) vanishes.  Grauert's theorem
then gives local freeness and base change; applying the same argument to
\(\mathcal O_X\) gives the last assertion.
\end{proof}

\begin{proposition}[Projective-bundle description]
\label{ha-v2-2}\dcref{V.2.2}\source{hartshorne-algebraic-geometry:V.2.2}
Every ruled surface is \(\mathbb P_C(\mathcal E)\) for a locally free sheaf
\(\mathcal E\) of rank two.  Conversely \(\mathbb P_C(\mathcal E)\) is ruled,
and \(\mathbb P(\mathcal E)\simeq\mathbb P(\mathcal E')\) over \(C\) exactly
when \(\mathcal E'\simeq\mathcal E\otimes\mathcal L\) for an invertible sheaf
\(\mathcal L\).

\end{proposition}
\begin{proof}
A section gives a quotient \(\mathcal E\twoheadrightarrow\mathcal L\) on
each trivializing open set.  The resulting morphism to \(\mathbb P(\mathcal E)\)
is an isomorphism on every fiber and hence an isomorphism globally.  Conversely
local triviality of \(\mathcal E\) gives fibers \(\mathbb P^1\) and sections.
The relative \(\mathcal O(1)\) is determined up to tensoring by a line bundle,
which proves the isomorphism criterion.
\end{proof}

\begin{proposition}[Picard and numerical groups]
\label{ha-v2-3}\dcref{V.2.3}\source{hartshorne-algebraic-geometry:V.2.3}
For \(X=\mathbb P_C(\mathcal E)\),
\(\operatorname{Pic}X\simeq\mathbb Z[\mathcal O_X(1)]\oplus\pi^*\operatorname{Pic}C\).
After choosing a section \(C_0\), \(\operatorname{Num}X\simeq\mathbb Z C_0\oplus\mathbb Z f\),
with \(C_0.f=1\) and \(f^2=0\).

\end{proposition}
\begin{proof}
Subtracting a suitable multiple of a fiber makes a divisor have degree zero
on every fiber; its restriction is then pulled back from \(C\).  This gives
surjectivity, while restriction to a fiber proves uniqueness.  Numerical
equivalence on pullbacks is degree on \(C\), yielding the stated basis and
intersection numbers.
\end{proof}

\begin{lemma}[Cohomology of nonnegative fiber degree]
\label{ha-v2-4}\dcref{V.2.4}\source{hartshorne-algebraic-geometry:V.2.4}
If \(D.f\ge0\), then \(R^i\pi_*\mathcal L(D)=0\) for \(i>0\), and
\[
 H^i(X,\mathcal L(D))\simeq H^i(C,\pi_*\mathcal L(D)).
\]

\end{lemma}
\begin{proof}
The fiber restriction has no higher cohomology, so Grauert gives the vanishing
of higher direct images.  The Leray spectral sequence therefore degenerates.
\end{proof}

\begin{corollary}[Invariants of a ruled surface]
\label{ha-v2-5}\dcref{V.2.5}\source{hartshorne-algebraic-geometry:V.2.5}
For a ruled surface over a curve of genus \(g\),
\[
 p_a(X)=-g,\qquad p_g(X)=0,\qquad q(X)=g.
\]
\uses{ha-v2-4}
\end{corollary}
\begin{proof}
Use Lemma~\ref{ha-v2-4} with \(D=0\) and \(\pi_*\mathcal O_X=\mathcal O_C\),
then the cohomology of \(\mathcal O_C\) gives \(h^0=1,h^1=g,h^2=0\).
\end{proof}

\begin{proposition}[Sections and quotient bundles]
\label{ha-v2-6}\dcref{V.2.6}\source{hartshorne-algebraic-geometry:V.2.6}
A section \(D\subset\mathbb P_C(\mathcal E)\) is equivalent to a surjection
\(\mathcal E\twoheadrightarrow\mathcal L\) onto an invertible sheaf.  If
\(0\to\mathcal N\to\mathcal E\to\mathcal L\to0\), then
\[
 \mathcal N\simeq\pi_*(\mathcal O_X(1)\otimes\mathcal O_X(-D)),qquad
 \pi_*\mathcal N\simeq\mathcal O_X(1)\otimes\mathcal O_X(-D)
\]
under the natural identification on the base.
\uses{ha-v2-4}
\end{proposition}
\begin{proof}
The quotient defines the section by the universal property of \(\mathbb P(\mathcal E)\).
The exact sequence
\(0\to\mathcal O_X(1)\otimes\mathcal L^{-1}\to\mathcal O_X(1)\to
\mathcal O_X(1)|_D\to0\), pushed down using Lemma~\ref{ha-v2-4}, identifies
the kernel and its pushforward as displayed.
\end{proof}

\begin{corollary}[Extensions on curves]
\label{ha-v2-7}\dcref{V.2.7}\source{hartshorne-algebraic-geometry:V.2.7}
Every locally free sheaf of rank two on a smooth curve is an extension of two
invertible sheaves.

\end{corollary}
\begin{proof}
Choose a line bundle quotient of the generic fiber and extend it after twisting
by a sufficiently positive line bundle.  The kernel is torsion-free of rank one,
hence invertible on a nonsingular curve, and gives the extension.
\end{proof}

\begin{proposition}[Normalization and the invariant]
\label{ha-v2-8}\dcref{V.2.8}\source{hartshorne-algebraic-geometry:V.2.8}
Every ruled surface has a normalized presentation \(X=\mathbb P(\mathcal E)\),
where \(H^0(\mathcal E)\ne0\) but \(H^0(\mathcal E\otimes\mathcal L)=0\) for every
line bundle \(\mathcal L\) of negative degree.  The integer
\(e=-\deg\mathcal E\) is presentation-independent, and there is a section
\(C_0\) with \(\mathcal O_X(C_0)\simeq\mathcal O_X(1)\).

\end{proposition}
\begin{proof}
Twist \(\mathcal E\) by a line bundle of minimal degree for which it has a
nonzero section.  Minimality gives the vanishing for negative twists.  A nonzero
section yields a quotient after removing its zero divisor and hence the section
\(C_0\).  A further twist changes \(\deg\mathcal E\) by twice the degree of
the twist and changes the chosen section correspondingly, so \(e\) is intrinsic.
\end{proof}

\begin{proposition}[Classes of sections]
\label{ha-v2-9}\dcref{V.2.9}\source{hartshorne-algebraic-geometry:V.2.9}
If a section \(D\) corresponds to \(\mathcal E\twoheadrightarrow\mathcal L\), then
\[
 \deg\mathcal L=C_0.D,\qquad D\sim C_0+(\deg\mathcal L-e)f,
 \qquad C_0^2=-e.
\]
\uses{ha-v2-6}
\end{proposition}
\begin{proof}
The first equality is restriction to the section.  Apply Proposition~\ref{ha-v2-6}
to the kernel and compare degrees in the resulting exact sequence; the divisor
class differs from \(C_0\) by the indicated pullback.  Intersecting with \(C_0\)
then gives \(C_0^2=-e\).
\end{proof}

\begin{lemma}[Canonical divisor of a ruled surface]
\label{ha-v2-10}\dcref{V.2.10}\source{hartshorne-algebraic-geometry:V.2.10}
For the normalized notation, with \(K_C\) also denoting a divisor pulled back
from \(C\),
\[
 K_X\sim -2C_0+(K_C+ef).
\]

\end{lemma}
\begin{proof}
Write \(K_X\sim aC_0+bf\).  Adjunction on a fiber gives
\(-2=K_X\mathbin{.}f=-2\), so \(a=-2\).  Adjunction on \(C_0\), whose genus
is \(g(C)\), gives \(2g-2=C_0\mathbin{.}(C_0+K_X)=-e+b\), hence
\(b=2g-2+e\), which is the displayed
linear equivalence.
\end{proof}

\begin{corollary}[Canonical self-intersection]
\label{ha-v2-11}\dcref{V.2.11}\source{hartshorne-algebraic-geometry:V.2.11}
\[
 K_X\equiv-2C_0+(2g-2-e)f,qquad K_X^2=8(1-g).
\]
\uses{ha-v2-10}
\end{corollary}
\begin{proof}
Use Lemma~\ref{ha-v2-10}, \(C_0^2=-e\), \(C_0.f=1\), and \(f^2=0\), then
expand the square.
\end{proof}

\begin{theorem}[Normalized bundles]
\label{ha-v2-12}\dcref{V.2.12}\source{hartshorne-algebraic-geometry:V.2.12}
For a normalized rank-two bundle on a genus-\(g\) curve, if it is decomposable
then \(\mathcal E\simeq\mathcal O_C\oplus\mathcal L\) with \(\deg\mathcal L\le0\),
so \(e\ge0\), and every \(e\ge0\) occurs.  If it is indecomposable, then
\[
 -2g\le e\le2g-2.
\]
\uses{ha-v2-7}
\end{theorem}
\begin{proof}
Normalization orders the two summands and gives the decomposable assertion.
For an indecomposable bundle use Proposition~\ref{ha-v2-7} in a maximal line
subbundle extension \(0\to\mathcal O_C\to\mathcal E\to\mathcal L\to0\).
The extension class is nonzero in \(H^1(\mathcal L^{-1})\), so Serre duality
and Riemann--Roch force both \(h^0(K_C\otimes\mathcal L)\) and
\(h^0(\mathcal L^{-1})\) to be nonzero only within the stated degree range.
\end{proof}

\begin{corollary}[Rational ruled surfaces]
\label{ha-v2-13}\dcref{V.2.13}\source{hartshorne-algebraic-geometry:V.2.13}
Over \(C=\mathbb P^1\), every ruled surface is isomorphic to exactly one
\(X_e=\mathbb P(\mathcal O\oplus\mathcal O(-e))\), with \(e\ge0\).
\uses{ha-v2-8}
\end{corollary}
\begin{proof}
Every bundle splits on \(\mathbb P^1\), and tensoring makes the larger summand
degree zero.  Proposition~\ref{ha-v2-8} makes the difference nonnegative and
unique.
\end{proof}

\begin{corollary}[Splitting on the projective line]
\label{ha-v2-14}\dcref{V.2.14}\source{hartshorne-algebraic-geometry:V.2.14}
Every locally free rank-two sheaf on \(\mathbb P^1\) is a direct sum of line
bundles.
\uses{ha-v2-7}
\end{corollary}
\begin{proof}
Apply the extension statement of Corollary~\ref{ha-v2-7}; the classification
of line bundles and the vanishing of the relevant \(H^1\) after ordering the
degrees show that the extension splits.
\end{proof}

\begin{theorem}[Indecomposable elliptic ruled surfaces]
\label{ha-v2-15}\dcref{V.2.15}\source{hartshorne-algebraic-geometry:V.2.15}
For an elliptic curve, an indecomposable normalized rank-two bundle has
\(e=0\) or \(e=-1\), and there is exactly one ruled-surface isomorphism class
for each value.

\end{theorem}
\begin{proof}
The extension \(0\to\mathcal O_C\to\mathcal E\to\mathcal L\to0\) and
\(h^1(\mathcal O_C)=1\) show that the nontrivial degree-zero extension is unique.
For degree one, tensoring by a degree-zero line bundle identifies all nontrivial
extensions with the unique normalized one.  If \(e\le-2\), the cohomology
diagram induced by multiplication by a nonzero section of a degree-one line
bundle makes an injective map from a two-dimensional space into a one-dimensional
space, a contradiction.  Twisting gives the asserted isomorphism classes.
\end{proof}

\begin{corollary}[Atiyah's elliptic classification]
\label{ha-v2-16}\dcref{V.2.16}\source{hartshorne-algebraic-geometry:V.2.16}
Indecomposable rank-two bundles of each fixed degree on an elliptic curve are
parametrized by the points of the curve (after the natural determinant/twist
identifications).
\uses{ha-v2-15}
\end{corollary}
\begin{proof}
Twist by a line bundle to reduce the degree to zero or one.  Theorem~\ref{ha-v2-15}
classifies the normalized extensions, and degree-zero line bundles are
parametrized by \(\operatorname{Pic}^0(C)\simeq C\).  Untwisting restores the
classification in every degree.
\end{proof}

\begin{theorem}[Linear systems on \(X_e\)]
\label{ha-v2-17}\dcref{V.2.17}\source{hartshorne-algebraic-geometry:V.2.17}
Let \(X_e=\mathbb P(\mathcal O\oplus\mathcal O(-e))\).  A section
\(D\sim C_0+nf\) exists exactly when \(n=0\) or \(n\ge e\); for \(n=e\) there
is a disjoint section \(C_1\sim C_0+ef\) with \(C_1^2=e\).  Moreover
\(|C_0+nf|\) is base-point-free iff \(n\ge e\), and very ample iff \(n>e\).
\uses{ha-v2-6}
\end{theorem}
\begin{proof}
By Proposition~\ref{ha-v2-6}, a section in this class is a quotient
\(\mathcal O\oplus\mathcal O(-e)\twoheadrightarrow\mathcal O(n-e)\).
Nonzero components exist precisely for \(n=0\) or \(n\ge e\), and for \(n=e\)
the second component gives the disjoint section.  Intersecting with \(C_0\)
shows base-point-freeness exactly for \(n\ge e\).  When \(n>e\), the two
summands separate points and tangent vectors on a fiber, on the minimal section,
and between fibers; the vanishing of
\(H^1(\mathcal O(n-1))\) and \(H^1(\mathcal O(n-e-1))\) supplies the required
lifting.  For \(n=e\), the disjoint section is contracted, so very ampleness fails.
\end{proof}

\begin{corollary}[Ample and very ample classes on \(X_e\)]
\label{ha-v2-18}\dcref{V.2.18}\source{hartshorne-algebraic-geometry:V.2.18}
For \(D=aC_0+bf\) on \(X_e\), \(D\) is ample iff it is very ample iff
\(a>0\) and \(b>ae\).  A general member of such a system is irreducible and
nonsingular.
\uses{ha-v2-17}
\end{corollary}
\begin{proof}
Write \(D=a(C_0+nf)+r f\) and apply Theorem~\ref{ha-v2-17}; the inequalities
are exactly those for a sufficiently positive multiple of the generating
systems.  Necessity follows by intersecting with \(f\) and \(C_0\).  Bertini
gives the final assertion.
\end{proof}

\begin{corollary}[Rational scrolls]
\label{ha-v2-19}\dcref{V.2.19}\source{hartshorne-algebraic-geometry:V.2.19}
For \(n\ge e\), \(|C_0+nf|\) embeds \(X_e\) as a rational scroll of degree
\(2n-e\) in \(\mathbb P^{2n-e+1}\).
\uses{ha-v2-17,ha-v2-1}
\end{corollary}
\begin{proof}
Theorem~\ref{ha-v2-17} gives the embedding.  Intersection theory gives
\((C_0+nf)^2=2n-e\).  Lemma~\ref{ha-v2-1} and cohomology on \(\mathbb P^1\) give
\(h^0(C_0+nf)=2n-e+2\), hence the stated projective dimension and degree.
\end{proof}

\begin{proposition}[Curves and ampleness for \(e\ge0\)]
\label{ha-v2-20}\dcref{V.2.20}\source{hartshorne-algebraic-geometry:V.2.20}
If \(e\ge0\) and an irreducible curve \(Y\) is neither \(C_0\) nor a fiber,
then \(Y\sim aC_0+bf\) with \(a>0\) and \(b\ge ae\).  A divisor
\(D=aC_0+bf\) is ample iff \(a>0\) and \(b>ae\).

\end{proposition}
\begin{proof}
Intersect with \(f\) to get \(a>0\), and with \(C_0\) to get
\(b-ae\ge0\).  Nakai--Moishezon applied to \(f,C_0\), and these inequalities
for every other irreducible curve, gives the criterion.
\end{proof}

\begin{proposition}[Curves and ampleness for \(e<0\)]
\label{ha-v2-21}\dcref{V.2.21}\source{hartshorne-algebraic-geometry:V.2.21}
Assume \(e<0\) and either characteristic zero or \(g\le1\).  If
\(Y\sim aC_0+bf\) is irreducible and is neither a section nor a fiber, then
\(a>0\) and \(b\ge ae/2\).  A divisor \(D=aC_0+bf\) is ample iff
\(a>0\) and \(b>ae/2\).
\uses{ha-v2-9}
\end{proposition}
\begin{proof}
Normalize \(Y\).  Hurwitz gives \(g(\widetilde Y)\ge g(C)\), while adjunction and
\(C_0^2=-e\) give
\((a-1)(b-ae/2)\ge0\).  The case \(a=1\) is handled by the section
description of Proposition~\ref{ha-v2-9}.  These inequalities, together with
the intersections with a fiber and with the minimal section, imply the stated
positivity; Nakai--Moishezon proves sufficiency and necessity.
\end{proof}

\section{Monoidal Transformations}
\label{ha-v3}\source{hartshorne-algebraic-geometry:V.3}

\begin{construction}[Monoidal transformation and multiplicity]
\source{hartshorne-algebraic-geometry:V.3}
The monoidal transformation at $P\in X$ is the blow-up
$\pi:\widetilde X\to X$.  Its inverse image $E=\pi^{-1}(P)$ is the
exceptional curve.  If $C$ has local equation $f$ at $P$, its multiplicity
$\mu_P(C)$ is the largest integer $r$ such that
$f\in\mathfrak m_P^r$.
\end{construction}

\begin{proposition}[The blow-up of a point]
\label{ha-v3-1}\dcref{V.3.1}\source{hartshorne-algebraic-geometry:V.3.1}
If \(\pi:\widetilde X\to X\) is the blow-up of a nonsingular point \(P\) on a
nonsingular projective surface, then \(\widetilde X\) is nonsingular and
projective, the exceptional curve \(E=\pi^{-1}(P)\) is \(\mathbb P^1\), and
\(E^2=-1\).

\end{proposition}
\begin{proof}
In regular parameters \((x,y)\), the blow-up is covered by
\(\operatorname{Spec}k[x,y/x]\) and \(\operatorname{Spec}k[x/y,y]\), so it is
nonsingular and projective.  The exceptional divisor is \(\operatorname{Proj}
\operatorname{gr}_{(x,y)}\mathcal O_{X,P}\simeq\mathbb P^1\).  Its normal bundle
is \(\mathcal O_{\mathbb P^1}(-1)\), hence its self-intersection is \(-1\).
\end{proof}

\begin{proposition}[Picard group and intersections after blowing up]
\label{ha-v3-2}\dcref{V.3.2}\source{hartshorne-algebraic-geometry:V.3.2}
\[
 \operatorname{Pic}\widetilde X\simeq\pi^*\operatorname{Pic}X\oplus\mathbb Z[E],
 \quad (\pi^*C).(\pi^*D)=C.D,\quad \pi^*C.E=0,\quad E^2=-1,
\]
and \(C.\pi_*D=(\pi^*C).D\).

\end{proposition}
\begin{proof}
The isomorphism away from \(P\) gives the restriction sequence; the kernel is
generated by \(E\), and \(E^2=-1\) proves independence.  Represent divisors on
\(X\) by transverse curves avoiding \(P\), whose strict transforms compute the
first three intersection identities.  The last follows by the projection
formula.
\end{proof}

\begin{proposition}[Canonical divisor under a blow-up]
\label{ha-v3-3}\dcref{V.3.3}\source{hartshorne-algebraic-geometry:V.3.3}
\[
 K_{\widetilde X}=\pi^*K_X+E,\qquad K_{\widetilde X}^2=K_X^2-1.
\]
\uses{ha-v3-2}
\end{proposition}
\begin{proof}
Write \(K_{\widetilde X}=\pi^*K_X+aE\).  Adjunction on
\(E\simeq\mathbb P^1\) gives \(-2=(K_{\widetilde X}+E).E=-a-1\), so \(a=1\).
The square follows from Proposition~\ref{ha-v3-2}.
\end{proof}

\begin{proposition}[Cohomology under a blow-up]
\label{ha-v3-4}\dcref{V.3.4}\source{hartshorne-algebraic-geometry:V.3.4}
\[
 \pi_*\mathcal O_{\widetilde X}=\mathcal O_X,qquad
 R^i\pi_*\mathcal O_{\widetilde X}=0\ (i>0),
\]
so \(H^i(X,\mathcal O_X)\simeq H^i(\widetilde X,\mathcal O_{\widetilde X})\).

\end{proposition}
\begin{proof}
The first equality holds because the blow-up is an isomorphism off a codimension
two point and both schemes are normal.  For the higher direct images, formal
functions reduces to the thickenings \(E_n\) of \(E\).  Their successive
quotients are \(\mathcal O_E(n)\), whose \(H^1\) vanishes for the relevant
nonnegative twists; induction gives \(H^i(E_n,\mathcal O_{E_n})=0\) for
\(i>0\), and formal functions gives the assertion.
\end{proof}

\begin{corollary}[Arithmetic genus]
\label{ha-v3-5}\dcref{V.3.5}\source{hartshorne-algebraic-geometry:V.3.5}
\(p_a(X)=p_a(\widetilde X)\); in particular \(q\) and \(p_g\) are unchanged.
\uses{ha-v3-4}
\end{corollary}
\begin{proof}
Take Euler characteristics in Proposition~\ref{ha-v3-4}.
\end{proof}

\begin{proposition}[Total and strict transforms]
\label{ha-v3-6}\dcref{V.3.6}\source{hartshorne-algebraic-geometry:V.3.6}
If an effective curve \(C\) has multiplicity \(r\) at \(P\), then
\[
 \pi^*C=\widetilde C+rE.
\]

\end{proposition}
\begin{proof}
In the two blow-up charts, divide the local equation of \(C\) by the highest
common power of the exceptional coordinate.  The remaining equation is the
strict transform, and its factor is the initial homogeneous form of degree
\(r\), proving the divisor identity.
\end{proof}

\begin{corollary}[Genus drop on blowing up]
\label{ha-v3-7}\dcref{V.3.7}\source{hartshorne-algebraic-geometry:V.3.7}
With the notation of Proposition~\ref{ha-v3-6},
\[
 \widetilde C.E=r,qquad p_a(\widetilde C)=p_a(C)-\frac12r(r-1).
\]
\uses{ha-v3-6,ha-v3-2}
\end{corollary}
\begin{proof}
The first equality follows from Proposition~\ref{ha-v3-2}.  Substitute
\(\widetilde C=\pi^*C-rE\) and \(K_{\widetilde X}=\pi^*K_X+E\) in adjunction;
the cross terms give exactly \(r(r-1)/2\).
\end{proof}

\begin{proposition}[Resolution of an irreducible curve]
\label{ha-v3-8}\dcref{V.3.8}\source{hartshorne-algebraic-geometry:V.3.8}
Repeatedly blowing up singular points of an irreducible curve produces, after
finitely many steps, a nonsingular strict transform.
\uses{ha-v3-7}
\end{proposition}
\begin{proof}
At each singular point the multiplicity is at least two, so Corollary~\ref{ha-v3-7}
strictly decreases the nonnegative integer arithmetic genus.  The process must
therefore terminate, and termination means that no singular point remains.
\end{proof}

\begin{theorem}[Embedded resolution of curves]
\label{ha-v3-9}\dcref{V.3.9}\source{hartshorne-algebraic-geometry:V.3.9}
For every curve \(Y\subset X\), a finite sequence of monoidal transformations
makes the total inverse image a divisor with normal crossings: every component
is nonsingular, intersections are transverse, and no two components meet in more
than one local branch.
\uses{ha-v3-8}
\end{theorem}
\begin{proof}
Resolve each irreducible component using Proposition~\ref{ha-v3-8}.  If a
remaining singularity has multiplicity \(r\ge3\), blowing it up changes the
arithmetic genus of the total transform by
\(-\frac12(r-1)(r-2)\), so only finitely many such steps occur.  A double point
with distinct tangent directions is already a node; otherwise its blow-up
produces either a separated transverse pair or another configuration of higher
contact, and the next blow-up lowers the same genus measure.  Thus the process
terminates with normal crossings.
\end{proof}

\begin{definition}[Infinitely near points and strict transform]
\source{hartshorne-algebraic-geometry:V.3}
Points on successive blow-ups are called infinitely near points.  A point $Q'$
is near $P$ when it lies on the strict transform of a curve through $P$.
For an effective curve of multiplicity $r$ at $P$, the strict transform is
defined by $\widetilde C=\pi^*C-rE$.
\end{definition}

\section{The Cubic Surface in \(\mathbb P^3\)}
\label{ha-v4}\source{hartshorne-algebraic-geometry:V.4}

\begin{definition}[Assigned base points]
\source{hartshorne-algebraic-geometry:V.4}
An assigned base point of multiplicity $m$ imposes the corresponding vanishing
conditions on a plane linear system.  Points may be infinitely near, in which
case the condition includes the prescribed tangent direction.  Blowing up all
assigned points replaces $|D|$ by
$|\pi^*D-\sum m_iE_i|$; base points remaining after this operation are called
unassigned base points.
\end{definition}

\begin{proposition}[Conics through assigned points]
\label{ha-v4-1}\dcref{V.4.1}\source{hartshorne-algebraic-geometry:V.4.1}
Conics through at most four assigned points in \(\mathbb P^2\), with no three
collinear, have no unassigned base points, including an assigned point infinitely
near another.

\end{proposition}
\begin{proof}
It suffices to consider four points.  The reducible conics
\(L_{12}+L_{34}\) and \(L_{13}+L_{24}\) lie in the system and their common
intersection is exactly the assigned scheme.  In the infinitely near case choose
the corresponding line with the prescribed tangent direction; the same
intersection calculation proves there is no further base point.
\end{proof}

\begin{corollary}[Dimension of conic systems]
\label{ha-v4-2}\dcref{V.4.2}\source{hartshorne-algebraic-geometry:V.4.2}
Under the hypotheses of Proposition~\ref{ha-v4-1}, the system of conics has
dimension \(5-r\) for \(r\le4\); for five points there is a unique irreducible
conic.
\uses{ha-v4-1}
\end{corollary}
\begin{proof}
Each assigned point imposes one independent linear condition on the six-dimensional
space of conics, by Proposition~\ref{ha-v4-1}.  For five points the remaining
one-dimensional vector space cannot contain a reducible conic without forcing
three assigned points onto one line.
\end{proof}

\begin{proposition}[Cubics through assigned points]
\label{ha-v4-3}\dcref{V.4.3}\source{hartshorne-algebraic-geometry:V.4.3}
Cubics through at most seven assigned points, with no four collinear and no seven
on a conic, have no unassigned base points, including infinitely near points.

\end{proposition}
\begin{proof}
For seven ordinary points and a point \(Q\) outside them, choose a line through
two assigned points and a conic through the other five avoiding \(Q\), unless
the incidence forces a line through three points or a conic through all seven;
the hypotheses exclude precisely these exceptions.  Varying the choice gives a
cubic through the assigned points but not \(Q\).  If an assigned point is
infinitely near, impose the tangent condition in the same line--conic
construction; the resulting cubic can be chosen with the required first jet.
\end{proof}

\begin{corollary}[Dimensions of cubic systems]
\label{ha-v4-4}\dcref{V.4.4}\source{hartshorne-algebraic-geometry:V.4.4}
The system of cubics through \(r\le7\) points in the hypotheses of
Proposition~\ref{ha-v4-3} has dimension \(9-r\).  For \(r=8\), it has dimension
one and its general member is irreducible.
\uses{ha-v4-3}
\end{corollary}
\begin{proof}
There are ten cubic monomials, and Proposition~\ref{ha-v4-3} gives independent
conditions.  For eight points the residual pencil has no fixed component,
otherwise a line or conic would contain too many assigned points; Bertini then
gives irreducibility of the general member.
\end{proof}

\begin{corollary}[The ninth base point]
\label{ha-v4-5}\dcref{V.4.5}\source{hartshorne-algebraic-geometry:V.4.5}
Eight points in general position determine a ninth point, possibly infinitely
near, common to every cubic through the eight.

\end{corollary}
\begin{proof}
Two general cubics through the eight have intersection number nine.  They have
no common component and already meet at the eight assigned points, counted with
their assigned tangent conditions, so Bezout leaves one residual point.  Varying
the two cubics shows the residual point is fixed.
\end{proof}

\begin{theorem}[Very ampleness of cubics on the blow-up]
\label{ha-v4-6}\dcref{V.4.6}\source{hartshorne-algebraic-geometry:V.4.6}
If assigned points satisfy no three collinear and no six on a conic, the cubics
through them induce a very ample linear system on their blow-up.
\uses{ha-v4-3}
\end{theorem}
\begin{proof}
After subtracting an exceptional point, the systems needed to separate any two
points or a tangent vector are cubic systems with at most seven assigned points.
Proposition~\ref{ha-v4-3} supplies a member avoiding any prescribed residual
point, and the same argument with a first-order infinitely near point separates
tangent vectors.  Thus the system separates points and tangent vectors.
\end{proof}

\begin{corollary}[Del Pezzo embeddings]
\label{ha-v4-7}\dcref{V.4.7}\source{hartshorne-algebraic-geometry:V.4.7}
Blowing up \(r=0,\ldots,6\) general points of \(\mathbb P^2\) embeds the result
in \(\mathbb P^{9-r}\) with degree \(9-r\), and
\(\omega_{X'}\simeq\mathcal O_{X'}(-1)\).  For \(r=6\), the image is a
nonsingular cubic surface in \(\mathbb P^3\).
\uses{ha-v4-6,ha-v3-2}
\end{corollary}
\begin{proof}
The system is \(3l-\sum E_i=-K_{X'}\).  Theorem~\ref{ha-v4-6} gives the
embedding, while Proposition~\ref{ha-v3-2} computes its square and the
dimension of its sections as \(9-r\).  The canonical blow-up formula gives
\(K_{X'}=-h\), hence the asserted canonical sheaf and degree.
\end{proof}

\begin{proposition}[Picard calculations on a cubic surface]
\label{ha-v4-8}\dcref{V.4.8}\source{hartshorne-algebraic-geometry:V.4.8}
For \(X=\operatorname{Bl}_{P_1,\ldots,P_6}\mathbb P^2\), let \(l\) be the pullback
of a line and \(e_i\) the exceptional classes.  Then
\[
 l^2=1,\ l.e_i=0,\ e_i.e_j=-\delta_{ij},\quad
 h=3l-\sum e_i,\quad K_X=-h,
\]
and for \(D\sim al-\sum b_ie_i\),
\[
 \deg_hD=3a-\sum b_i,\quad D^2=a^2-\sum b_i^2,quad
 p_a(D)=1+\tfrac12(D^2-\deg_hD).
\]
\uses{ha-v3-2,ha-v3-3}
\end{proposition}
\begin{proof}
The intersection table and canonical formula are Propositions~\ref{ha-v3-2}
and~\ref{ha-v3-3}.  The degree is \(D.h\), the square follows by expansion,
and adjunction gives the arithmetic-genus formula.
\end{proof}

\begin{theorem}[The twenty-seven lines]
\label{ha-v4-9}\dcref{V.4.9}\source{hartshorne-algebraic-geometry:V.4.9}
The cubic surface contains exactly 27 lines, namely
\[
 e_i\ (1\le i\le6),\qquad l-e_i-e_j\ (i<j),\qquad
 2l-\sum_{j\ne i}e_j\ (1\le i\le6).
\]
They are all the curves of self-intersection \(-1\).

\end{theorem}
\begin{proof}
A line has \(D.h=1\) and, by adjunction, \(D^2=-1\).  Writing
\(D=al-\sum b_ie_i\), these equations are
\(3a-\sum b_i=1\) and \(a^2-\sum b_i^2=-1\).  Schwarz's inequality gives
\(3a^2-6a-5\le0\), hence \(a=0,1,2\).  Solving the integer equations gives
exactly the six exceptional classes, the fifteen pair-line classes, and the
six conic classes listed above.  Each is effective and represented by the
corresponding plane curve, so the list is complete.
\end{proof}

\begin{proposition}[Six skew lines]
\label{ha-v4-10}\dcref{V.4.10}\source{hartshorne-algebraic-geometry:V.4.10}
Any six mutually disjoint lines on a cubic surface are the exceptional curves
of a morphism \(X\to\mathbb P^2\); thus they define a second blow-up presentation.

\end{proposition}
\begin{proof}
For a chosen six-tuple, use the quadratic transformation of \(\mathbb P^2\) to
replace a selected configuration \((e_i,l-e_i-e_j,2l-\sum_{j\ne i}e_j)\) by
exceptional classes.  The intersection table shows that the remaining six
classes are again disjoint and their images are six points with no three
collinear and no six on a conic.  Induction over the possible incidences gives
the required blow-down map.
\end{proof}

\begin{theorem}[Ampleness on a cubic surface]
\label{ha-v4-11}\dcref{V.4.11}\source{hartshorne-algebraic-geometry:V.4.11}
For a divisor \(D\) on a nonsingular cubic surface, the following are equivalent:
\(D\) is very ample; \(D\) is ample; \(D^2>0\) and \(D.L>0\) for every line
\(L\); and \(D.L>0\) for every line \(L\).
\uses{ha-v4-10,ha-v4-12}
\end{theorem}
\begin{proof}
The implications from very ample to ample and to positivity are immediate;
the converse positivity implies \(D^2>0\) by the intersection description and
Nakai--Moishezon.  Choose six skew lines minimizing their intersections with
\(D\), use Proposition~\ref{ha-v4-10} to relabel them as exceptional classes,
and write \(D=al-\sum b_ie_i\) with ordered positive \(b_i\).  The line
inequalities give \(a\ge b_1+b_2+b_5\).  Lemma~\ref{ha-v4-12} then makes \(D\)
very ample.
\end{proof}

\begin{lemma}[A sufficient very-ampleness decomposition]
\label{ha-v4-12}\dcref{V.4.12}\source{hartshorne-algebraic-geometry:V.4.12}
If \(D\sim al-\sum b_ie_i\), \(b_1\ge\cdots\ge b_6>0\), and
\(a\ge b_1+b_2+b_5\), then \(D\) is very ample.
\uses{ha-v4-6}
\end{lemma}
\begin{proof}
Subtract successively nonnegative multiples of
\[
 l,\quad l-e_1,\quad 2l-e_1-e_2,\quad\ldots,\quad3l-e_1-\cdots-e_6.
\]
The hypotheses ensure nonnegative coefficients.  The first systems are
base-point-free and the last is the anticanonical very ample system from
Theorem~\ref{ha-v4-6}; tensor products and sums of these systems separate
points and tangent vectors, so their nonnegative combination is very ample.
\end{proof}

\begin{corollary}[Numerical criterion on a cubic surface]
\label{ha-v4-13}\dcref{V.4.13}\source{hartshorne-algebraic-geometry:V.4.13}
For \(D\sim al-\sum b_ie_i\), ampleness and very ampleness are equivalent to
\[
 b_i>0,\qquad a>b_i+b_j\ (i\ne j),\qquad
 2a>\sum_{i\ne j}b_i\quad\text{for every }i.
\]
Every such class contains an irreducible nonsingular member.
\uses{ha-v4-11}
\end{corollary}
\begin{proof}
Intersect with the 27 line classes to obtain exactly the displayed inequalities;
Theorem~\ref{ha-v4-11} gives equivalence with ampleness.  A general member is
irreducible and nonsingular by Bertini, since the class is very ample.
\end{proof}

\section{Birational Transformations}
\label{ha-v5}\source{hartshorne-algebraic-geometry:V.5}

\begin{definition}[Birational-map data]
\source{hartshorne-algebraic-geometry:V.5}
For a birational map \(T:X\dashrightarrow Y\), its maximal domain is the
largest open set on which it is a morphism; points outside it are fundamental
points.  Its graph $\Gamma$ is the closure of the graph over this domain.  The
total transform of a subvariety is obtained from the image under the graph
projection, with strict transform away from exceptional components.
\end{definition}

\begin{lemma}[Fundamental points]
\label{ha-v5-1}\dcref{V.5.1}\source{hartshorne-algebraic-geometry:V.5.1}
For a birational map from a normal projective variety, the fundamental locus is
closed and has codimension at least two.

\end{lemma}
\begin{proof}
At a codimension-one point the local ring is a DVR.  The induced inclusion of
function fields defines a valuation on the target field, and the valuative
criterion extends the rational map across that point.  Thus indeterminacy cannot
contain a divisor; closedness follows from the graph projection.
\end{proof}

\begin{theorem}[Zariski's main theorem for a fundamental point]
\label{ha-v5-2}\dcref{V.5.2}\source{hartshorne-algebraic-geometry:V.5.2}
For a birational map of normal projective surfaces, the total transform of each
fundamental point is connected and has dimension at least one.

\end{theorem}
\begin{proof}
Let \(\Gamma\) be the graph and project it to the source.  The fiber over the
fundamental point is connected by the connected-fibers theorem for a proper
birational morphism.  If it were zero-dimensional, the induced projective
birational morphism to a normal affine neighborhood would be finite; a finite
birational morphism to a normal scheme is an isomorphism, contradicting that the
point is fundamental.  Hence the fiber has dimension at least one.
\end{proof}

\begin{proposition}[Factorization through a point blow-up]
\label{ha-v5-3}\dcref{V.5.3}\source{hartshorne-algebraic-geometry:V.5.3}
If \(f:X'\to X\) is a birational morphism of nonsingular projective surfaces,
and \(P\) is a fundamental point of \(f^{-1}\), then \(f\) factors through the
blow-up \(\pi:\widetilde X\to X\) at \(P\): there is \(f':X'\to\widetilde X\)
with \(f=\pi f'\).
\uses{ha-v5-2}
\end{proposition}
\begin{proof}
Set \(T=\pi^{-1}f\).  By Theorem~\ref{ha-v5-2}, the fiber of \(f\) over \(P\)
contains a curve.  In regular local coordinates at a point of that curve, the
pullbacks of the two parameters generate an ideal whose common vanishing is the
fiber; comparing their orders shows that the ideal \(I_P\mathcal O_{X'}\) is
invertible.  The universal property of the blow-up therefore extends \(T\) to
a morphism \(f'\), proving the factorization.
\end{proof}

\begin{corollary}[Birational morphisms]
\label{ha-v5-4}\dcref{V.5.4}\source{hartshorne-algebraic-geometry:V.5.4}
If \(n(f)\) is the number of irreducible curves contracted by a birational
morphism \(f:X'\to X\) of nonsingular projective surfaces, then \(f\) is a
composition of exactly \(n(f)\) monoidal transformations.
\uses{ha-v5-3}
\end{corollary}
\begin{proof}
Choose a contracted curve over a fundamental point of the inverse and apply
Proposition~\ref{ha-v5-3}; the factorization removes one contracted component.
Induction on \(n(f)\) terminates, and each blow-up adds exactly one exceptional
curve.
\end{proof}

\begin{theorem}[Factorization of birational transformations]
\label{ha-v5-5}\dcref{V.5.5}\source{hartshorne-algebraic-geometry:V.5.5}
Every birational transformation between nonsingular projective surfaces is a
composition of monoidal transformations and their inverses.
\uses{ha-v3-7,ha-v5-4}
\end{theorem}
\begin{proof}
Choose a very ample divisor \(H'\) on the target and a nonsingular
\(C'\in|2H'|\) avoiding the fundamental points.  Pull it back to the source;
the difference \(m=p_a(C)-p_a(C')\) is nonnegative.  Blow up singular and
infinitely near points of the pullback curve.  Corollary~\ref{ha-v3-7} strictly
decreases \(m\), so after finitely many steps the rational map becomes a
morphism.  Apply Corollary~\ref{ha-v5-4} to that morphism and to the analogous
map for the inverse.
\end{proof}

\begin{corollary}[Birational invariance of surface arithmetic genus]
\label{ha-v5-6}\dcref{V.5.6}\source{hartshorne-algebraic-geometry:V.5.6}
The arithmetic genus of a nonsingular projective surface is a birational
invariant.
\uses{ha-v5-5,ha-v3-5}
\end{corollary}
\begin{proof}
Theorem~\ref{ha-v5-5} reduces a birational map to blow-ups and blow-downs, and
Corollary~\ref{ha-v3-5} preserves arithmetic genus at each step.
\end{proof}

\begin{theorem}[Castelnuovo contraction]
\label{ha-v5-7}\dcref{V.5.7}\source{hartshorne-algebraic-geometry:V.5.7}
If \(Y\simeq\mathbb P^1\) on a nonsingular projective surface and \(Y^2=-1\),
there is a morphism contracting \(Y\) to a nonsingular point, and this morphism
is inverse to the blow-up of that point.

\end{theorem}
\begin{proof}
Choose very ample \(H\) with \(H^1(H)=0\), put \(k=H.Y\), and use
\(0\to\mathcal O(H+(i-1)Y)\to\mathcal O(H+iY)\to\mathcal O_Y(H+iY)\to0\)
to prove inductively \(H^1(H+iY)=0\) for \(0\le i\le k\).  Consequently
\(\mathcal O(H+kY)\) is globally generated.  Its morphism is an isomorphism
off \(Y\) and contracts \(Y\).  Normalize the image.  Formal functions and
the thickenings of \(Y\) identify the completed local ring at the image with
\(\varprojlim k[x,y]/(x,y)^{n+1}=k[[x,y]]\), so the point is nonsingular.
Factorization identifies the morphism with the blow-down; the same completed
ring calculation shows the normalization map is already an isomorphism.
\end{proof}

\begin{theorem}[Relatively minimal models]
\label{ha-v5-8}\dcref{V.5.8}\source{hartshorne-algebraic-geometry:V.5.8}
Every nonsingular projective surface admits a birational morphism to a relatively
minimal surface, i.e. one with no exceptional curve of the first kind.
\uses{ha-v5-7}
\end{theorem}
\begin{proof}
Repeatedly contract every \((-1)\)-curve by Theorem~\ref{ha-v5-7}.  The
cohomology classes of contracted curves are linearly independent in
\(H^1(X,\Omega_X)\), since their intersection matrix is negative diagonal after
successive pullback.  Their number is therefore bounded by the finite dimension
of this space, so the process terminates at a relatively minimal surface.
\end{proof}

\section{Classification of Surfaces}
\label{ha-v6}\source{hartshorne-algebraic-geometry:V.6}

\begin{definition}[Canonical ring and Kodaira dimension]
\source{hartshorne-algebraic-geometry:V.6}
For a nonsingular projective surface define the canonical ring
\(R(X,K)=\bigoplus_{n\ge0}H^0(X,\mathcal O_X(nK_X))\).  Its Kodaira dimension
\(\kappa(X)\) is \(-1\) when all positive pluricanonical systems are empty;
otherwise it is the dimension of the image of \(|nK_X|\) for sufficiently
divisible \(n\), and lies in \(\{0,1,2\}\).
\end{definition}

\begin{theorem}[The case \(\kappa=-1\)]
\label{ha-v6-1}\dcref{V.6.1}\source{hartshorne-algebraic-geometry:V.6.1}
\[
 \kappa(X)=-1\quad\Longleftrightarrow\quad |12K_X|=\varnothing
 \quad\Longleftrightarrow\quad X\text{ is rational or ruled}.
\]

\end{theorem}
\begin{proof}
The source states this classification theorem but does not supply its proof in
the chapter body.
\end{proof}

\begin{theorem}[Castelnuovo rationality criterion]
\label{ha-v6-2}\dcref{V.6.2}\source{hartshorne-algebraic-geometry:V.6.2}
For a nonsingular projective surface, \(X\) is rational if and only if
\(p_a(X)=0\) and \(P_2=0\), where
\(P_2=h^0(X,\mathcal O_X(2K_X))\).

\end{theorem}
\begin{proof}
The source cites Castelnuovo's criterion and does not supply its proof here.
\end{proof}

\begin{theorem}[The case \(\kappa=0\)]
\label{ha-v6-3}\dcref{V.6.3}\source{hartshorne-algebraic-geometry:V.6.3}
If \(\operatorname{char}k\ne2,3\), then
\(\kappa(X)=0\) iff \(|12K_X|\) consists of one divisor (equivalently
\(P_{12}=1\)).  The minimal surfaces with \(\kappa=0\) are K3 surfaces,
Enriques surfaces, abelian surfaces, and hyperelliptic (bielliptic) surfaces,
distinguished by their canonical torsion and invariants \(p_g,q\).

\end{theorem}
\begin{proof}
The source states the classification and does not supply its proof in this
chapter body.
\end{proof}

\begin{theorem}[The case \(\kappa=1\)]
\label{ha-v6-4}\dcref{V.6.4}\source{hartshorne-algebraic-geometry:V.6.4}
\(\kappa(X)=1\) if and only if \(X\) is an elliptic surface: after a birational
modification it admits a fibration to a curve whose general fiber is a smooth
curve of genus one.

\end{theorem}
\begin{proof}
The source states this characterization and does not supply its proof here.
\end{proof}

\begin{theorem}[The case \(\kappa=2\)]
\label{ha-v6-5}\dcref{V.6.5}\source{hartshorne-algebraic-geometry:V.6.5}
\(\kappa(X)=2\) if and only if some pluricanonical system \(|nK_X|\) defines a
birational map onto its image.  Such surfaces are precisely the surfaces of
general type.

\end{theorem}
\begin{proof}
