\section{Intersection Theory}
\label{ha-appA-sec1}
\source{hartshorne-algebraic-geometry:A.1}

\begin{definition}[Cycles, rational equivalence, and Chow groups]
\source{hartshorne-algebraic-geometry:A.1}
For a variety $X$ over an algebraically closed field, a codimension-$r$ cycle
is a finite integral combination of closed irreducible codimension-$r$
subvarieties.  A closed subscheme of pure codimension $r$ determines the
cycle whose coefficient at a component is the length at its generic point.
For $f:X\to X'$, proper pushforward sends a subvariety $Y$ to zero if its
dimension drops and otherwise to $[K(Y):K(f(Y))]f(Y)$, extended linearly.
If $\widetilde V\to V$ is the normalization, linearly equivalent Weil
divisors on $\widetilde V$ define rationally equivalent cycles on $X$.
Write $A^r(X)$ for codimension-$r$ cycles modulo this relation and
$A(X)=\bigoplus_rA^r(X)$.
\end{definition}

An intersection theory on nonsingular quasi-projective varieties has products
$A^r(X)\times A^s(X)\to A^{r+s}(X)$ and pullbacks defined by the graph, subject
to the following axioms.

\begin{convention}[Chow-ring structure]
\label{ha-appA-A1}
\source{hartshorne-algebraic-geometry:A1}
\dcref{A1}
$A(X)$ is a commutative associative graded ring with identity.
\end{convention}

\begin{convention}[Functorial pullback]
\label{ha-appA-A2}
\source{hartshorne-algebraic-geometry:A2}
\dcref{A2}
Pullback is a ring map and $(gf)^*=f^*g^*$.
\end{convention}

\begin{convention}[Functorial proper pushforward]
\label{ha-appA-A3}
\source{hartshorne-algebraic-geometry:A3}
\dcref{A3}
Proper pushforward is graded and $(gf)_*=g_*f_*$.
\end{convention}

\begin{convention}[Projection formula]
\label{ha-appA-A4}
\source{hartshorne-algebraic-geometry:A4}
\dcref{A4}
$f_*(x f^*y)=f_*(x)y$.
\end{convention}

\begin{convention}[Diagonal formula]
\label{ha-appA-A5}
\source{hartshorne-algebraic-geometry:A5}
\dcref{A5}
For the diagonal $\Delta:X\to X\times X$, $YZ=\Delta^*(Y\times Z)$.
\end{convention}

\begin{convention}[Proper-intersection multiplicities]
\label{ha-appA-A6}
\source{hartshorne-algebraic-geometry:A6}
\dcref{A6}
If $Y,Z$ meet properly, $YZ=\sum_W i(Y,Z;W)W$, with $i(Y,Z;W)$ local at the
generic point of $W$.
\end{convention}

\begin{convention}[Cartier-divisor normalization]
\label{ha-appA-A7}
\source{hartshorne-algebraic-geometry:A7}
\dcref{A7}
If $Z$ is an effective Cartier divisor meeting $Y$ properly, $YZ$ is the cycle
of the Cartier divisor cut on $Y$.
\end{convention}

\begin{theorem}[Intersection theory]
\label{ha-appA-thm1-1}
\dcref{A.1.1}
On nonsingular quasi-projective varieties there is a unique intersection
theory satisfying A1--A7.  For proper intersection, the local multiplicity is
\[
i(Y,Z;W)=\sum_{j\ge0}(-1)^j\length_A\operatorname{Tor}^A_j(A/\mathfrak a,A/\mathfrak b),
\]
where $A=\mathcal O_{X,\eta_W}$ and $\mathfrak a,\mathfrak b$ are the ideals
of $Y,Z$.  Chow's moving lemma says that $Z$ is rationally equivalent to a
cycle meeting $Y$ properly, and two such choices give the same product.
\source{hartshorne-algebraic-geometry:A.1.1}
\uses{ha-appA-A1,ha-appA-A2,ha-appA-A3,ha-appA-A4,ha-appA-A5,ha-appA-A6,ha-appA-A7}
\end{theorem}

\begin{proof}
Serre's Tor formula has the required local, normalization, and positivity
properties.  By the moving lemma replace one cycle by a rationally equivalent
cycle meeting the other properly.  For uniqueness use A5 to reduce to the
diagonal in $X\times X'$, which is a local complete intersection; A6 reduces
to one factor a complete intersection of Cartier divisors, and repeated A7
then determines the product.  This also proves independence of the moved
representative.
\end{proof}



\section{Properties of the Chow Ring}
\label{ha-appA-sec2}
\source{hartshorne-algebraic-geometry:A.2}

\begin{convention}[Divisors and the Picard group]
\label{ha-appA-A8}
\source{hartshorne-algebraic-geometry:A8}
\dcref{A8}
$A^1(X)\simeq\operatorname{Pic}X$.
\end{convention}

\begin{convention}[Affine-space invariance]
\label{ha-appA-A9}
\source{hartshorne-algebraic-geometry:A9}
\dcref{A9}
Projection $X\times\mathbb A^n\to X$ induces
$A(X)\simeq A(X\times\mathbb A^n)$.
\end{convention}

\begin{convention}[Localization]
\label{ha-appA-A10}
\source{hartshorne-algebraic-geometry:A10}
\dcref{A10}
For a nonsingular closed $Y\subset X$, with $U=X-Y$, the sequence
$A(Y)\to A(X)\to A(U)\to0$ is exact.
\end{convention}

\begin{convention}[Projective-bundle formula]
\label{ha-appA-A11}
\source{hartshorne-algebraic-geometry:A11}
\dcref{A11}
If $\mathcal E$ has rank $r$, then $A(\mathbb P(\mathcal E))$ is a free
$A(X)$-module on $1,\xi,\ldots,\xi^{r-1}$, where $\xi$ is the tautological
divisor class.
\end{convention}

\section{Chern Classes}
\label{ha-appA-sec3}
\source{hartshorne-algebraic-geometry:A.3}

\begin{definition}[Chern classes]
\source{hartshorne-algebraic-geometry:A.3}
For a rank-$r$ locally free sheaf $\mathcal E$ on $X$, define
$c_i(\mathcal E)\in A^i(X)$ by $c_0=1$ and
\[
\sum_{i=0}^r(-1)^i\xi^{r-i}\pi^*c_i(\mathcal E)=0
\quad\text{in }A(\mathbb P(\mathcal E)),
\]
where $\pi$ is the projection.  The total class is
$c(\mathcal E)=\sum_i c_i(\mathcal E)$.
\end{definition}

\begin{convention}[First Chern class of a line bundle]
\label{ha-appA-C1}
\source{hartshorne-algebraic-geometry:C1}
\dcref{C1}
$c(\mathcal O_X(D))=1+D$.
\end{convention}

\begin{convention}[Pullback of Chern classes]
\label{ha-appA-C2}
\source{hartshorne-algebraic-geometry:C2}
\dcref{C2}
$c_i(f^*\mathcal E)=f^*c_i(\mathcal E)$.
\end{convention}

\begin{convention}[Whitney sum formula]
\label{ha-appA-C3}
\source{hartshorne-algebraic-geometry:C3}
\dcref{C3}
For $0\to\mathcal E'\to\mathcal E\to\mathcal E''\to0$,
$c(\mathcal E)=c(\mathcal E')c(\mathcal E'')$.
\end{convention}

\begin{convention}[Splitting principle]
\label{ha-appA-C4}
\source{hartshorne-algebraic-geometry:C4}
\dcref{C4}
If $\mathcal E$ has a filtration with invertible quotients $\mathcal L_i$,
then $c(\mathcal E)=\prod_i(1+c_1(\mathcal L_i))$.
\end{convention}

\begin{convention}[Chern-root identities]
\label{ha-appA-C5}
\source{hartshorne-algebraic-geometry:C5}
\dcref{C5}
Under formal Chern roots $a_i,b_j$,
$c(\mathcal E\otimes\mathcal F)=\prod_{i,j}(1+(a_i+b_j)t)$,
$c(\bigwedge^p\mathcal E)=\prod_{|I|=p}(1+(\sum_{i\in I}a_i)t)$, and
$c(\mathcal E^\vee)=\prod_i(1-a_it)$.
\end{convention}

\begin{convention}[Zero scheme of a section]
\label{ha-appA-C6}
\source{hartshorne-algebraic-geometry:C6}
\dcref{C6}
If a section of $\mathcal E$ has zero scheme $Y$ of codimension $r$, then
$c_r(\mathcal E)=[Y]$.
\end{convention}

\begin{convention}[Self-intersection formula]
\label{ha-appA-C7}
\source{hartshorne-algebraic-geometry:C7}
\dcref{C7}
If $i:Y\hookrightarrow X$ is nonsingular of codimension $r$, then
$i_*c_r(N_{Y/X})=Y\cdot Y$.
\end{convention}

\section{The Riemann--Roch Theorem}
\label{ha-appA-sec4}
\source{hartshorne-algebraic-geometry:A.4}

\begin{definition}[Chern character and Todd class]
\source{hartshorne-algebraic-geometry:A.4}
For formal roots $a_i$ of $\mathcal E$, set
$\operatorname{ch}(\mathcal E)=\sum_i e^{a_i}$ and
$\operatorname{td}(\mathcal E)=\prod_i a_i/(1-e^{-a_i})$.  Thus
\[
\operatorname{ch}=r+c_1+\tfrac12(c_1^2-2c_2)+\tfrac16(c_1^3-3c_1c_2+3c_3)+\cdots.
\]
\end{definition}

\begin{theorem}[Hirzebruch--Riemann--Roch]
\label{ha-appA-thm4-1}
\dcref{A.4.1}
If $\mathcal E$ is locally free on a nonsingular projective $n$-fold $X$,
\[
\chi(\mathcal E)=\deg\bigl(\operatorname{ch}(\mathcal E)\operatorname{td}(T_X)\bigr)_n.
\]
\source{hartshorne-algebraic-geometry:A.4.1}
\end{theorem}
\begin{proof}
The source attributes this theorem to Hirzebruch over $\mathbb C$ and to
Grothendieck in generalized form; it does not give a proof here.
\end{proof}

\section{Complements and Generalizations}
\label{ha-appA-sec5}
\source{hartshorne-algebraic-geometry:A.5}

\begin{theorem}[Nakai--Moishezon criterion]
\label{ha-appA-thm5-1}
\dcref{A.5.1}
For a Cartier divisor $D$ on a scheme $X$ proper over an algebraically closed
field, $D$ is ample iff
$D^{\dim Y}\cdot Y>0$ for every positive-dimensional integral closed
subvariety $Y\subset X$.
\source{hartshorne-algebraic-geometry:A.5.1}
\end{theorem}
\begin{proof}
The source attributes this criterion to Nakai and says that its proof is
clarified and simplified by Kleiman; no proof is supplied in this appendix.
\end{proof}

\begin{theorem}[Hodge index theorem]
\label{ha-appA-thm5-2}
\dcref{A.5.2}
If $X$ is a nonsingular projective surface, $H$ is ample, and $D$ is a
numerically nonzero divisor, then
\[
(D\cdot H)^2\geq (H^2)(D^2),
\]
with equality if and only if $D$ is numerically proportional to $H$.
\source{hartshorne-algebraic-geometry:A.5.2}
\end{theorem}
\begin{proof}
The source attributes this theorem to Hodge and says that the proof uses
Hodge's theory of harmonic integrals; no proof is supplied here.
\end{proof}

\begin{definition}[K-theory pushforward]
\source{hartshorne-algebraic-geometry:A.5}
The Chern classes extend additively to $K(X)$, the Chern character is a ring
map $K(X)\to A(X)\otimes\mathbb Q$, and a proper morphism has
$f_![\mathcal F]=\sum_i(-1)^i[R^if_*\mathcal F]$.
\end{definition}

\begin{theorem}[Grothendieck--Riemann--Roch]
\label{ha-appA-thm5-3}
\dcref{A.5.3}
For a smooth projective morphism $f:X\to Y$ of nonsingular quasi-projective
varieties and $x\in K(X)$,
\[
\operatorname{ch}(f_!x)\operatorname{td}(T_Y)
=f_*\bigl(\operatorname{ch}(x)\operatorname{td}(T_X)\bigr).
\]
\source{hartshorne-algebraic-geometry:A.5.3}
\end{theorem}
\begin{proof}
The source attributes this theorem to Grothendieck and refers to its proof in
the cited literature; no proof is supplied here.
\end{proof}

\label{app:hartshorne-transcendental}



\section{The Associated Complex Analytic Space}
\label{ha-appB-sec1}
\source{hartshorne-algebraic-geometry:B.1}

\begin{construction}[Analytification]
\source{hartshorne-algebraic-geometry:B.1}
If $X$ is of finite type over $\CC$, cover it by $Y_i=\operatorname{Spec}A_i$
with $A_i=\CC[x_1,\ldots,x_n]/(f_1,\ldots,f_q)$.  Regard the $f_j$ as
holomorphic functions, form the analytic zero spaces $(Y_i)_h\subset\CC^n$,
and glue them using the algebraic transition maps.  The resulting analytic
space is $X_h$, functorially in $X$.  A coherent sheaf analytifies by applying
the same construction to local finite cokernel presentations.  The
construction preserves separatedness/Hausdorffness, connectedness,
reducedness, smoothness/being a complex manifold, and properness.  There are
natural maps
\[
H^i(X,\mathcal F)\longrightarrow H^i(X_h,\mathcal F_h).
\]
\end{construction}

\section{Comparison of the Algebraic and Analytic Categories}
\label{ha-appB-sec2}
\source{hartshorne-algebraic-geometry:B.2}

\begin{theorem}[GAGA]
\label{ha-appB-thm2-1}
\dcref{B.2.1}
If $X$ is projective over $\CC$, analytification gives an equivalence between
coherent algebraic sheaves on $X$ and coherent analytic sheaves on $X_h$;
for every coherent $\mathcal F$ the comparison maps
\[
\alpha_i:H^i(X,\mathcal F)\xrightarrow{\sim}H^i(X_h,\mathcal F_h)
\]
are isomorphisms.
\source{hartshorne-algebraic-geometry:B.2.1}

\end{theorem}
\begin{proof}
Embed $X$ in $\mathbf P^N$.  Analytification of a finite presentation gives a coherent analytic
sheaf, and Serre's finiteness theorems A and B identify its Cech cohomology with the algebraic Cech
complex on the standard affine cover.  The resulting comparison maps are isomorphisms and are
compatible with tensor products and morphisms, yielding the equivalence.
\end{proof}

\begin{theorem}[Chow]
\label{ha-appB-thm2-2}
\dcref{B.2.2}
Every compact analytic subspace of $\mathbb P^n_h$ is the analytification of
a unique closed algebraic subscheme of $\mathbb P^n$.
\source{hartshorne-algebraic-geometry:B.2.2}

\end{theorem}
\begin{proof}
This is stated as a corollary of Serre's theorem in the source; no separate
proof is supplied.
\end{proof}

\section{When Is a Compact Complex Manifold Algebraic?}
\label{ha-appB-sec3}
\source{hartshorne-algebraic-geometry:B.3}

\begin{theorem}[Riemann]
\label{ha-appB-thm3-1}
\dcref{B.3.1}
Every compact complex manifold of dimension one is projective algebraic.
\source{hartshorne-algebraic-geometry:B.3.1}
\end{theorem}

\begin{proof}
The source explains that the first step uses hard analysis (Weyl's or
Gunning's argument) to produce a nonconstant meromorphic function; the second,
elementary Riemann-existence step gives a finite map to $\mathbb P^1$ and
algebraicity.  No full proof is supplied.
\end{proof}


\begin{theorem}[Generalized Riemann existence]
\label{ha-appB-thm3-2}
\dcref{B.3.2}
If $X$ is a normal scheme of finite type over $\CC$, and $X'$ is a normal
complex analytic space with a finite morphism $f:X'\to X_h$, then there is a
unique normal scheme $X'$ and finite morphism $g:X'\to X$ such that
$X'_h\simeq X'$ and $g_h=f$.  Consequently
\[
\pi_1^{\mathrm{alg}}(X)\simeq\widehat{\pi_1(X_h)}.
\]
\source{hartshorne-algebraic-geometry:B.3.2}
\end{theorem}
\begin{proof}
The source attributes this generalized theorem to Grauert--Remmert and
Grothendieck (SGA 1) and does not supply a proof.
\end{proof}

\begin{proposition}[Siegel]
\label{ha-appB-prop3-3}
\dcref{B.3.3}
For a compact complex manifold $X$ of dimension $n$, the meromorphic function
field has transcendence degree at most $n$ over $\CC$; if equality holds, it is
a finitely generated extension of $\CC$.  If $X=X_h$ is algebraic, then this
field is the algebraic rational function field.
\source{hartshorne-algebraic-geometry:B.3.3}

\end{proposition}
\begin{proof}
The source cites Siegel for this proposition and does not give its proof.
\end{proof}

\begin{theorem}[Chow--Kodaira]
\label{ha-appB-thm3-4}
\dcref{B.3.4}
Every compact complex manifold of dimension two with two algebraically
independent meromorphic functions is projective algebraic.
\source{hartshorne-algebraic-geometry:B.3.4}

\end{theorem}
\begin{proof}
The source states this theorem without proof and cites Chow and Kodaira.
\end{proof}

\section{Kähler Manifolds}
\label{ha-appB-sec4}
\source{hartshorne-algebraic-geometry:B.4}

\begin{definition}[Kähler, Hodge, and Moishezon manifolds]
\source{hartshorne-algebraic-geometry:B.4}
A Hermitian metric is Kähler when its associated $(1,1)$-form is closed.  A
compact Kähler manifold is a Hodge manifold if its Kähler class lies in
$H^2(X,\mathbb Z)$.  A compact complex manifold is Moishezon if its
meromorphic function field has transcendence degree equal to its dimension.
\end{definition}

\begin{theorem}[Kodaira]
\label{ha-appB-thm4-1}
\dcref{B.4.1}
Every Hodge manifold is projective algebraic.
\source{hartshorne-algebraic-geometry:B.4.1}

\end{theorem}
\begin{proof}
The source cites Kodaira for this theorem and does not give its proof.
\end{proof}

\begin{theorem}[Moishezon]
\label{ha-appB-thm4-2}
\dcref{B.4.2}
Every Moishezon manifold which is Kähler is projective algebraic.
\source{hartshorne-algebraic-geometry:B.4.2}

\end{theorem}
\begin{proof}
The source cites Moishezon for this theorem and does not give its proof.
\end{proof}

\section{The Exponential Sequence}
\label{ha-appB-sec5}
\source{hartshorne-algebraic-geometry:B.5}

\begin{construction}[Exponential sequence]
\source{hartshorne-algebraic-geometry:B.5}
The exponential sequence of sheaves on a complex manifold is
\[
0\longrightarrow\mathbb Z\longrightarrow\mathcal O_X
\xrightarrow{\exp(2\pi i\,\cdot)}\mathcal O_X^*\longrightarrow0.
\]
Its long exact sequence gives
\[
H^1(X,\mathcal O_X)\to \operatorname{Pic}X
\to H^2(X,\mathbb Z)\to H^2(X,\mathcal O_X),
\]
and $\operatorname{Pic}X\simeq H^1(X,\mathcal O_X^*)$.  For a curve of genus
$g$, $H^1(X,\mathcal O_X)\simeq\CC^g$ and
$\operatorname{Pic}^0(X)\simeq\CC^g/\mathbb Z^{2g}$, the Jacobian.
\end{construction}

\label{app:hartshorne-weil}



\section{The Zeta Function and the Weil Conjectures}
\label{ha-appC-sec1}
\source{hartshorne-algebraic-geometry:C.1}

\begin{definition}[Zeta function of a variety over a finite field]
\source{hartshorne-algebraic-geometry:C.1}
Let $k=\mathbb F_q$, let $X$ be of finite type over $k$, and put
$N_r=\#X(\mathbb F_{q^r})$.  Define
\[
Z(X,t)=\exp\left(\sum_{r\ge1}N_r\frac{t^r}{r}\right)\in\mathbb Q[[t]].
\]
\end{definition}

\begin{conjecture}[Weil rationality]
\label{ha-appC-conj1-1}
\source{hartshorne-algebraic-geometry:C.1.1}
\dcref{C.1.1}
For smooth projective $X/k$ of dimension $n$, $Z(X,t)$ is rational.
\end{conjecture}

\begin{conjecture}[Weil functional equation]
\label{ha-appC-conj1-2}
\source{hartshorne-algebraic-geometry:C.1.2}
\dcref{C.1.2}
If $E$ is the self-intersection number of a hyperplane section of $X$, then
$Z(1/(q^nt))=\pm q^{nE/2}t^E Z(t)$.
\end{conjecture}

\begin{conjecture}[Weil weights]
\label{ha-appC-conj1-3}
\source{hartshorne-algebraic-geometry:C.1.3}
\dcref{C.1.3}
There are integer polynomials $P_i(t)$, with $P_0(t)=1-t$ and
$P_{2n}(t)=1-q^nt$, such that
$Z(t)=P_1(t)P_3(t)\cdots P_{2n-1}(t)/(P_0(t)P_2(t)\cdots P_{2n}(t))$,
and every reciprocal root of $P_i$ is an algebraic integer of absolute value
$q^{i/2}$.
\end{conjecture}

\begin{conjecture}[Betti numbers]
\label{ha-appC-conj1-4}
\source{hartshorne-algebraic-geometry:C.1.4}
\dcref{C.1.4}
Assuming C.1.3, $B_i=\deg P_i$ are the Betti numbers and
$E=\sum_i(-1)^iB_i$; these agree with the topological Betti numbers when
$X$ is lifted to characteristic zero.
\end{conjecture}

\section{History of Work on the Weil Conjectures}
\label{ha-appC-sec2}
\source{hartshorne-algebraic-geometry:C.2}

The curve case was proved by Weil using correspondences and Jacobians; the
higher-dimensional rationality and functional equation were proved by Dwork.
The search for a characteristic-$p$ cohomology with characteristic-zero
coefficients led to étale and $\ell$-adic cohomology, and Deligne proved the
weight assertion in 1973.

\section{The $\ell$-adic Cohomology}
\label{ha-appC-sec3}
\source{hartshorne-algebraic-geometry:C.3}

\begin{definition}[Etale cohomology and Frobenius data]
\source{hartshorne-algebraic-geometry:C.3}
Fix $\ell\ne\operatorname{char}k$.  For $X$ over $k$ write
\[
H^i(X,\mathbb Q_\ell)=
\left(\varprojlim_m H^i_{\acute et}(X,\mathbb Z/\ell^m)\right)\otimes_{\mathbb Z_\ell}\mathbb Q_\ell.
\]
For a smooth projective $X/\mathbb F_q$, let $F:X\to X$ be Frobenius; its
fixed points satisfy $\operatorname{Fix}(F^r)=X(\mathbb F_{q^r})$.
\end{definition}
\begin{convention}[Finite-dimensionality]
\label{ha-appC-prop3-1}
\source{hartshorne-algebraic-geometry:C.3.1}
\dcref{C.3.1}
$H^i(X,\mathbb Q_\ell)$ is finite-dimensional and vanishes for $i<0$ and
$i>2n$ when $\dim X=n$.
\end{convention}

\begin{convention}[Contravariance]
\label{ha-appC-prop3-2}
\source{hartshorne-algebraic-geometry:C.3.2}
\dcref{C.3.2}
$H^i(-,\mathbb Q_\ell)$ is contravariant in $X$.
\end{convention}

\begin{convention}[Cup product]
\label{ha-appC-prop3-3}
\source{hartshorne-algebraic-geometry:C.3.3}
\dcref{C.3.3}
There is a cup product
$H^i(X,\mathbb Q_\ell)\otimes H^j(X,\mathbb Q_\ell)\to H^{i+j}(X,\mathbb Q_\ell)$.
\end{convention}

\begin{convention}[Poincare duality]
\label{ha-appC-prop3-4}
\source{hartshorne-algebraic-geometry:C.3.4}
\dcref{C.3.4}
If $X$ is smooth proper of dimension $n$, $H^{2n}(X,\mathbb Q_\ell)$ is
one-dimensional and cup product gives a perfect pairing
$H^i(X)\times H^{2n-i}(X)\to H^{2n}(X)$.
\end{convention}

\begin{convention}[Lefschetz fixed point formula]
\label{ha-appC-prop3-5}
\source{hartshorne-algebraic-geometry:C.3.5}
\dcref{C.3.5}
If $f:X\to X$ has isolated multiplicity-one fixed points, then
$L(f,X)=\sum_i(-1)^i\operatorname{Tr}(f^*;H^i(X,\mathbb Q_\ell))$.
\end{convention}

\begin{convention}[Smooth proper base change]
\label{ha-appC-prop3-6}
\source{hartshorne-algebraic-geometry:C.3.6}
\dcref{C.3.6}
For a smooth proper morphism with connected base, $\dim H^i(X_y,\mathbb Q_\ell)$
is constant; in particular it is invariant under finite-field extension.
\end{convention}

\begin{convention}[Comparison over the complex numbers]
\label{ha-appC-prop3-7}
\source{hartshorne-algebraic-geometry:C.3.7}
\dcref{C.3.7}
For smooth proper $X/\CC$,
$H^i(X,\mathbb Q_\ell)\otimes_{\mathbb Q_\ell}\CC\simeq H^i(X_h,\CC)$.
\end{convention}

\begin{convention}[Cycle classes]
\label{ha-appC-prop3-8}
\source{hartshorne-algebraic-geometry:C.3.8}
\dcref{C.3.8}
A codimension-$q$ cycle has a class $\eta(Z)\in H^{2q}(X,\mathbb Q_\ell)$;
rational equivalence is killed, intersections map to cup products, and the
class of a closed point is nonzero.
\end{convention}

\section{Cohomological Interpretation of the Weil Conjectures}
\label{ha-appC-sec4}
\source{hartshorne-algebraic-geometry:C.4}

Let $X/\mathbb F_q$ be smooth projective and let $F:X\to X$ be Frobenius.
The fixed points of $F^r$ are exactly $X(\mathbb F_{q^r})$, so by 3.5,
\[
N_r=\sum_{i=0}^{2n}(-1)^i\operatorname{Tr}(F^{r*};H^i(X,\mathbb Q_\ell)).
\]

\begin{lemma}[Determinant identity]
\label{ha-appC-lem4-1}
\dcref{C.4.1}
For an endomorphism $\varphi$ of a finite-dimensional vector space $V$,
\[
\exp\left(\sum_{r\ge1}\operatorname{Tr}(\varphi^r;V)\frac{t^r}{r}\right)
=\det(1-t\varphi;V)^{-1}.
\]
\source{hartshorne-algebraic-geometry:C.4.1}
\end{lemma}

\begin{proof}
For $\dim V=1$ this is the geometric-series identity.  Induct on dimension
using an invariant subspace and the resulting short exact sequence; traces and
determinants are additive and multiplicative, respectively.
\end{proof}



\begin{theorem}[Cohomological zeta formula]
\label{ha-appC-thm4-2}
\dcref{C.4.2}
Put $P_i(t)=\det(1-tF^*;H^i(X,\mathbb Q_\ell))$.  Then
\[
Z(X,t)=\prod_{i=0}^{2n}P_i(t)^{(-1)^{i+1}}.
\]
Consequently $Z(X,t)$ is rational.  Moreover $P_0(t)=1-t$ and
$P_{2n}(t)=1-q^nt$.
\source{hartshorne-algebraic-geometry:C.4.2}
\uses{ha-appC-lem4-1}
\end{theorem}
\begin{proof}
Insert the Lefschetz trace expression for $N_r$ into the definition of $Z$ and
apply Lemma 4.1 to each cohomological degree.  The Frobenius acts as the
identity on $H^0$, while it acts as multiplication by $q^n$ on the one-
dimensional top cohomology, giving the two displayed endpoint factors.
\end{proof}

\begin{lemma}[Perfect-pairing determinant identity]
\label{ha-appC-lem4-3}
\dcref{C.4.3}
If $V\times W\to K$ is a perfect pairing and endomorphisms $\varphi,\psi$
satisfy $\langle\varphi v,\psi w\rangle=\lambda\langle v,w\rangle$,
then
\[
\det(1-t\psi;W)=(-1)^rt^r\lambda^r
\frac{\det(1-(\lambda t)^{-1}\varphi;V)}{\det(\varphi;V)}.
\]
\source{hartshorne-algebraic-geometry:C.4.3}

\end{lemma}
\begin{proof}
Choose dual bases for the perfect pairing.  The relation
$\langle\varphi v,\psi w\rangle=\lambda\langle v,w\rangle$ says that the matrix of $\psi$ is
$\lambda$ times the inverse transpose of the matrix of $\varphi$.  Taking determinants of
$1-t\psi$ and clearing powers of $t$ gives the displayed identity.
\end{proof}

\begin{theorem}[Functional equation]
\label{ha-appC-thm4-4}
\dcref{C.4.4}
Under the hypotheses of Theorem 4.2,
\[
Z(1/(q^nt))=\pm q^{nE/2}t^E Z(t),
\qquad E=\sum_i(-1)^i\dim H^i(X,\mathbb Q_\ell).
\]
\source{hartshorne-algebraic-geometry:C.4.4}
\uses{ha-appC-thm4-2,ha-appC-lem4-3}
\end{theorem}

\begin{proof}
Apply Poincaré duality to pair $H^i$ with $H^{2n-i}$ and use Lemma 4.3
to relate the corresponding characteristic polynomials.  Substitution in the
product of Theorem 4.2 yields the stated equation, with the sign determined by
the determinants.
\end{proof}



\begin{theorem}[Deligne's theorem]
\label{ha-appC-thm4-5}
\dcref{C.4.5}
The reciprocal roots of each $P_i(t)$ are algebraic integers $\alpha_{ij}$
with $|\alpha_{ij}|=q^{i/2}$.  Hence the Weil conjectures all hold.
\source{hartshorne-algebraic-geometry:C.4.5}
\end{theorem}
\begin{proof}
This is Deligne's theorem, cited in the source; the source explicitly does not
give its proof.  It supplies the algebraic-integrality and absolute-value
assertions for the Frobenius reciprocal roots.
\end{proof}
